@font-face {
  font-family: 'Space Grotesk';
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}

:root{
  --black:#000000;
  --panel:#0b0b0b;
  --panel-2:#131313;
  --panel-3:#1a1a1a;
  --line:#262626;
  --line-bright:#3d3d3d;
  --white:#ffffff;
  --fg:#eaeaea;
  --fg-dim:#8f8f8f;
  --fg-faint:#525252;
  --font-display:'Space Grotesk', sans-serif;
  --font-mono:'JetBrains Mono', monospace;

  /* Signal Protocol — the only color permitted anywhere in this UI besides
     pure white/black. Desaturated so they read as terminal-appropriate
     status indicators, not decoration. */
  --signal-green:#4c9a5a;
  --signal-red:#b8564f;
  --signal-amber:#c99a3f;
}
*{box-sizing:border-box; margin:0; padding:0;}
html,body{
  background:var(--black);
  color:var(--fg);
  font-family:var(--font-display);
  height:100%;
  overflow-x:hidden;
}
::selection{background:var(--white); color:var(--black);}
button, input{font-family:inherit; color:inherit;}
button{cursor:pointer;}
:focus-visible{outline:2px solid var(--white); outline-offset:2px;}

.terminal{
  display:flex;
  flex-direction:column;
  min-height:100vh;
}

/* ---------- TOP BAR ---------- */
.topbar{
  display:flex;
  align-items:center;
  gap:20px;
  padding:12px 20px;
  border-bottom:1px solid var(--line);
  background:var(--panel);
  flex-wrap:wrap;
}
.brand{
  display:flex;
  align-items:center;
  gap:12px;
  flex-shrink:0;
}
.brand img{
  width:34px; height:34px;
  display:block;
}
.brand .wordmark{
  font-family:var(--font-mono);
  font-weight:700;
  font-size:15px;
  letter-spacing:0.18em;
  color:var(--white);
}
.brand .wordmark span{color:var(--fg-dim); font-weight:400;}

.cmdbar{
  flex:1;
  min-width:220px;
  display:flex;
  align-items:center;
  background:var(--black);
  border:1px solid var(--line-bright);
  padding:8px 14px;
  gap:8px;
  max-width:520px;
}
.cmdbar .prompt{
  font-family:var(--font-mono);
  color:var(--fg-faint);
  font-size:13px;
}
.cmdbar input{
  flex:1;
  background:transparent;
  border:none;
  font-family:var(--font-mono);
  font-size:13px;
  color:var(--white);
  text-transform:uppercase;
  letter-spacing:0.05em;
}
.cmdbar input::placeholder{color:var(--fg-faint); text-transform:none; letter-spacing:normal;}
.cmdbar .hint{
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg-faint);
  white-space:nowrap;
}

.lang-toggle{
  display:flex;
  border:1px solid var(--line-bright);
  flex-shrink:0;
}
.lang-btn{
  background:transparent;
  border:none;
  padding:6px 11px;
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.04em;
  color:var(--fg-dim);
}
.lang-btn+.lang-btn{border-left:1px solid var(--line-bright);}
.lang-btn:hover{color:var(--white);}
.lang-btn.active{background:var(--white); color:var(--black);}

.clock{
  font-family:var(--font-mono);
  font-size:13px;
  color:var(--fg-dim);
  text-align:right;
  flex-shrink:0;
}
.clock .date{color:var(--fg-faint); font-size:11px;}

/* ---------- TICKER ---------- */
.ticker-wrap{
  border-bottom:1px solid var(--line);
  background:var(--black);
  overflow:hidden;
  height:30px;
  display:flex;
  align-items:center;
  position:relative;
}
.ticker-track{
  display:flex;
  white-space:nowrap;
  will-change:transform;
}
.ticker-item{
  font-family:var(--font-mono);
  font-size:12px;
  color:var(--fg-dim);
  padding:0 22px;
  border-right:1px solid var(--line);
  display:flex;
  align-items:center;
  gap:8px;
}
.ticker-item .rk{color:var(--white); font-weight:700;}

/* ---------- TABS ---------- */
.tabs{
  display:flex;
  flex-wrap:wrap;
  border-bottom:1px solid var(--line);
  background:var(--panel);
}
.tab{
  background:transparent;
  border:none;
  border-right:1px solid var(--line);
  padding:10px 10px;
  font-family:var(--font-display);
  font-weight:600;
  font-size:13px;
  letter-spacing:0.04em;
  color:var(--fg-dim);
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  gap:2px;
  transition:background 0.15s ease, color 0.15s ease;
  flex:1 1 0;
  min-width:0;
  overflow:hidden;
}
.tab .tab-label{
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  max-width:100%;
}
.tab:hover{background:var(--panel-2); color:var(--fg);}
.tab.active{
  background:var(--white);
  color:var(--black);
}

/* ---------- MAIN ---------- */
.main{
  flex:1;
  display:grid;
  grid-template-columns:300px 1fr;
  min-height:0;
}
.sidebar{
  border-right:1px solid var(--line);
  background:var(--panel);
  overflow-y:auto;
  max-height:calc(100vh - 200px);
}
.sidebar-label{
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg-faint);
  letter-spacing:0.12em;
  padding:14px 18px 8px;
}
.filter-glyph{
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:3px;
  width:26px;
  flex-shrink:0;
  border-right:1px solid var(--line-bright);
}
.filter-glyph span{display:block; height:1px; background:var(--fg-faint);}
.filter-glyph span:nth-child(1){width:14px;}
.filter-glyph span:nth-child(2){width:9px;}
.filter-glyph span:nth-child(3){width:4px;}
.sidebar-filter{
  display:flex;
  align-items:stretch;
  margin:0 18px 10px;
  border:1px solid var(--line-bright);
}
.sidebar-filter input{
  flex:1;
  min-width:0;
  background:var(--black);
  border:none;
  padding:7px 10px;
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--white);
}
.sidebar-filter input::placeholder{color:var(--fg-faint);}
.feat-item{
  width:100%;
  text-align:left;
  background:transparent;
  border:none;
  border-bottom:1px solid var(--line);
  padding:12px 18px;
  display:flex;
  align-items:baseline;
  gap:12px;
  transition:background 0.12s ease;
}
.feat-item:hover{background:var(--panel-2);}
.feat-item.active{background:var(--panel-3); border-left:3px solid var(--white); padding-left:15px;}
.feat-item .num{
  font-family:var(--font-mono);
  font-size:12px;
  color:var(--fg-faint);
  flex-shrink:0;
  width:20px;
}
.feat-item.active .num{color:var(--white);}
.feat-item .label{
  font-size:13px;
  color:var(--fg);
  line-height:1.3;
}
.feat-item.active .label{color:var(--white); font-weight:600;}

/* Bucketed sidebar sections — group features under professional category
   headers instead of one flat ranked list. */
.sidebar-group{ border-bottom:1px solid var(--line); }
.sidebar-group:last-child{ border-bottom:none; }
.sidebar-group-label{
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.14em;
  color:var(--fg-faint);
  text-transform:uppercase;
  padding:12px 18px 7px;
  background:var(--panel-2);
  border-top:1px solid var(--line);
  position:sticky;
  top:0;
  z-index:2;
}
.sidebar-group:first-child .sidebar-group-label{ border-top:none; }
.sidebar-group .feat-item{ border-bottom:1px solid var(--line); }
.sidebar-group .feat-item:last-child{ border-bottom:none; }

.detail{
  padding:28px 36px;
  overflow-y:auto;
  max-height:calc(100vh - 200px);
}
.detail-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:20px;
  border-bottom:1px solid var(--line);
  padding-bottom:18px;
  margin-bottom:20px;
  flex-wrap:wrap;
}
.detail-head .rank-badge{
  font-family:var(--font-mono);
  font-size:34px;
  font-weight:700;
  color:var(--fg-faint);
  line-height:1;
}
.detail-title-block{display:flex; gap:16px; align-items:flex-start;}
.detail-title{
  font-size:24px;
  font-weight:700;
  color:var(--white);
  line-height:1.25;
  max-width:640px;
}
.tags{display:flex; gap:8px; margin-top:10px; flex-wrap:wrap;}
.tag{
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.08em;
  padding:4px 9px;
  border:1px solid var(--line-bright);
  color:var(--fg-dim);
}
.tag.unique{border-color:var(--white); color:var(--white);}

.section-label{
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.14em;
  color:var(--fg-faint);
  margin-bottom:8px;
  margin-top:22px;
}
.body-text{
  font-size:15px;
  line-height:1.65;
  color:var(--fg);
  max-width:760px;
}
.callout{
  border-left:2px solid var(--white);
  background:var(--panel-2);
  padding:14px 18px;
  font-size:14px;
  line-height:1.6;
  color:var(--fg-dim);
  max-width:760px;
}

/* ---------- TOOLBAR (filter / export / Studio) ---------- */
.toolbar{
  display:flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
  margin-top:22px;
  padding-bottom:16px;
  border-bottom:1px solid var(--line);
  max-width:900px;
}
.filter-group{
  flex:1;
  min-width:200px;
  display:flex;
  align-items:stretch;
  border:1px solid var(--line-bright);
}
.filter-group .filter-glyph{border-right:1px solid var(--line-bright);}
.filter-group:focus-within{border-color:var(--white);}
.filter-group:focus-within .filter-glyph{border-color:var(--white);}
.filter-group:focus-within .filter-glyph span{background:var(--white);}
.filter-input{
  flex:1;
  min-width:0;
  background:var(--black);
  border:none;
  padding:8px 12px;
  font-family:var(--font-mono);
  font-size:12px;
  color:var(--white);
}
.filter-input::placeholder{color:var(--fg-faint);}
.filter-input:disabled{color:var(--fg-faint); cursor:not-allowed;}
.filter-group:has(.filter-input:disabled){border-color:var(--line);}
.filter-group:has(.filter-input:disabled) .filter-glyph{border-right-color:var(--line);}
.column-filters{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  width:100%;
}
.column-filter-select{
  appearance:none;
  background:var(--black);
  border:1px solid var(--line-bright);
  padding:7px 26px 7px 10px;
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.02em;
  color:var(--fg-dim);
  background-image:linear-gradient(45deg, transparent 50%, var(--fg-faint) 50%), linear-gradient(135deg, var(--fg-faint) 50%, transparent 50%);
  background-position:calc(100% - 14px) center, calc(100% - 9px) center;
  background-size:5px 5px, 5px 5px;
  background-repeat:no-repeat;
}
.column-filter-select:hover{color:var(--white); border-color:var(--white);}
.toolbar-btn{
  background:transparent;
  border:1px solid var(--line-bright);
  padding:8px 14px;
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.04em;
  color:var(--fg-dim);
  white-space:nowrap;
  transition:background 0.15s ease, color 0.15s ease;
}
.toolbar-btn:hover:not(:disabled){background:var(--panel-3); color:var(--white); border-color:var(--white);}
.toolbar-btn:disabled{color:var(--fg-faint); border-color:var(--line); cursor:not-allowed;}
.toolbar-msg{
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg-faint);
  min-height:14px;
  margin-top:6px;
}

table.sample{
  margin-top:10px;
  border-collapse:collapse;
  table-layout:auto;
  width:auto;
  min-width:100%;
}
table.sample caption{
  text-align:left;
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.1em;
  color:var(--fg-faint);
  padding-bottom:6px;
}
table.sample th{
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.05em;
  text-align:left;
  color:var(--fg-dim);
  border-bottom:1px solid var(--line-bright);
  padding:8px 14px 8px 0;
  font-weight:500;
}
table.sample td{
  font-family:var(--font-mono);
  font-size:13px;
  color:var(--fg);
  border-bottom:1px solid var(--line);
  padding:10px 14px 10px 0;
  max-width:560px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
table.sample td a{color:var(--fg); text-decoration:underline; text-decoration-color:var(--fg-faint);}
table.sample td a:hover{color:var(--white);}

/* ---------- EXPANDABLE ROW / ANALYSIS ACCORDION ---------- */
/* Used only by features whose dataSource sets `expandable` (currently the
   Bill Passage Probability Index) — an inline accordion, not a modal, that
   stays in-flow within the scrollable feed. */
tr.expandable-row{cursor:pointer;}
tr.expandable-row:hover{background:var(--panel-2);}
tr.expandable-row .expand-chevron{
  display:inline-block;
  width:10px;
  font-family:var(--font-mono);
  color:var(--fg-faint);
  transition:transform 0.12s ease;
}
tr.expandable-row.expanded .expand-chevron{transform:rotate(90deg);}
tr.expandable-row.expanded{background:var(--panel-2);}
tr.expand-panel-row > td{
  background:var(--panel-2);
  border-bottom:1px solid var(--line-bright);
  padding:0;
  white-space:normal;
}
.bill-panel{padding:16px 14px 18px;}
.bill-panel .status-line{
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg-dim);
  margin-bottom:12px;
}
.bill-panel .stat-cards{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(180px, 1fr));
  gap:10px;
  margin-bottom:14px;
}
.bill-panel .stat-card{
  border:1px solid var(--line-bright);
  background:var(--black);
  padding:10px 12px;
}
.bill-panel .stat-card .stat-label{
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.08em;
  color:var(--fg-faint);
  margin-bottom:6px;
}
.bill-panel .stat-card .stat-value{
  font-size:20px;
  font-weight:700;
  color:var(--white);
  line-height:1.2;
}
.bill-panel .stat-card .stat-value.pending{
  font-size:12px;
  font-weight:400;
  color:var(--fg-faint);
  font-style:italic;
}
.bill-panel .stat-card .stat-note{
  font-size:11px;
  color:var(--fg-dim);
  line-height:1.5;
  margin-top:6px;
}
.bill-panel .stat-card .info-link{margin-top:8px; font-size:10px;}
/* Gauge bar — reuses the Signal Protocol's green/amber/red, the one color
   permitted anywhere in this UI, so the probability/precedent visual reads
   as consistent with the dots and arrows used everywhere else. */
.gauge{margin-top:8px;}
.gauge-track{height:8px; background:var(--line); position:relative; overflow:hidden;}
.gauge-fill{height:100%; transition:width 0.2s ease;}
.gauge-fill.gauge-green{background:var(--signal-green);}
.gauge-fill.gauge-amber{background:var(--signal-amber);}
.gauge-fill.gauge-red{background:var(--signal-red);}
.bill-panel .pill-row{display:flex; flex-wrap:wrap; gap:6px; margin-bottom:10px;}
.bill-panel .pill-row-label{
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.08em;
  color:var(--fg-faint);
  margin-bottom:6px;
}
/* Sectors: filled/inverted — reads as the primary, "accented" pill role
   ("teal-style" in the brief) using only the existing white/black tokens,
   never a new color. */
.pill-sector{
  font-family:var(--font-mono);
  font-size:10px;
  padding:4px 9px;
  background:var(--white);
  color:var(--black);
}
/* Key terms: outlined neutral-gray — visually distinct from sectors without
   any new color token, matching the existing .tag treatment. */
.pill-keyterm{
  font-family:var(--font-mono);
  font-size:10px;
  padding:4px 9px;
  border:1px solid var(--line-bright);
  color:var(--fg-dim);
}
.bill-panel .body-text{margin-bottom:12px; max-width:none;}
.bill-panel .detail-list{
  list-style:none;
  margin:0 0 14px;
  padding:0;
  display:flex;
  flex-direction:column;
  gap:6px;
}
.bill-panel .detail-list li{
  font-size:12px;
  line-height:1.5;
  color:var(--fg-dim);
  padding-left:14px;
  position:relative;
}
.bill-panel .detail-list li::before{
  content:"—";
  position:absolute;
  left:0;
  color:var(--fg-faint);
}
.bill-panel .category-badge{
  display:inline-block;
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.06em;
  padding:3px 8px;
  border:1px solid var(--line-bright);
  color:var(--fg-dim);
  margin-bottom:10px;
}
.wealth-row{display:flex; align-items:center; gap:8px; margin-top:6px;}
.wealth-row .wealth-year{
  font-family:var(--font-mono);
  font-size:10px;
  color:var(--fg-faint);
  width:32px;
  flex-shrink:0;
}
.wealth-row .gauge-track{flex:1;}
.wealth-row .wealth-amt{
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg);
  width:70px;
  flex-shrink:0;
  text-align:right;
}
.bill-panel .pending-note{
  font-size:12px;
  color:var(--fg-faint);
  font-style:italic;
}
.bill-panel .stance-bars{display:flex; flex-direction:column; gap:6px;}
.bill-panel .stance-bar-row{display:flex; align-items:center; gap:8px; font-size:12px;}
.bill-panel .stance-bar-row .stance-who{width:140px; flex-shrink:0; color:var(--fg-dim);}
.bill-panel .stance-bar-track{flex:1; height:6px; background:var(--line); position:relative;}
.bill-panel .stance-bar-fill{height:100%; background:var(--fg-dim);}
.bill-panel .stance-bar-row.stance-supportive .stance-bar-fill{background:var(--signal-green);}
.bill-panel .stance-bar-row.stance-opposed .stance-bar-fill{background:var(--signal-red);}
.bill-panel .stance-bar-row.stance-mixed .stance-bar-fill{background:var(--signal-amber);}

.bill-panel .coverage-list{display:flex; flex-direction:column; gap:8px; margin-top:2px;}
.coverage-item{
  display:flex;
  flex-direction:column;
  gap:2px;
  padding:8px 10px;
  border:1px solid var(--line-bright);
  text-decoration:none;
}
.coverage-item:hover{border-color:var(--white);}
.coverage-item .coverage-title{
  font-size:12px;
  color:var(--fg);
  line-height:1.4;
}
.coverage-item:hover .coverage-title{color:var(--white);}
.coverage-item .coverage-source{
  font-family:var(--font-mono);
  font-size:10px;
  color:var(--fg-faint);
}

/* ---------- SIGNAL PROTOCOL ---------- */
/* Dots/arrows are the only color in this UI besides pure white — never
   recolor a whole row or any chrome element. */
.dot{
  display:inline-block;
  width:7px; height:7px;
  border-radius:50%;
  margin-right:7px;
  flex-shrink:0;
  vertical-align:middle;
}
.dot-green{background:var(--signal-green);}
.dot-red{background:var(--signal-red);}
.dot-amber{background:var(--signal-amber);}

.trend-arrow{
  font-family:var(--font-mono);
  font-weight:700;
  margin-right:5px;
}
.trend-green{color:var(--signal-green);}
.trend-red{color:var(--signal-red);}
.trend-amber{color:var(--signal-amber);}

.badge-unofficial{
  display:inline-block;
  font-family:var(--font-mono);
  font-size:9px;
  letter-spacing:0.06em;
  padding:1px 5px;
  margin-right:6px;
  border:1px solid var(--signal-amber);
  color:var(--signal-amber);
  vertical-align:middle;
}

.feat-item .dot{margin-right:6px;}

.signal-legend{
  font-family:var(--font-mono);
  font-size:10px;
  color:var(--fg-faint);
  display:flex;
  align-items:center;
  gap:4px;
  cursor:help;
}
.signal-legend .dot{margin-right:3px;}

.empty-state{
  margin-top:10px;
  border:1px dashed var(--line-bright);
  padding:24px 20px;
  max-width:760px;
  color:var(--fg-dim);
  font-size:13px;
  line-height:1.6;
}
.empty-state .headline{
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.1em;
  color:var(--fg-faint);
  margin-bottom:8px;
}

/* ---------- STATUS BAR ---------- */
.statusbar{
  display:flex;
  align-items:center;
  gap:14px;
  padding:9px 20px;
  border-top:1px solid var(--line);
  background:var(--panel);
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg-faint);
  flex-wrap:wrap;
}
.live-dot{
  width:7px; height:7px;
  border-radius:50%;
  background:var(--white);
  animation:blink 1.6s ease-in-out infinite;
  flex-shrink:0;
}
@keyframes blink{0%,100%{opacity:1;} 50%{opacity:0.25;}}
.statusbar .sep{color:var(--line-bright);}
.statusbar .breadcrumb{color:var(--fg-dim);}

/* ---------- INFO LINK + MODAL ---------- */
/* Replaces the old always-visible callout box under every table — full
   source/methodology text now lives one click away instead of dominating
   the customer-facing view by default. */
.info-link{
  background:transparent;
  border:none;
  padding:0;
  margin-top:10px;
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg-faint);
  text-decoration:underline;
  text-decoration-color:var(--line-bright);
}
.info-link:hover{color:var(--fg-dim); text-decoration-color:var(--fg-dim);}
.modal-overlay{
  position:fixed;
  inset:0;
  background:rgba(0,0,0,0.7);
  display:flex;
  align-items:center;
  justify-content:center;
  z-index:1000;
  padding:24px;
}
.modal-overlay[hidden]{display:none;}
.modal-box{
  background:var(--panel);
  border:1px solid var(--line-bright);
  max-width:640px;
  width:100%;
  max-height:80vh;
  display:flex;
  flex-direction:column;
}
.modal-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:16px 20px;
  border-bottom:1px solid var(--line);
}
.modal-title{
  font-family:var(--font-mono);
  font-size:12px;
  letter-spacing:0.06em;
  color:var(--white);
}
.modal-close{
  background:transparent;
  border:1px solid var(--line-bright);
  color:var(--fg-dim);
  width:26px; height:26px;
  font-size:16px;
  line-height:1;
  flex-shrink:0;
}
.modal-close:hover{color:var(--white); border-color:var(--white);}
.modal-body{
  padding:18px 20px 22px;
  overflow-y:auto;
  font-size:13px;
  line-height:1.65;
  color:var(--fg-dim);
}
.modal-body p+p{margin-top:10px;}

/* ---------- RESPONSIVE ---------- */
@media (max-width: 860px){
  .main{grid-template-columns:1fr;}
  .sidebar{max-height:260px; border-right:none; border-bottom:1px solid var(--line);}
  .detail{max-height:none;}
  .cmdbar{order:3; max-width:none; width:100%;}
  .clock{order:2;}
  .lang-toggle{order:1;}
  .tab{padding:12px 16px; font-size:13px;}
}
@media (prefers-reduced-motion: reduce){
  .live-dot{animation:none;}
}

/* ================================================================
   LIGHT THEME — toggled via [data-theme="light"] on <html>. Same
   structure/spacing as dark, only the palette flips.
   ================================================================ */
html[data-theme="light"]{
  --black:#f5f5f3;
  --panel:#ffffff;
  --panel-2:#eeeeec;
  --panel-3:#e4e4e1;
  --line:#d8d8d4;
  --line-bright:#b7b7b1;
  --white:#0a0a0a;
  --fg:#1c1c1a;
  --fg-dim:#54544f;
  --fg-faint:#83837c;
}
html[data-theme="light"] ::selection{background:var(--black); color:var(--white);}
/* The brain-mark logo is drawn near-white on a transparent background —
   invisible once the panel behind it turns light. Inverting a grayscale
   image just swaps light<->dark, so this restores contrast cleanly. */
html[data-theme="light"] .brand img{filter:invert(1);}

/* ================================================================
   LOGIN SCREEN
   ================================================================ */
body.locked .terminal,
body.locked .modal-overlay{display:none;}
#loginScreen{display:none;}
body.locked #loginScreen{display:flex;}
#loginScreen{
  min-height:100vh;
  align-items:center;
  justify-content:center;
  background:var(--black);
  padding:24px;
}
.login-box{
  width:100%;
  max-width:380px;
  border:1px solid var(--line-bright);
  background:var(--panel);
  padding:36px 32px;
}
.login-box .brand{margin-bottom:26px; justify-content:center;}
.login-box .wordmark{font-size:16px;}
.login-title{
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.14em;
  color:var(--fg-faint);
  margin-bottom:20px;
  text-align:center;
}
.login-field{margin-bottom:14px;}
.login-field label{
  display:block;
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.1em;
  color:var(--fg-faint);
  margin-bottom:6px;
}
.login-field input{
  width:100%;
  background:var(--black);
  border:1px solid var(--line-bright);
  color:var(--white);
  padding:10px 12px;
  font-family:var(--font-mono);
  font-size:13px;
}
.login-field input:focus-visible{border-color:var(--white);}
.login-submit{
  width:100%;
  margin-top:8px;
  background:var(--white);
  color:var(--black);
  border:none;
  padding:11px;
  font-family:var(--font-mono);
  font-weight:700;
  font-size:12px;
  letter-spacing:0.1em;
}
.login-submit:hover{opacity:0.85;}
.login-error{
  min-height:16px;
  margin-top:12px;
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--signal-red);
  text-align:center;
}
.login-hint{
  margin-top:18px;
  font-family:var(--font-mono);
  font-size:10px;
  color:var(--fg-faint);
  text-align:center;
  line-height:1.6;
}

/* ================================================================
   PROFILE MENU
   ================================================================ */
.profile-wrap{position:relative; flex-shrink:0;}
.profile-btn{
  width:34px; height:34px;
  border:1px solid var(--line-bright);
  background:var(--panel-2);
  color:var(--fg-dim);
  display:flex;
  align-items:center;
  justify-content:center;
  font-family:var(--font-mono);
  font-size:12px;
  font-weight:700;
  border-radius:50%;
}
.profile-btn:hover{color:var(--white); border-color:var(--white);}
.profile-menu{
  position:absolute;
  top:calc(100% + 8px);
  right:0;
  min-width:230px;
  background:var(--panel);
  border:1px solid var(--line-bright);
  z-index:900;
  padding:6px;
}
.profile-menu[hidden]{display:none;}
.profile-menu-section{padding:8px 10px 4px;}
.profile-menu-label{
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.1em;
  color:var(--fg-faint);
}
.profile-menu-item{
  width:100%;
  text-align:left;
  background:transparent;
  border:none;
  padding:9px 10px;
  font-size:13px;
  color:var(--fg);
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}
.profile-menu-item:hover{background:var(--panel-2);}
.theme-toggle{
  display:flex;
  border:1px solid var(--line-bright);
}
.theme-toggle button{
  background:transparent;
  border:none;
  padding:5px 10px;
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg-dim);
}
.theme-toggle button+button{border-left:1px solid var(--line-bright);}
.theme-toggle button.active{background:var(--white); color:var(--black);}
.profile-menu-divider{height:1px; background:var(--line); margin:6px 0;}

/* ================================================================
   SEARCH — cmdbar upgraded with live suggestions + AI mode
   ================================================================ */
.cmdbar{position:relative;}
.ai-search-btn{
  flex-shrink:0;
  background:transparent;
  border:1px solid var(--line-bright);
  color:var(--fg-dim);
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.06em;
  padding:5px 9px;
}
.ai-search-btn:hover{color:var(--white); border-color:var(--white);}
.ai-search-btn.active{background:var(--white); color:var(--black); border-color:var(--white);}
.search-suggest{
  position:absolute;
  top:calc(100% + 6px);
  left:0;
  right:0;
  background:var(--panel);
  border:1px solid var(--line-bright);
  max-height:340px;
  overflow-y:auto;
  z-index:850;
}
.search-suggest[hidden]{display:none;}
.suggest-group-label{
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.1em;
  color:var(--fg-faint);
  padding:8px 12px 4px;
}
.suggest-item{
  width:100%;
  text-align:left;
  background:transparent;
  border:none;
  padding:8px 12px;
  display:flex;
  flex-direction:column;
  gap:2px;
}
.suggest-item:hover, .suggest-item.kbd-active{background:var(--panel-2);}
.suggest-item .suggest-title{font-size:13px; color:var(--fg);}
.suggest-item .suggest-meta{font-family:var(--font-mono); font-size:10px; color:var(--fg-faint);}
.suggest-empty{padding:16px 12px; font-size:12px; color:var(--fg-faint);}
.ai-answer-panel{
  padding:14px 16px;
  border-top:1px solid var(--line);
  background:var(--panel-2);
}
.ai-answer-panel .ai-q{font-family:var(--font-mono); font-size:11px; color:var(--fg-faint); margin-bottom:8px;}
.ai-answer-panel .ai-a{font-size:13px; line-height:1.6; color:var(--fg); white-space:pre-wrap;}
.ai-answer-panel .ai-loading{font-family:var(--font-mono); font-size:11px; color:var(--fg-faint);}
.ai-offline-note{font-family:var(--font-mono); font-size:10px; color:var(--signal-amber); margin-top:8px; line-height:1.5;}

/* ================================================================
   TICKER — category-tagged live feed
   ================================================================ */
.ticker-item .cat{
  font-family:var(--font-mono);
  font-size:9px;
  font-weight:700;
  letter-spacing:0.06em;
  padding:2px 6px;
  border:1px solid var(--line-bright);
  color:var(--fg-dim);
  flex-shrink:0;
}
.ticker-item .cat-bill{border-color:var(--signal-green); color:var(--signal-green);}
.ticker-item .cat-transfer{border-color:var(--signal-amber); color:var(--signal-amber);}
.ticker-item .cat-war{border-color:var(--signal-red); color:var(--signal-red);}
.ticker-item .cat-breaking{background:var(--white); color:var(--black); border-color:var(--white);}
.ticker-item .ts{color:var(--fg-faint); margin-left:2px;}

/* ================================================================
   DATA STUDIO
   ================================================================ */
#dataStudio{display:none;}
#dataStudio.show{display:flex; flex:1; min-height:0;}

#nDesk{display:none;}
#nDesk.show{display:flex; flex:1; min-height:0;}
.ndesk-shell{display:flex; flex-direction:column; flex:1; min-height:0; width:100%; overflow-y:auto; padding:24px 28px;}
.ndesk-head{display:flex; align-items:flex-start; justify-content:space-between; gap:16px; flex-wrap:wrap; border-bottom:1px solid var(--line); padding-bottom:16px; margin-bottom:16px;}
.ndesk-title{font-size:20px; font-weight:700; color:var(--white); font-family:var(--font-display);}
.ndesk-sub{font-size:12px; color:var(--fg-dim); margin-top:3px;}
.ndesk-actions{display:flex; gap:8px; flex-shrink:0;}
.ndesk-primary{background:var(--white); color:var(--black); border-color:var(--white);}
.ndesk-primary:hover{background:var(--fg); }
.ndesk-filters{display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:20px;}
.ndesk-filters-label{font-family:var(--font-mono); font-size:10px; letter-spacing:.1em; color:var(--fg-faint); margin-right:4px;}
.ndesk-chip{font-family:var(--font-display); font-size:12px; padding:6px 12px; background:var(--panel-2); border:1px solid var(--line-bright); color:var(--fg-dim); cursor:pointer; transition:all .12s ease;}
.ndesk-chip.active{background:var(--white); color:var(--black); border-color:var(--white);}
.ndesk-feed{display:flex; flex-direction:column; gap:12px;}
.ndesk-card{border:1px solid var(--line); background:var(--panel-2); padding:16px 18px;}
.ndesk-card-head{display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:8px; flex-wrap:wrap;}
.ndesk-card-topic{font-size:14px; font-weight:600; color:var(--white);}
.ndesk-card-meta{display:flex; gap:6px; align-items:center; flex-wrap:wrap;}
.ndesk-card-tag{font-family:var(--font-mono); font-size:9px; letter-spacing:.08em; padding:3px 7px; border:1px solid var(--line-bright); color:var(--fg-faint);}
.ndesk-card-time{font-family:var(--font-mono); font-size:10px; color:var(--fg-faint);}
.ndesk-card-body{font-size:13px; line-height:1.6; color:var(--fg);}
.ndesk-empty{color:var(--fg-faint); font-size:13px; padding:40px 0; text-align:center;}
.ndesk-loading{color:var(--fg-dim); font-size:12px; font-family:var(--font-mono);}
.studio-shell{
  display:grid;
  grid-template-columns:200px 1fr;
  min-height:0;
  flex:1;
}
.studio-nav{
  border-right:1px solid var(--line);
  background:var(--panel);
  padding:14px 0;
}
.studio-nav-item{
  width:100%;
  text-align:left;
  background:transparent;
  border:none;
  border-left:3px solid transparent;
  padding:11px 18px;
  font-size:13px;
  color:var(--fg-dim);
}
.studio-nav-item:hover{background:var(--panel-2); color:var(--fg);}
.studio-nav-item.active{border-left-color:var(--white); color:var(--white); background:var(--panel-3); font-weight:600;}
.studio-body{
  padding:26px 32px;
  overflow-y:auto;
  max-height:calc(100vh - 200px);
}
.studio-pane[hidden]{display:none;}
.studio-h1{font-size:20px; font-weight:700; color:var(--white); margin-bottom:6px;}
.studio-sub{font-size:13px; color:var(--fg-dim); margin-bottom:20px; max-width:640px; line-height:1.55;}
.dataset-grid{
  display:grid;
  grid-template-columns:repeat(auto-fill, minmax(240px, 1fr));
  gap:10px;
  margin-bottom:20px;
}
.dataset-card{
  border:1px solid var(--line-bright);
  background:var(--panel-2);
  padding:14px 16px;
  display:flex;
  flex-direction:column;
  gap:8px;
}
.dataset-card .ds-name{font-size:13px; font-weight:600; color:var(--white);}
.dataset-card .ds-meta{font-family:var(--font-mono); font-size:10px; color:var(--fg-faint);}
.dataset-card .ds-actions{display:flex; gap:6px; margin-top:4px;}
.studio-stats-row{display:flex; gap:10px; flex-wrap:wrap; margin-bottom:16px;}
.studio-stat{border:1px solid var(--line-bright); background:var(--panel-2); padding:10px 14px; min-width:120px;}
.studio-stat .stat-k{font-family:var(--font-mono); font-size:10px; color:var(--fg-faint); margin-bottom:4px;}
.studio-stat .stat-v{font-size:18px; font-weight:700; color:var(--white);}
.studio-table-wrap{overflow-x:auto; max-width:100%;}
.studio-chart{width:100%; max-width:640px; height:220px; margin:14px 0;}

.upload-zone{
  border:1px dashed var(--line-bright);
  padding:26px 20px;
  text-align:center;
  color:var(--fg-dim);
  font-size:13px;
  margin-bottom:16px;
  cursor:pointer;
}
.upload-zone:hover{border-color:var(--white); color:var(--fg);}
.upload-zone.drag{border-color:var(--white); background:var(--panel-2);}
.uploaded-list{display:flex; flex-direction:column; gap:6px; margin-bottom:16px;}
.uploaded-item{
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  border:1px solid var(--line-bright); padding:8px 12px; font-size:12px;
}
.uploaded-item .uf-name{color:var(--fg);}
.uploaded-item .uf-meta{font-family:var(--font-mono); font-size:10px; color:var(--fg-faint);}
.uploaded-item button{background:transparent; border:none; color:var(--fg-faint); font-size:14px;}
.uploaded-item button:hover{color:var(--signal-red);}
.ai-report{border:1px solid var(--line-bright); background:var(--panel-2); padding:18px 20px; margin-top:16px;}
.ai-report h4{font-size:14px; color:var(--white); margin:14px 0 6px;}
.ai-report h4:first-child{margin-top:0;}
.ai-report ul{margin:0 0 10px 18px;}
.ai-report li{font-size:13px; color:var(--fg-dim); line-height:1.6; margin-bottom:4px;}
.ai-report p{font-size:13px; color:var(--fg); line-height:1.65;}

.slide-deck{display:flex; flex-direction:column; gap:16px;}
.slide{
  width:100%;
  max-width:720px;
  aspect-ratio:16/9;
  border:1px solid var(--line-bright);
  background:var(--white);
  color:var(--black);
  padding:32px 36px;
  display:flex;
  flex-direction:column;
  gap:10px;
  overflow:auto;
}
.slide .slide-title{font-size:22px; font-weight:700;}
.slide .slide-sub{font-size:12px; color:#555; font-family:var(--font-mono); letter-spacing:0.06em;}
.slide ul{margin:6px 0 0 18px;}
.slide li{font-size:14px; line-height:1.6; margin-bottom:4px;}
.template-gallery{display:grid; grid-template-columns:repeat(auto-fill, minmax(160px,1fr)); gap:12px; margin-bottom:18px;}
.template-card{border:1px solid var(--line-bright); background:var(--panel-2); padding:14px; cursor:pointer; text-align:center;}
.template-card:hover{border-color:var(--white);}
.template-card.selected{border-color:var(--white); background:var(--panel-3);}
.template-card .tpl-icon{font-size:22px; margin-bottom:6px;}
.template-card .tpl-name{font-size:12px; color:var(--fg);}

.sheet-toolbar{display:flex; gap:8px; flex-wrap:wrap; margin-bottom:14px;}
.sheet-grid-wrap{overflow:auto; border:1px solid var(--line-bright); max-height:520px;}
table.sheet{border-collapse:collapse;}
table.sheet th, table.sheet td{border:1px solid var(--line); padding:0;}
table.sheet th{
  background:var(--panel-2);
  font-family:var(--font-mono);
  font-size:11px;
  color:var(--fg-faint);
  padding:6px 8px;
  min-width:110px;
}
table.sheet td[contenteditable]{
  padding:6px 8px;
  font-size:12px;
  min-width:110px;
  outline:none;
}
table.sheet td[contenteditable]:focus{background:var(--panel-2); outline:1px solid var(--white);}
table.sheet .row-head{
  background:var(--panel-2);
  font-family:var(--font-mono);
  font-size:10px;
  color:var(--fg-faint);
  text-align:center;
  width:34px;
}

.chat-box{border:1px solid var(--line-bright); margin-top:20px;}
.chat-log{max-height:260px; overflow-y:auto; padding:12px 14px; display:flex; flex-direction:column; gap:10px;}
.chat-msg{font-size:13px; line-height:1.6;}
.chat-msg.user{color:var(--fg-dim);}
.chat-msg.user::before{content:"You — "; font-family:var(--font-mono); font-size:10px; color:var(--fg-faint);}
.chat-msg.ai{color:var(--fg); white-space:pre-wrap;}
.chat-msg.ai::before{content:"AI — "; font-family:var(--font-mono); font-size:10px; color:var(--fg-faint);}
.chat-input-row{display:flex; border-top:1px solid var(--line);}
.chat-input-row input{flex:1; background:var(--black); border:none; padding:10px 12px; font-size:13px; color:var(--white);}
.chat-input-row button{background:var(--white); color:var(--black); border:none; padding:0 18px; font-family:var(--font-mono); font-size:11px; font-weight:700;}

/* ================================================================
   BETA BADGE
   ================================================================ */
.beta-badge{
  display:inline-block;
  font-family:var(--font-mono);
  font-size:8px;
  font-weight:700;
  letter-spacing:0.08em;
  padding:1px 5px;
  margin-left:6px;
  border:1px solid var(--signal-amber);
  color:var(--signal-amber);
  vertical-align:middle;
  line-height:1.5;
}
.tab .beta-badge{margin-left:4px;}
.studio-nav-item .beta-badge{float:right;}

/* ================================================================
   LOGIN SCREEN — two-column layout matching the approved mock
   ================================================================ */
#loginScreen{
  align-items:stretch;
  padding:0;
}
.login-shell{
  display:grid;
  grid-template-columns:1.3fr 1fr;
  width:100%;
  min-height:100vh;
}
.login-art{
  background:#000 url('data:image/webp;base64,') center center / cover no-repeat;
  display:flex;
  align-items:flex-start;
  padding:56px;
}
.login-art .login-headline{
  font-family:'Press Start 2P', 'JetBrains Mono', monospace;
  font-size:clamp(18px, 2.6vw, 30px);
  font-weight:400;
  /* Fixed, not var(--white) — this panel's background image is always
     dark by design, in both themes, so the text must stay light always. */
  color:#f5f5f5;
  letter-spacing:0.01em;
  line-height:1.5;
  text-shadow:0 2px 0 rgba(0,0,0,0.6);
  max-width:640px;
}
.login-card-col{
  display:flex;
  align-items:center;
  justify-content:center;
  padding:24px;
}
@media (max-width: 860px){
  .login-shell{grid-template-columns:1fr;}
  .login-art{display:none;}
}
/* Login — full-screen hero video background + wordmark + floating sign-in card */
.login-shell{ position:relative; background:transparent; }
.login-art{ background:transparent !important; background-image:none !important; padding:0 !important; }
.login-video{ position:fixed; inset:0; width:100vw; height:100vh; object-fit:cover; z-index:0; background:#000; }
.login-veil{ position:fixed; inset:0; z-index:1; pointer-events:none; background:linear-gradient(90deg, rgba(0,0,0,.4) 0%, rgba(0,0,0,.12) 42%, rgba(0,0,0,.72) 100%); }
.login-wordmark{ position:fixed; top:8%; left:56px; z-index:2; font-family:'JetBrains Mono','Space Mono',monospace; font-weight:600; letter-spacing:.34em; font-size:clamp(26px,3.6vw,52px); color:#f2f2f2; text-shadow:0 2px 24px rgba(0,0,0,.85); }
.login-card-col{ position:relative; z-index:3; }
@media (max-width:1100px){ .login-wordmark{ left:32px; top:6%; } }
@media (max-width:860px){ .login-wordmark{ display:none; } }

/* ================================================================
   LOCATION SCOPE BAR (National/State/Local fixed-location dropdowns)
   ================================================================ */
.scope-bar{
  display:flex;
  align-items:center;
  gap:16px;
  padding:9px 20px;
  border-bottom:1px solid var(--line);
  background:var(--panel);
  flex-wrap:wrap;
}
.scope-field{display:flex; align-items:center; gap:8px;}
.scope-field label{
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.1em;
  color:var(--fg-faint);
}
.scope-field select{
  appearance:none;
  background:var(--black);
  border:1px solid var(--line-bright);
  padding:6px 24px 6px 10px;
  font-family:var(--font-mono);
  font-size:12px;
  color:var(--fg);
  background-image:linear-gradient(45deg, transparent 50%, var(--fg-faint) 50%), linear-gradient(135deg, var(--fg-faint) 50%, transparent 50%);
  background-position:calc(100% - 12px) center, calc(100% - 7px) center;
  background-size:5px 5px, 5px 5px;
  background-repeat:no-repeat;
}
.scope-field select:disabled{color:var(--fg-dim); cursor:default; opacity:0.85;}
.scope-actions{display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-left:auto;}
.scope-action-btn{
  display:flex;
  align-items:center;
  gap:6px;
  background:transparent;
  border:1px solid var(--line-bright);
  color:var(--fg-dim);
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.03em;
  padding:6px 11px;
}
.scope-action-btn:hover{color:var(--white); border-color:var(--white);}
.scope-action-btn .icon{font-size:13px; line-height:1; display:inline-flex;}
.scope-action-btn .icon svg{fill:var(--white); flex-shrink:0;}
.scope-action-wrap{position:relative;}
.scope-popover{
  position:absolute;
  top:calc(100% + 8px);
  right:0;
  min-width:240px;
  background:var(--panel);
  border:1px solid var(--line-bright);
  padding:14px;
  z-index:900;
}
.scope-popover[hidden]{display:none;}
.scope-popover label{display:block; font-family:var(--font-mono); font-size:10px; letter-spacing:0.08em; color:var(--fg-faint); margin-bottom:6px;}
.scope-popover input, .scope-popover select{
  width:100%;
  background:var(--black);
  border:1px solid var(--line-bright);
  color:var(--white);
  padding:8px 10px;
  font-family:var(--font-mono);
  font-size:12px;
  margin-bottom:10px;
}
.scope-popover .popover-row{display:flex; gap:8px;}
.scope-popover .popover-row button{flex:1;}
.category-chip-list{display:flex; flex-wrap:wrap; gap:6px; margin-bottom:10px;}
.category-chip{
  font-family:var(--font-mono);
  font-size:10px;
  padding:4px 9px;
  border:1px solid var(--line-bright);
  color:var(--fg-dim);
  background:transparent;
}
.category-chip.active{background:var(--white); color:var(--black); border-color:var(--white);}
.embed-btn{
  background:transparent;
  border:1px solid var(--line-bright);
  color:var(--fg-faint);
  font-family:var(--font-mono);
  font-size:10px;
  padding:4px 9px;
  display:inline-flex;
  align-items:center;
  gap:5px;
}
.card-actions-row{display:flex; gap:8px; flex-wrap:wrap; align-items:center;}
.card-action-btn{
  background:transparent;
  border:1px solid var(--line-bright);
  color:var(--fg-faint);
  font-family:var(--font-mono);
  font-size:10px;
  padding:4px 9px;
  display:inline-flex;
  align-items:center;
  gap:5px;
  text-decoration:none;
  cursor:pointer;
  transition:border-color .12s ease, color .12s ease;
}
.card-action-btn:hover{border-color:var(--white); color:var(--white);}
.embed-btn:hover{color:var(--white); border-color:var(--white);}
.toast{
  position:fixed;
  bottom:24px;
  left:50%;
  transform:translateX(-50%);
  background:var(--white);
  color:var(--black);
  font-family:var(--font-mono);
  font-size:12px;
  padding:10px 18px;
  z-index:1200;
  opacity:0;
  pointer-events:none;
  transition:opacity 0.2s ease;
}
.toast.show{opacity:1;}
.embed-field{margin-bottom:14px;}
.embed-field label{display:block; font-family:var(--font-mono); font-size:10px; letter-spacing:0.08em; color:var(--fg-faint); margin-bottom:6px;}
.embed-field select, .embed-field input{width:100%; background:var(--black); border:1px solid var(--line-bright); color:var(--white); padding:8px 10px; font-family:var(--font-mono); font-size:12px;}
.embed-field .row{display:flex; gap:8px;}
.embed-field .row input{flex:1;}

/* ================================================================
   TOPBAR QUICK CONTROLS — AI status pill + theme flip, filling the
   space beside the clock instead of leaving it empty.
   ================================================================ */
.quick-controls{display:flex; align-items:center; gap:10px; flex-shrink:0;}
.ai-status-pill{
  display:flex;
  align-items:center;
  gap:6px;
  font-family:var(--font-mono);
  font-size:10px;
  letter-spacing:0.06em;
  color:var(--fg-faint);
  background:transparent;
  border:1px solid var(--line-bright);
  padding:5px 10px;
  cursor:pointer;
}
.ai-status-pill:hover{color:var(--white); border-color:var(--white);}
.ai-status-pill .refresh-icon{display:inline-block; font-size:12px; line-height:1;}
.ai-status-pill.spinning .refresh-icon{animation:spin 0.6s linear infinite;}
@keyframes spin{from{transform:rotate(0deg);} to{transform:rotate(360deg);}}
.quick-theme-btn{
  width:30px; height:30px;
  border:1px solid var(--line-bright);
  background:var(--panel-2);
  color:var(--fg-dim);
  font-size:14px;
  display:flex;
  align-items:center;
  justify-content:center;
}
.quick-theme-btn:hover{color:var(--white); border-color:var(--white);}

/* ================================================================
   GLOBAL AI ASSISTANT — floating launcher, available on every tier
   ================================================================ */
#globalAiBtn{
  position:fixed;
  right:24px;
  bottom:24px;
  z-index:950;
  width:54px; height:54px;
  border-radius:50%;
  border:1px solid var(--line-bright);
  background:var(--white);
  color:var(--black);
  font-size:20px;
  display:flex;
  align-items:center;
  justify-content:center;
  box-shadow:0 4px 18px rgba(0,0,0,0.45);
}
#globalAiBtn:hover{opacity:0.88;}
body.locked #globalAiBtn{display:none;}
#globalAiDrawer{
  position:fixed;
  right:24px;
  bottom:90px;
  z-index:950;
  width:360px;
  max-height:min(560px, calc(100vh - 130px));
  background:var(--panel);
  border:1px solid var(--line-bright);
  display:flex;
  flex-direction:column;
  box-shadow:0 8px 30px rgba(0,0,0,0.5);
}
#globalAiDrawer[hidden]{display:none;}
.global-ai-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:12px 14px;
  border-bottom:1px solid var(--line);
}
.global-ai-head .title{font-size:13px; font-weight:600; color:var(--white);}
.global-ai-head .ctx{font-family:var(--font-mono); font-size:10px; color:var(--fg-faint); margin-top:2px;}
.global-ai-close{background:transparent; border:none; color:var(--fg-dim); font-size:16px;}
.global-ai-close:hover{color:var(--white);}

/* ================================================================
   DATA STUDIO — Overview pane + searchable/grouped dataset catalog
   ================================================================ */
.studio-overview-grid{display:grid; grid-template-columns:repeat(auto-fit, minmax(150px,1fr)); gap:10px; margin-bottom:22px;}
.overview-quick-actions{display:flex; gap:10px; flex-wrap:wrap; margin-bottom:24px;}
.overview-quick-actions button{
  border:1px solid var(--line-bright);
  background:var(--panel-2);
  color:var(--fg);
  padding:12px 16px;
  font-size:13px;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  gap:4px;
  min-width:150px;
}
.overview-quick-actions button:hover{border-color:var(--white);}
.overview-quick-actions button .qa-icon{font-size:16px;}
.dataset-search-row{display:flex; gap:8px; margin-bottom:16px; flex-wrap:wrap; align-items:center;}
.dataset-search-row input{
  flex:1;
  min-width:200px;
  background:var(--black);
  border:1px solid var(--line-bright);
  padding:8px 12px;
  font-family:var(--font-mono);
  font-size:12px;
  color:var(--white);
}
.dataset-group-label{
  font-family:var(--font-mono);
  font-size:11px;
  letter-spacing:0.12em;
  color:var(--fg-faint);
  margin:18px 0 8px;
  padding-top:10px;
  border-top:1px solid var(--line);
}
.dataset-group-label:first-of-type{border-top:none; padding-top:0; margin-top:0;}


/* ===== CONNECTIVE TISSUE — interaction styling ===== */
table.sample tbody tr.nx-row{ cursor:pointer; transition:background .1s ease; }
table.sample tbody tr.nx-row:hover,
table.sample tbody tr.nx-row:focus-visible{ background:var(--panel-3, #1a1a1a); outline:none; }
table.sample tbody tr.nx-row:focus-visible{ box-shadow: inset 2px 0 0 var(--white, #fff); }
table.sample tbody tr.nx-row td:first-child{ position:relative; }
table.sample tbody tr.nx-row:hover td:first-child::before{ content:'›'; position:absolute; left:-2px; color:var(--white,#fff); font-weight:700; }

/* row detail drawer (reuses infoModal shell) */
.row-detail-meta{ display:flex; gap:8px; margin-bottom:14px; }
.row-detail-fields{ display:grid; grid-template-columns:1fr; gap:0; border-top:1px solid var(--line,#262626); }
.row-detail-field{ display:grid; grid-template-columns:180px 1fr; gap:16px; padding:9px 0; border-bottom:1px solid var(--line,#262626); }
.rdf-key{ font-family:var(--font-mono,monospace); font-size:11px; letter-spacing:.06em; color:var(--fg-faint,#525252); text-transform:uppercase; }
.rdf-val{ font-size:13px; color:var(--fg,#eaeaea); font-family:var(--font-mono,monospace); word-break:break-word; }
.rdf-empty{ color:var(--fg-faint,#525252); font-size:13px; padding:12px 0; }
.row-detail-link{ color:var(--white,#fff); text-decoration:underline; }
.row-detail-related{ margin-top:18px; }
.rdr-label,.frp-tier,.rd-chip-tier{ font-family:var(--font-mono,monospace); font-size:10px; letter-spacing:.1em; color:var(--fg-faint,#525252); }
.rdr-label{ margin-bottom:8px; }
.rd-chip{ display:inline-flex; align-items:center; gap:8px; background:var(--panel-2,#131313); border:1px solid var(--line-bright,#3d3d3d); color:var(--fg,#eaeaea); font-family:var(--font-display,sans-serif); font-size:12px; padding:7px 12px; margin:0 8px 8px 0; cursor:pointer; transition:background .12s ease; }
.rd-chip:hover{ background:var(--white,#fff); color:var(--black,#000); }
.rd-chip:hover .rd-chip-tier{ color:#555; }
.row-detail-actions{ display:flex; gap:8px; flex-wrap:wrap; margin-top:20px; padding-top:16px; border-top:1px solid var(--line,#262626); }

/* feature toolbar: related dropdown */
.feat-related-wrap{ position:relative; display:inline-block; }
.feat-related-pop{ position:absolute; top:calc(100% + 4px); right:0; z-index:60; background:var(--panel,#0b0b0b); border:1px solid var(--line-bright,#3d3d3d); min-width:240px; box-shadow:0 8px 24px rgba(0,0,0,.6); }
.frp-item{ display:flex; align-items:center; justify-content:space-between; gap:10px; width:100%; text-align:left; background:transparent; border:none; border-bottom:1px solid var(--line,#262626); color:var(--fg,#eaeaea); font-family:var(--font-display,sans-serif); font-size:12px; padding:10px 12px; cursor:pointer; }
.frp-item:hover{ background:var(--panel-3,#1a1a1a); color:var(--white,#fff); }

/* overview quick actions */
.qa-grid{ display:grid; grid-template-columns:repeat(auto-fit,minmax(210px,1fr)); gap:12px; margin:6px 0 22px; }
.qa-card{ text-align:left; background:var(--panel-2,#131313); border:1px solid var(--line,#262626); padding:16px; cursor:pointer; transition:border-color .12s ease, background .12s ease; display:flex; flex-direction:column; gap:5px; }
.qa-card:hover{ border-color:var(--white,#fff); background:var(--panel-3,#1a1a1a); }
.qa-card.qa-ai{ border-color:var(--line-bright,#3d3d3d); }
.qa-card.qa-ai:hover{ background:var(--white,#fff); }
.qa-card.qa-ai:hover .qa-t,.qa-card.qa-ai:hover .qa-d,.qa-card.qa-ai:hover .qa-k{ color:var(--black,#000); }
.qa-k{ font-family:var(--font-mono,monospace); font-size:10px; letter-spacing:.12em; color:var(--fg-faint,#525252); }
.qa-t{ font-size:15px; font-weight:600; color:var(--white,#fff); }
.qa-d{ font-size:12px; color:var(--fg-dim,#8f8f8f); line-height:1.4; }


/* Access-flag badges — at-a-glance data availability, from the source map */
.access-flag{
  font-family:var(--font-mono); font-size:9px; letter-spacing:.08em;
  padding:3px 6px; border:1px solid var(--line-bright); color:var(--fg-faint);
  white-space:nowrap;
}
.access-flag.flag-open{ border-color:var(--fg-dim); color:var(--fg); }
.access-flag.flag-reg{ border-color:var(--line-bright); color:var(--fg-dim); }
.access-flag.flag-paid{ border-color:var(--white); color:var(--white); }
.access-flag.flag-scrape{ border-style:dashed; }
.access-flag.flag-internal{ border-color:var(--line); color:var(--fg-faint); }
.sidebar-group .feat-item .access-flag{ margin-left:6px; }



/* ============================================================
   ENHANCEMENT LAYER v2 — split layout, analyst visualizations
   with methodology info icons, sidebar accordion, AI tray.
   Theme-aware via existing CSS custom properties.
   ============================================================ */

/* ---- 60/40 split layout inside the feature detail ---- */
#detail.niy-laid-out{ display:flex; flex-direction:column; overflow:hidden; padding:22px 26px; }
#detail.niy-laid-out .detail-head{ flex:none; margin-bottom:12px; padding-bottom:12px; }
#detail.niy-laid-out .toolbar{ flex:none; }
#detail.niy-laid-out .toolbar-msg{ flex:none; }
.niy-split{ display:flex; flex:1 1 auto; min-height:0; margin-top:12px; }
.niy-col{ min-width:0; overflow-y:auto; display:flex; flex-direction:column; }
.niy-col-body{ min-height:0; }
.niy-col-feed{ flex:1 1 60%; padding-right:14px; }
.niy-col-work{ flex:1 1 40%; border-left:1px solid var(--line); padding-left:16px; }
.niy-col-head{ display:flex; align-items:center; justify-content:space-between; gap:8px; position:sticky; top:0; background:var(--black); padding:0 0 10px; margin-bottom:6px; z-index:3; }
.niy-col-title{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.13em; color:var(--fg-dim); text-transform:uppercase; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.niy-col-toggle{ flex:none; width:22px; height:20px; background:transparent; border:1px solid var(--line-bright); color:var(--fg-dim); cursor:pointer; font-size:11px; line-height:1; }
.niy-col-toggle:hover{ color:var(--white); border-color:var(--white); }
.niy-viz-add{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.04em; padding:3px 8px; background:transparent; border:1px solid var(--line-bright); color:var(--fg-dim); cursor:pointer; }
.niy-viz-add:hover{ color:var(--white); border-color:var(--white); }
.niy-viz-add:disabled{ opacity:.5; cursor:default; }
.niy-divider{ flex:0 0 9px; cursor:col-resize; position:relative; }
.niy-divider:before{ content:""; position:absolute; left:4px; top:0; bottom:0; width:1px; background:var(--line); }
.niy-divider:hover:before, .niy-divider.drag:before{ background:var(--white); width:2px; left:3px; }
.niy-split.only-feed .niy-col-work{ display:none; }
.niy-split.only-feed .niy-divider{ display:none; }
.niy-split.only-feed .niy-col-feed{ flex-basis:100% !important; padding-right:0; }
.niy-split.only-work .niy-col-feed{ display:none; }
.niy-split.only-work .niy-divider{ display:none; }
.niy-split.only-work .niy-col-work{ flex-basis:100% !important; border-left:none; padding-left:0; }
@media (max-width:1100px){
  #detail.niy-laid-out{ overflow-y:auto; }
  .niy-split{ flex-direction:column; }
  .niy-col{ overflow:visible; }
  .niy-col-work{ flex-basis:auto; border-left:none; border-top:1px solid var(--line); padding-left:0; margin-top:14px; padding-top:10px; }
  .niy-divider{ display:none; }
}

/* ---- KPI cards ---- */
.niy-kpis-wrap{ margin-bottom:18px; }
.niy-kpis-hd, .niy-chart-hd{ display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:11px; }
.niy-kpis-hd span{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.12em; color:var(--fg-dim); text-transform:uppercase; }
.niy-kpis{ display:grid; grid-template-columns:repeat(auto-fit, minmax(140px,1fr)); gap:10px; }
.niy-col-work .niy-kpis{ grid-template-columns:repeat(2,1fr); }
.niy-kpi{ border:1px solid var(--line); background:var(--panel); padding:13px 14px; }
.niy-kpi-k{ font-family:var(--font-mono); font-size:9.5px; letter-spacing:0.09em; color:var(--fg-faint); text-transform:uppercase; margin-bottom:8px; }
.niy-kpi-v{ font-family:var(--font-display); font-size:23px; font-weight:700; color:var(--white); line-height:1; }
.niy-kpi-sub{ font-family:var(--font-mono); font-size:9.5px; color:var(--fg-dim); margin-top:6px; }
.sig-green{ color:var(--signal-green); } .sig-amber{ color:var(--signal-amber); } .sig-red{ color:var(--signal-red); }

/* ---- Charts ---- */
.niy-charts{ display:grid; grid-template-columns:1fr; gap:14px; }
.niy-chart{ border:1px solid var(--line); background:var(--panel); padding:15px 16px; min-width:0; }
.niy-chart-t{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.09em; color:var(--fg-dim); text-transform:uppercase; }
.niy-dist-row{ display:grid; grid-template-columns:minmax(64px,40%) 1fr auto; gap:9px; align-items:center; margin-bottom:8px; font-family:var(--font-mono); font-size:11px; }
.niy-dist-label{ color:var(--fg); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.niy-dist-track{ height:9px; background:var(--panel-3); position:relative; }
.niy-dist-bar{ height:100%; background:var(--fg-dim); }
.niy-dist-bar.g{ background:var(--signal-green); } .niy-dist-bar.a{ background:var(--signal-amber); } .niy-dist-bar.r{ background:var(--signal-red); }
.niy-dist-val{ color:var(--fg-dim); min-width:34px; text-align:right; white-space:nowrap; }
.niy-spark{ width:100%; height:auto; display:block; }
.niy-spark-axis{ display:flex; justify-content:space-between; font-family:var(--font-mono); font-size:9px; color:var(--fg-faint); margin-top:6px; }
.niy-breadth{ display:flex; height:24px; border:1px solid var(--line); overflow:hidden; margin-bottom:8px; }
.niy-breadth-adv{ background:var(--signal-green); } .niy-breadth-dec{ background:var(--signal-red); }
.niy-breadth-lab{ display:flex; justify-content:space-between; font-family:var(--font-mono); font-size:10px; }
.niy-viz-empty{ font-family:var(--font-mono); font-size:11px; color:var(--fg-faint); padding:6px 0; }

/* ---- Methodology info icon + modal ---- */
.niy-info{ width:16px; height:16px; border-radius:50%; border:1px solid var(--line-bright); background:transparent; color:var(--fg-faint); font-family:var(--font-mono); font-size:10px; font-style:italic; line-height:1; cursor:pointer; opacity:.4; transition:all .15s; flex:none; }
.niy-info:hover{ opacity:1; color:var(--white); border-color:var(--white); }
/* doubled-class specificity so these theme-aware borders beat the app's
   container-scoped button reset in light mode */
.niy-info.niy-info{ border-color:var(--line-bright); }
.niy-info.niy-info:hover{ border-color:var(--white); }
.niy-col-toggle.niy-col-toggle{ border-color:var(--line-bright); }
.niy-col-toggle.niy-col-toggle:hover{ border-color:var(--white); }
.niy-viz-add.niy-viz-add{ border-color:var(--line-bright); }
.niy-viz-add.niy-viz-add:hover{ border-color:var(--white); }
.niy-meth-row{ display:grid; grid-template-columns:132px 1fr; gap:12px; padding:9px 0; border-bottom:1px solid var(--line); }
.niy-meth-row:last-child{ border-bottom:none; }
.niy-meth-k{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.07em; text-transform:uppercase; color:var(--fg-dim); }
.niy-meth-v{ font-size:13px; line-height:1.55; color:var(--fg); }

/* ---- Sidebar accordion (single-open, animated) ---- */
.sidebar-group-label.niy-acc-head{ cursor:pointer; display:flex; align-items:center; justify-content:space-between; gap:8px; user-select:none; padding:11px 14px; transition:background .15s ease, color .15s ease; }
.sidebar-group-label.niy-acc-head:hover{ background:var(--panel-2); color:var(--fg); }
.sidebar-group-label.niy-acc-head.open{ background:var(--panel-2); color:var(--fg); }
.niy-acc-name{ overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.niy-acc-meta{ display:flex; align-items:center; gap:8px; flex:none; }
.niy-acc-count{ font-family:var(--font-mono); font-size:9px; color:var(--fg-faint); border:1px solid var(--line); border-radius:9px; padding:1px 6px; line-height:1.4; }
.niy-acc-head.open .niy-acc-count{ color:var(--fg-dim); border-color:var(--line-bright); }
.niy-acc-chev{ font-size:9px; color:var(--fg-faint); transition:transform .25s ease, color .15s ease; }
.niy-acc-head.open .niy-acc-chev{ transform:rotate(90deg); color:var(--fg-dim); }
.niy-acc-body{ overflow:hidden; max-height:0; transition:max-height .28s cubic-bezier(.4,0,.2,1); }
#sidebarList.niy-acc-search .niy-acc-body{ max-height:none !important; }
#sidebarList .sidebar-group{ border-bottom:1px solid var(--line); }

/* ---- Compact filter/toolbar zone (maximizes feed + analytics) ---- */
#detail.niy-laid-out{ padding-top:16px; }
#detail.niy-laid-out .detail-head{ margin-bottom:8px; padding-bottom:10px; }
#detail.niy-laid-out .toolbar{ display:flex; flex-wrap:wrap; align-items:center; gap:8px; padding:6px 0; margin:0; }
#detail.niy-laid-out .toolbar .filter-group{ flex:1 1 200px; max-width:340px; }
#detail.niy-laid-out .toolbar .column-filters{ display:inline-flex; flex:0 1 auto; width:auto; margin:0; gap:6px; }
#detail.niy-laid-out .toolbar .toolbar-btn{ padding:6px 10px; font-size:11px; }
#detail.niy-laid-out .toolbar-msg{ margin:0; }
#detail.niy-laid-out .toolbar-msg:empty{ display:none; }
.niy-col-feed .section-label.niy-hide{ display:none; }
.niy-more{ position:relative; order:99; }
.niy-more-btn{ padding:6px 11px; font-size:13px; line-height:1; }
.niy-more-menu{ position:absolute; top:calc(100% + 5px); right:0; min-width:190px; background:var(--panel-2); border:1px solid var(--line-bright); z-index:30; display:flex; flex-direction:column; box-shadow:0 8px 24px rgba(0,0,0,.35); }
.niy-more-menu[hidden]{ display:none; }
.niy-more-menu .niy-more-item{ border:none !important; border-bottom:1px solid var(--line) !important; text-align:left; width:100%; padding:10px 13px !important; font-size:11px !important; }
.niy-more-menu .niy-more-item:last-child{ border-bottom:none !important; }
.niy-more-menu .niy-more-item:hover{ background:var(--panel-3); }

/* ---- Premium segmented top navigation ---- */
.tabs{ display:flex; flex-wrap:nowrap; gap:0; padding:0 8px; background:var(--panel); border-bottom:1px solid var(--line-bright); overflow-x:auto; scrollbar-width:none; }
.tabs::-webkit-scrollbar{ display:none; }
.tab{ position:relative; flex:1 1 0; min-width:0; display:flex; flex-direction:row; align-items:center; justify-content:center; gap:8px; padding:12px 12px 13px; border:none; border-right:1px solid var(--line); background:transparent; color:var(--fg-dim); font-family:var(--font-display); font-weight:600; font-size:12.5px; letter-spacing:0.035em; cursor:pointer; transition:color .18s ease, background .18s ease; }
.tab:last-child{ border-right:none; }
.tab .tab-ico{ width:15px; height:15px; display:inline-flex; align-items:center; justify-content:center; opacity:.55; transition:opacity .18s ease, transform .18s ease; flex:none; }
.tab .tab-ico svg{ width:15px; height:15px; fill:none; stroke:currentColor; stroke-width:1.6; stroke-linecap:round; stroke-linejoin:round; }
.tab .tab-label{ white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:100%; }
.tab:hover{ color:var(--fg); background:var(--panel-2); }
.tab:hover .tab-ico{ opacity:1; transform:translateY(-1px); }
.tab::after{ content:""; position:absolute; left:14px; right:14px; bottom:0; height:2px; background:var(--white); transform:scaleX(0); transform-origin:center; transition:transform .24s cubic-bezier(.4,0,.2,1); }
.tab.active{ color:var(--white); background:var(--panel-3); }
.tab.active .tab-ico{ opacity:1; }
.tab.active::after{ transform:scaleX(1); }
.tab .beta-badge{ transform:scale(.82); transform-origin:left center; }
.tab-live{ width:6px; height:6px; border-radius:50%; background:var(--signal-green); flex:none; box-shadow:0 0 0 0 rgba(76,154,90,.5); animation:niyPulse 2.4s infinite; }
.tab.active .tab-live{ background:var(--signal-green); }
@keyframes niyPulse{ 0%{ box-shadow:0 0 0 0 rgba(76,154,90,.5);} 70%{ box-shadow:0 0 0 5px rgba(76,154,90,0);} 100%{ box-shadow:0 0 0 0 rgba(76,154,90,0);} }
@media (max-width:1100px){
  .tab{ flex:0 0 auto; }
  .tab .tab-label{ font-size:11.5px; }
}

/* ---- Enriched row-detail modal sections ---- */
.rd-summary{ font-size:13.5px; line-height:1.6; color:var(--fg); background:var(--panel-2); border-left:2px solid var(--line-bright); padding:11px 14px; margin:4px 0 16px; }
.rd-section{ margin-bottom:18px; }
.rd-sec-label{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.12em; color:var(--fg-faint); text-transform:uppercase; margin-bottom:9px; }
.rd-timeline{ position:relative; padding-left:4px; }
.rd-tl-item{ display:flex; gap:12px; align-items:flex-start; padding:0 0 12px; position:relative; }
.rd-tl-item:not(:last-child):before{ content:""; position:absolute; left:4px; top:14px; bottom:0; width:1px; background:var(--line-bright); }
.rd-tl-dot{ width:9px; height:9px; border-radius:50%; background:var(--signal-amber); margin-top:4px; flex:none; z-index:1; }
.rd-tl-when{ font-family:var(--font-mono); font-size:12px; color:var(--white); }
.rd-tl-what{ font-size:11px; color:var(--fg-dim); margin-top:1px; }
.rd-docs{ display:flex; flex-wrap:wrap; gap:8px; }
.rd-doc{ display:inline-flex; align-items:center; gap:7px; padding:7px 12px; border:1px solid var(--line-bright); color:var(--fg); text-decoration:none; font-size:12px; transition:all .12s; }
.rd-doc:hover{ border-color:var(--white); color:var(--white); }
.rd-doc-ic{ color:var(--fg-dim); }
.rd-entities{ display:flex; flex-wrap:wrap; gap:7px; }
.rd-entity{ font-family:var(--font-mono); font-size:11px; padding:4px 10px; background:var(--panel-3); color:var(--fg); border:1px solid var(--line); }
.toolbar-btn.primary{ background:var(--white); color:var(--black); border-color:var(--white); }
.toolbar-btn.primary:hover{ opacity:.88; }

/* ---- AI context tray ---- */
#niyAiTray{ border-bottom:1px solid var(--line); padding:10px 14px; background:var(--panel-2); }
#niyAiTray[hidden]{ display:none; }
.niy-tray-head{ display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; }
.niy-tray-label{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.1em; color:var(--fg-dim); text-transform:uppercase; }
.niy-tray-clear{ font-family:var(--font-mono); font-size:10px; background:none; border:none; color:var(--fg-faint); cursor:pointer; text-transform:uppercase; }
.niy-tray-clear:hover{ color:var(--signal-red); }
.niy-tray-chips{ display:flex; flex-wrap:wrap; gap:6px; }
.niy-tray-chip{ display:inline-flex; align-items:center; gap:6px; max-width:100%; font-family:var(--font-mono); font-size:11px; padding:4px 8px; background:var(--panel-3); border:1px solid var(--line-bright); color:var(--fg); }
.niy-tray-chip span{ overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:180px; }
.niy-tray-chip button{ background:none; border:none; color:var(--fg-faint); cursor:pointer; font-size:13px; line-height:1; padding:0; }
.niy-tray-chip button:hover{ color:var(--signal-red); }
#globalAiBtn .niy-ai-badge{ position:absolute; top:-4px; right:-4px; min-width:16px; height:16px; padding:0 3px; border-radius:8px; background:var(--signal-red); color:#fff; font-size:10px; font-family:var(--font-mono); display:flex; align-items:center; justify-content:center; }

/* ---- Large-display scaling ---- */
@media (min-width:1600px){
  .main{ grid-template-columns:340px 1fr; }
  .niy-kpis{ grid-template-columns:repeat(auto-fit, minmax(150px,1fr)); }
}
@media (min-width:2200px){
  .main{ grid-template-columns:380px 1fr; }
  #detail.niy-laid-out{ padding:30px 56px; }
  .detail-title{ font-size:28px; max-width:900px; }
  .niy-col-work .niy-kpis{ grid-template-columns:repeat(3,1fr); }
}

/* ============================================================
   v3 — intelligence workstation: multi-pane workspace,
   in-pane AI, interactive charts, tighter chrome
   ============================================================ */

/* ---- tighter chrome: content-first vertical budget ---- */
.topbar{ padding:7px 20px !important; }
.tabs{ padding:0 8px; }
.tab{ padding:9px 12px 10px; }
#scopeBar.scope-bar, .scope-bar{ padding:6px 22px !important; min-height:0; }
#detail.niy-laid-out{ padding:12px 22px 14px; }
#detail.niy-laid-out .detail-head{ margin-bottom:8px; padding-bottom:9px; align-items:center; }
#detail.niy-laid-out .detail-title{ font-size:19px; line-height:1.15; }
#detail.niy-laid-out .detail-head .tags{ margin-top:5px; }
#detail.niy-laid-out .niy-split{ margin-top:10px; }

/* ---- work column: head + body + panes ---- */
.niy-col-work{ overflow:hidden; padding:0 0 0 16px; }
.niy-work-head{ flex:none; display:flex; align-items:center; justify-content:space-between; gap:10px; padding:0 0 9px; margin-bottom:8px; border-bottom:1px solid var(--line); position:sticky; top:0; background:var(--black); z-index:3; }
.niy-work-modes{ display:inline-flex; border:1px solid var(--line-bright); border-radius:3px; overflow:hidden; }
.niy-mode{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.06em; text-transform:uppercase; padding:5px 12px; background:transparent; border:none; color:var(--fg-dim); cursor:pointer; transition:background .15s ease, color .15s ease; }
.niy-mode + .niy-mode{ border-left:1px solid var(--line); }
.niy-mode:hover{ color:var(--fg); background:var(--panel-2); }
.niy-mode.active{ background:var(--white); color:var(--black); }
.niy-work-tools{ display:flex; align-items:center; gap:7px; }
.niy-ai-clear{ font-family:var(--font-mono); font-size:10px; text-transform:uppercase; letter-spacing:0.05em; padding:4px 9px; background:transparent; border:1px solid var(--line-bright); color:var(--fg-dim); cursor:pointer; }
.niy-ai-clear:hover{ color:var(--signal-red); border-color:var(--signal-red); }
.niy-work-body{ flex:1 1 auto; min-height:0; display:flex; }
.niy-pane{ flex:1 1 auto; min-width:0; min-height:0; }
.niy-pane[hidden]{ display:none; }
.niy-pane-analytics{ overflow-y:auto; }
.niy-pane-ai{ display:flex; flex-direction:column; }

/* ---- cross-filter chip in the work head ---- */
.niy-cf-chip{ display:inline-flex; align-items:center; gap:6px; font-family:var(--font-mono); font-size:10px; color:var(--fg); background:var(--panel-3); border:1px solid var(--line-bright); padding:3px 4px 3px 8px; max-width:200px; }
.niy-cf-chip[hidden]{ display:none; }
.niy-cf-chip span{ overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.niy-cf-x{ background:none; border:none; color:var(--fg-faint); cursor:pointer; font-size:13px; line-height:1; padding:0 2px; }
.niy-cf-x:hover{ color:var(--signal-red); }

/* ---- interactive charts ---- */
.niy-dist-bar{ transition:width .55s cubic-bezier(.22,1,.36,1); }
.niy-dist-row.niy-clickable{ cursor:pointer; border-radius:2px; }
.niy-dist-row.niy-clickable:hover{ background:var(--panel-2); }
.niy-dist-row:hover .niy-dist-bar{ filter:brightness(1.35); }
.niy-dist-row.niy-cf-active{ background:var(--panel-3); }
.niy-dist-row.niy-cf-active .niy-dist-bar{ box-shadow:0 0 0 1px var(--white) inset; }
.niy-spark-area{ fill:var(--line-bright); opacity:.30; }
.niy-spark-line{ fill:none; stroke:var(--white); stroke-width:1.5; }
.niy-spark-vis{ fill:var(--white); }
.niy-spark-dot{ cursor:default; transition:fill .12s ease; }
.niy-spark-dot.niy-clickable{ cursor:pointer; }
.niy-spark-dot:hover{ fill:rgba(255,255,255,.14); }
.niy-feed-hl{ background:var(--panel-3) !important; box-shadow:inset 2px 0 0 var(--signal-amber); }

/* ---- shared tooltip ---- */
#niyTip{ position:fixed; z-index:9999; pointer-events:none; max-width:280px; background:var(--panel-2); border:1px solid var(--line-bright); box-shadow:0 10px 30px rgba(0,0,0,.45); padding:9px 11px; font-family:var(--font-mono); }
#niyTip[hidden]{ display:none; }
.niy-tip-t{ font-size:12px; color:var(--white); margin-bottom:4px; font-weight:600; }
.niy-tip-v{ font-size:12px; color:var(--fg); }
.niy-tip-v b{ color:var(--white); }
.niy-tip-m{ font-size:10px; color:var(--fg-faint); margin-top:5px; }

/* ---- in-pane AI workspace ---- */
.niy-ai-context{ flex:none; margin-bottom:8px; }
.niy-ai-drop-hint{ font-family:var(--font-mono); font-size:10.5px; color:var(--fg-faint); border:1px dashed var(--line-bright); padding:8px 10px; text-align:center; }
.niy-ai-ctx-hd{ display:flex; align-items:center; justify-content:space-between; font-family:var(--font-mono); font-size:10px; letter-spacing:0.06em; text-transform:uppercase; color:var(--fg-dim); margin-bottom:6px; }
.niy-ai-ctx-clear{ background:none; border:none; color:var(--fg-faint); cursor:pointer; font-family:var(--font-mono); font-size:10px; text-transform:uppercase; }
.niy-ai-ctx-clear:hover{ color:var(--signal-red); }
.niy-ai-ctx-chips{ display:flex; flex-wrap:wrap; gap:6px; }
.niy-ai-chip{ display:inline-flex; align-items:center; gap:6px; max-width:100%; font-family:var(--font-mono); font-size:11px; padding:4px 8px; background:var(--panel-3); border:1px solid var(--line-bright); color:var(--fg); }
.niy-ai-chip span{ overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:170px; }
.niy-ai-chip button{ background:none; border:none; color:var(--fg-faint); cursor:pointer; font-size:13px; line-height:1; padding:0; }
.niy-ai-chip button:hover{ color:var(--signal-red); }
.niy-ai-log{ flex:1 1 auto; min-height:0; overflow-y:auto; display:flex; flex-direction:column; gap:10px; padding:4px 2px 8px; }
.niy-ai-msg{ font-size:13px; line-height:1.6; padding:10px 12px; border:1px solid var(--line); white-space:pre-wrap; word-break:break-word; max-width:92%; }
.niy-ai-msg.user{ align-self:flex-end; background:var(--panel-3); color:var(--fg); border-color:var(--line-bright); }
.niy-ai-msg.ai{ align-self:flex-start; background:var(--panel); color:var(--fg); }
.niy-ai-pending{ color:var(--fg-dim); font-style:italic; }
.niy-ai-empty{ margin:auto; text-align:center; max-width:320px; color:var(--fg-faint); }
.niy-ai-empty-t{ font-family:var(--font-display); font-weight:700; font-size:16px; color:var(--fg-dim); margin-bottom:8px; }
.niy-ai-empty-d{ font-size:12px; line-height:1.6; }
.niy-ai-input-row{ flex:none; display:flex; gap:8px; align-items:flex-end; border-top:1px solid var(--line); padding-top:9px; }
.niy-ai-input{ flex:1 1 auto; resize:none; background:var(--panel-2); border:1px solid var(--line-bright); color:var(--fg); font-family:var(--font-mono); font-size:12.5px; line-height:1.5; padding:9px 11px; max-height:160px; }
.niy-ai-input:focus{ outline:none; border-color:var(--white); }
.niy-ai-send{ flex:none; background:var(--white); color:var(--black); border:none; font-family:var(--font-mono); font-size:11px; letter-spacing:0.06em; text-transform:uppercase; padding:0 16px; height:38px; cursor:pointer; }
.niy-ai-send:hover{ opacity:.88; }

/* ---- drag & resize affordances ---- */
.niy-col-feed table.sample tbody tr[draggable="true"]{ cursor:grab; }
.niy-split.niy-dragging .niy-col-work{ outline:1px dashed var(--line-bright); outline-offset:-4px; }
.niy-col-work.niy-drop-over{ background:var(--panel-2); box-shadow:inset 0 0 0 2px var(--signal-green); }
body.niy-resizing{ cursor:col-resize; user-select:none; }
body.niy-resizing *{ pointer-events:none; }
body.niy-resizing .niy-divider{ pointer-events:auto; }

/* ---- merged title+filter band + maximal content budget ---- */
#detail.niy-laid-out{ padding:10px 22px 12px; }
#detail.niy-laid-out .detail-head.niy-head-merged{ display:flex; align-items:center; justify-content:flex-start; gap:10px 14px; flex-wrap:wrap; margin-bottom:8px; padding-bottom:8px; }
