#detail.niy-laid-out .detail-head.niy-head-merged .toolbar{ flex:1 1 380px; justify-content:flex-end; margin-left:auto; padding:0; gap:7px; }
#detail.niy-laid-out .niy-split{ margin-top:8px; }
.topbar{ padding:6px 20px !important; }
#scopeBar.scope-bar, .scope-bar{ padding:4px 22px !important; }
.ticker-wrap{ font-size:11px; }
.ticker-track{ padding:3px 0 !important; }

/* ---- final chrome trim to reach content-first budget ---- */
.ticker-wrap{ font-size:10.5px; }
.ticker-track{ padding:2px 0 !important; }
.tab{ padding:8px 12px 9px; }
#scopeBar.scope-bar, .scope-bar{ padding:3px 22px !important; }
.scope-bar select, .scope-bar .scope-action-btn, .scope-bar input{ padding:4px 8px !important; font-size:11px !important; }
#detail.niy-laid-out{ padding:8px 22px 10px; }
#detail.niy-laid-out .detail-head.niy-head-merged{ margin-bottom:6px; padding-bottom:6px; }
#detail.niy-laid-out .niy-split{ margin-top:6px; }

/* ============================================================
   LIVE TV — media-monitoring workspace (dark, native)
   ============================================================ */
.niy-livetv-btn{ display:inline-flex; align-items:center; gap:7px; font-family:var(--font-mono); font-size:11px; letter-spacing:0.06em; text-transform:uppercase; padding:6px 12px; background:transparent; border:1px solid var(--line-bright); color:var(--fg); cursor:pointer; transition:all .15s ease; }
.niy-livetv-btn:hover{ border-color:var(--signal-red); color:var(--white); }
.niy-livetv-dot{ width:7px; height:7px; border-radius:50%; background:var(--signal-red); box-shadow:0 0 0 0 rgba(184,86,79,.6); animation:niyPulse 2s infinite; }

#niyLiveTv{ position:fixed; inset:0; z-index:5000; background:var(--black); display:flex; flex-direction:column; }
#niyLiveTv[hidden]{ display:none; }
.ltv-topbar{ flex:none; display:flex; align-items:center; gap:14px; padding:8px 20px; border-bottom:1px solid var(--line-bright); background:var(--panel); }
.ltv-back{ font-family:var(--font-mono); font-size:11px; text-transform:uppercase; letter-spacing:0.05em; padding:6px 12px; background:transparent; border:1px solid var(--line-bright); color:var(--fg-dim); cursor:pointer; }
.ltv-back:hover{ color:var(--white); border-color:var(--white); }
.ltv-brand{ font-family:var(--font-display); font-weight:700; font-size:15px; letter-spacing:0.14em; color:var(--white); }
.ltv-brand span{ color:var(--signal-red); }
.ltv-now{ display:inline-flex; align-items:center; gap:7px; font-family:var(--font-mono); font-size:12px; color:var(--fg); padding:4px 10px; border:1px solid var(--line-bright); }
.ltv-now .ltv-dot, .ltv-sb-live .ltv-dot{ width:7px; height:7px; border-radius:50%; background:var(--signal-red); animation:niyPulse 2s infinite; }
.ltv-spacer{ flex:1 1 auto; }
.ltv-hint{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.06em; text-transform:uppercase; color:var(--fg-faint); }
.ltv-close{ width:30px; height:30px; background:transparent; border:1px solid var(--line-bright); color:var(--fg-dim); font-size:15px; cursor:pointer; }
.ltv-close:hover{ color:var(--white); border-color:var(--signal-red); }

.ltv-grid{ flex:1 1 auto; overflow-y:auto; padding:24px; display:grid; grid-template-columns:repeat(auto-fill, minmax(200px,1fr)); gap:16px; align-content:start; }
.ltv-card{ position:relative; display:flex; flex-direction:column; text-align:left; background:var(--panel); border:1px solid var(--line); padding:0 0 12px; cursor:pointer; overflow:hidden; transition:transform .14s ease, border-color .14s ease; }
.ltv-card:hover{ transform:translateY(-3px); border-color:var(--line-bright); }
.ltv-live-badge{ position:absolute; top:10px; right:10px; z-index:2; display:inline-flex; align-items:center; gap:5px; font-family:var(--font-mono); font-size:9px; letter-spacing:0.08em; color:#fff; background:rgba(184,86,79,.92); padding:3px 7px; }
.ltv-live-badge .ltv-dot{ width:5px; height:5px; border-radius:50%; background:#fff; animation:niyPulse 2s infinite; }
.ltv-logo{ height:96px; display:flex; align-items:center; justify-content:center; }
.ltv-logo span{ font-family:var(--font-display); font-weight:800; font-size:30px; letter-spacing:0.02em; color:#fff; text-shadow:0 1px 6px rgba(0,0,0,.35); }
.ltv-card-name{ font-family:var(--font-display); font-weight:700; font-size:14px; color:var(--white); padding:12px 14px 2px; }
.ltv-card-lang{ font-family:var(--font-mono); font-size:10px; color:var(--fg-dim); padding:0 14px; }

/* viewer fills the space under the (thin) topbar + icon strip ≈ 90% and splits 70 / 30 */
.ltv-viewer{ flex:1 1 auto; display:flex; min-height:0; }
.ltv-stage{ flex:0 0 70%; max-width:70%; display:flex; flex-direction:column; min-width:0; }
/* compact channel-icon strip: small ~3cm tiles, one scrolling row */
.ltv-strip{ flex:none; display:flex; gap:8px; overflow-x:auto; overflow-y:hidden; padding:6px 14px; border-bottom:1px solid var(--line-bright); background:var(--panel); scrollbar-width:thin; }
.ltv-chip{ flex:0 0 3cm; width:3cm; display:flex; flex-direction:column; gap:0; padding:0; background:var(--panel-2); border:1px solid var(--line); color:var(--fg-dim); cursor:pointer; overflow:hidden; transition:border-color .13s ease, transform .13s ease; }
.ltv-chip:hover{ border-color:var(--line-bright); transform:translateY(-1px); }
.ltv-chip.active{ border-color:var(--white); }
.ltv-chip-logo{ position:relative; width:100%; height:26px; display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:800; font-size:12px; letter-spacing:0.02em; color:#fff; }
.ltv-chip-livedot{ position:absolute; top:3px; right:5px; width:5px; height:5px; border-radius:50%; background:#fff; box-shadow:0 0 0 1px rgba(0,0,0,.25); animation:niyPulse 2s infinite; }
.ltv-chip-name{ font-family:var(--font-mono); font-size:9px; letter-spacing:0.01em; color:var(--fg-dim); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; padding:3px 6px; text-align:center; }
.ltv-chip.active .ltv-chip-name{ color:var(--white); }
.ltv-video-wrap{ flex:1 1 auto; position:relative; background:#000; min-height:0; }
.ltv-video, .ltv-video-wrap iframe{ position:absolute; inset:0; width:100% !important; height:100% !important; border:0; }
.ltv-offline{ position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px; background:var(--panel); text-align:center; padding:24px; }
/* the `hidden` attribute must win over display:flex above, otherwise a stale
   error card stays visible on top of a channel that is actually playing */
.ltv-offline[hidden]{ display:none !important; }
.ltv-off-t{ font-family:var(--font-display); font-weight:700; font-size:17px; color:var(--fg); }
.ltv-off-d{ font-family:var(--font-mono); font-size:12px; color:var(--fg-dim); max-width:420px; line-height:1.6; }
.ltv-statusbar{ flex:none; display:flex; align-items:center; gap:14px; padding:8px 16px; border-top:1px solid var(--line); background:var(--panel); font-family:var(--font-mono); font-size:11px; }
.ltv-sb-live{ display:inline-flex; align-items:center; gap:6px; color:var(--signal-red); letter-spacing:0.08em; }
.ltv-sb-name{ color:var(--white); }
.ltv-sb-note{ margin-left:auto; color:var(--fg-faint); font-size:10px; }

.ltv-intruth{ flex:0 0 30%; max-width:30%; min-width:260px; display:flex; flex-direction:column; border-left:1px solid var(--line-bright); background:var(--panel); }
.ltv-intruth-head{ flex:none; display:flex; align-items:center; gap:8px; padding:12px 14px; border-bottom:1px solid var(--line); font-family:var(--font-display); font-weight:700; font-size:13px; color:var(--white); }
.ltv-it-logo{ width:20px; height:20px; border-radius:50%; background:var(--signal-green); color:#fff; display:flex; align-items:center; justify-content:center; font-size:12px; }
.ltv-it-tag{ margin-left:auto; font-family:var(--font-mono); font-size:8.5px; letter-spacing:0.08em; color:var(--fg-faint); border:1px solid var(--line-bright); padding:2px 6px; }
.ltv-intruth-body{ flex:1 1 auto; min-height:0; overflow-y:auto; padding:14px; display:flex; flex-direction:column; gap:14px; }
.ltv-intruth-frame{ width:100%; height:100%; border:0; flex:1 1 auto; }
.ltv-it-note{ font-family:var(--font-mono); font-size:10.5px; line-height:1.6; color:var(--fg-dim); border-left:2px solid var(--signal-green); padding:8px 10px; background:var(--panel-2); }
.ltv-it-sec-h{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.1em; text-transform:uppercase; color:var(--fg-faint); margin-bottom:6px; }
.ltv-it-sec-b{ font-size:12px; line-height:1.6; color:var(--fg-dim); border:1px solid var(--line); padding:10px 11px; min-height:44px; }
.ltv-it-ask{ display:flex; gap:7px; margin-top:auto; }
.ltv-it-ask input{ flex:1 1 auto; background:var(--panel-2); border:1px solid var(--line-bright); color:var(--fg); font-family:var(--font-mono); font-size:11.5px; padding:8px 10px; }
.ltv-it-ask input:focus{ outline:none; border-color:var(--white); }
.ltv-it-ask button{ flex:none; background:var(--signal-green); color:#fff; border:none; font-family:var(--font-mono); font-size:10px; text-transform:uppercase; letter-spacing:0.05em; padding:0 12px; cursor:pointer; }
.ltv-it-foot{ font-family:var(--font-mono); font-size:9px; color:var(--fg-faint); text-align:center; letter-spacing:0.05em; }

@media (max-width:1100px){
  .ltv-viewer{ flex-direction:column; }
  .ltv-stage, .ltv-intruth{ flex:1 1 auto; max-width:100%; }
  .ltv-intruth{ border-left:none; border-top:1px solid var(--line-bright); min-height:220px; }
}

.ltv-key-btn{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.05em; text-transform:uppercase; padding:6px 11px; background:transparent; border:1px solid var(--line-bright); color:var(--fg-dim); cursor:pointer; }
.ltv-key-btn:hover{ color:var(--white); border-color:var(--white); }
.ltv-off-form{ display:flex; gap:8px; width:100%; max-width:460px; margin-top:6px; }
.ltv-off-form input{ flex:1 1 auto; background:var(--panel-2); border:1px solid var(--line-bright); color:var(--fg); font-family:var(--font-mono); font-size:12px; padding:9px 11px; }
.ltv-off-form input:focus{ outline:none; border-color:var(--white); }
.ltv-off-form button{ flex:none; background:var(--white); color:var(--black); border:none; font-family:var(--font-mono); font-size:10px; letter-spacing:0.05em; text-transform:uppercase; padding:0 14px; cursor:pointer; }
.ltv-off-form button:hover{ opacity:.88; }
.ltv-off-help{ font-family:var(--font-mono); font-size:10px; color:var(--fg-faint); margin-top:12px; line-height:1.6; max-width:460px; }
.ltv-spinner{ width:26px; height:26px; border:2px solid var(--line-bright); border-top-color:var(--white); border-radius:50%; animation:niySpin .8s linear infinite; margin-bottom:6px; }
@keyframes niySpin{ to{ transform:rotate(360deg); } }
/* the key-setup modal must sit above the full-screen Live TV overlay (z 5000) */
.modal-overlay{ z-index:6000; }

.ltv-sb-state{ font-family:var(--font-mono); font-size:10px; color:var(--fg-faint); }

/* ---- Live fact-check panel ---- */
.ltv-fc-ctl{ display:flex; flex-direction:column; gap:6px; margin-bottom:4px; }
.ltv-fc-btn{ align-self:flex-start; font-family:var(--font-mono); font-size:11px; letter-spacing:0.04em; text-transform:uppercase; padding:7px 12px; background:transparent; border:1px solid var(--signal-green); color:var(--signal-green); cursor:pointer; }
.ltv-fc-btn:hover{ background:var(--signal-green); color:#fff; }
.ltv-fc-btn.on{ border-color:var(--signal-red); color:var(--signal-red); }
.ltv-fc-btn.on:hover{ background:var(--signal-red); color:#fff; }
.ltv-fc-status{ font-family:var(--font-mono); font-size:10px; color:var(--fg-dim); line-height:1.5; }
.ltv-fc-ph{ font-family:var(--font-mono); font-size:11px; color:var(--fg-faint); line-height:1.55; }
.ltv-fc-transcript{ max-height:150px; overflow-y:auto; font-size:12px; line-height:1.6; }
.ltv-fc-line{ margin-bottom:4px; color:var(--fg); }
.ltv-fc-ts{ font-family:var(--font-mono); font-size:9px; color:var(--fg-faint); margin-right:5px; }
.ltv-fc-marker{ font-family:var(--font-mono); font-size:9px; color:var(--signal-amber); text-align:center; margin:6px 0; letter-spacing:0.05em; }
.ltv-fc-summary{ font-size:12.5px; line-height:1.6; color:var(--fg); }
.ltv-fc-claims{ display:flex; flex-direction:column; gap:8px; max-height:300px; overflow-y:auto; }
.ltv-fc-card{ border:1px solid var(--line); border-left:3px solid var(--fg-faint); background:var(--panel-2); padding:9px 10px; }
.ltv-fc-card.ltv-fc-g{ border-left-color:var(--signal-green); }
.ltv-fc-card.ltv-fc-r{ border-left-color:var(--signal-red); }
.ltv-fc-card.ltv-fc-a{ border-left-color:var(--signal-amber); }
.ltv-fc-card.ltv-fc-u{ border-left-color:var(--fg-faint); }
.ltv-fc-card.ltv-fc-pending{ opacity:.65; }
.ltv-fc-card-h{ display:flex; justify-content:space-between; align-items:center; margin-bottom:5px; gap:8px; }
.ltv-fc-verdict{ font-family:var(--font-mono); font-size:10px; letter-spacing:0.05em; text-transform:uppercase; color:var(--white); }
.ltv-fc-g .ltv-fc-verdict{ color:var(--signal-green); }
.ltv-fc-r .ltv-fc-verdict{ color:var(--signal-red); }
.ltv-fc-a .ltv-fc-verdict{ color:var(--signal-amber); }
.ltv-fc-time{ font-family:var(--font-mono); font-size:9px; color:var(--fg-faint); flex:none; }
.ltv-fc-claim{ font-size:12.5px; line-height:1.5; color:var(--fg); margin-bottom:4px; }
.ltv-fc-exp{ font-size:11.5px; line-height:1.5; color:var(--fg-dim); margin-bottom:5px; }
.ltv-fc-src{ font-family:var(--font-mono); font-size:10px; color:var(--fg-dim); word-break:break-word; }
.ltv-fc-src a{ color:var(--fg-dim); } .ltv-fc-src a:hover{ color:var(--white); }
.ltv-fc-nosrc{ color:var(--signal-amber); }
.ltv-fc-answer{ border-top:1px solid var(--line); padding-top:8px; margin-top:2px; }
.ltv-fc-answer[hidden]{ display:none; }
.ltv-fc-q{ font-family:var(--font-mono); font-size:11px; color:var(--fg-dim); margin-bottom:4px; }
.ltv-fc-a{ font-size:12.5px; line-height:1.6; color:var(--fg); white-space:pre-wrap; }




.niy-mtx{display:grid;gap:3px;align-items:stretch;font-size:11px;margin-top:4px}
.niy-mtx-ch{font-family:var(--mono,monospace);text-transform:uppercase;letter-spacing:.04em;font-size:9.5px;color:var(--text-3,#8a8f98);text-align:center;padding:2px 1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.niy-mtx-rh{font-size:11px;color:var(--text-2,#c8ccd2);padding:0 6px;display:flex;align-items:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.niy-mtx-cell{position:relative;min-height:22px;border-radius:3px;background:var(--panel-2,rgba(255,255,255,.03));display:flex;align-items:center;justify-content:center}
.niy-mtx-fill{position:absolute;inset:0;border-radius:3px}
.niy-mtx-n{position:relative;z-index:1;font-family:var(--mono,monospace);font-size:10.5px;color:var(--text-1,#e8eaed);font-weight:600}
.niy-mtx-cell.on .niy-mtx-n{color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.55)}
.niy-mtx-tot{font-family:var(--mono,monospace);font-size:10px;color:var(--text-3,#8a8f98);text-align:center;display:flex;align-items:center;justify-content:center}



.niy-co-loading{display:flex;align-items:center;gap:9px;padding:14px 2px;color:var(--fg-dim,#9aa0aa);font-size:12px}
.niy-co-spin{width:13px;height:13px;border:2px solid var(--line,#2a2d34);border-top-color:var(--accent,#7fb0ff);border-radius:50%;animation:niyCoSpin .7s linear infinite;flex:none}
@keyframes niyCoSpin{to{transform:rotate(360deg)}}



#searchSuggest .suggest-sec{font-family:var(--font-mono);font-size:8.5px;letter-spacing:.14em;color:var(--fg-faint);padding:8px 12px 3px;text-transform:uppercase}
#searchSuggest .suggest-hit{font-family:var(--font-mono);font-size:9px;color:var(--signal-amber);border:1px solid color-mix(in srgb,var(--signal-amber) 40%,transparent);border-radius:8px;padding:0 5px;margin-left:4px;vertical-align:middle}



:root{
  --gm-hair:rgba(148,166,196,.13); --gm-hair-2:rgba(148,166,196,.22);
  --gm-panel:rgba(148,166,196,.06); --gm-card:rgba(148,166,196,.045);
  --gm-ink-3:#8b95a7;
  --gm-red:#e5484d; --gm-amber:#e0913f; --gm-yellow:#e5c53f;
  --gm-green:#46a758; --gm-cyan:#3fb5c9; --gm-blue:#4a90d9;
}
/* ---- selection + focus: one accent, everywhere the same ---- */
::selection{background:rgba(127,176,255,.28)}
:focus-visible{outline:1px solid var(--ds-accent-line)!important;outline-offset:2px;border-radius:3px}
/* ---- thin uniform scrollbars (Gotham chrome never shouts) ---- */
*::-webkit-scrollbar{width:8px;height:8px}
*::-webkit-scrollbar-thumb{background:var(--ds-thumb);border-radius:4px;border:2px solid transparent;background-clip:content-box}
*::-webkit-scrollbar-thumb:hover{background:var(--ds-thumb-h);border:2px solid transparent;background-clip:content-box}
*::-webkit-scrollbar-track{background:transparent}
/* ---- sidebar: histogram sections + notch selection (Gotham signature) ---- */
.sidebar-group-label{position:relative;text-transform:uppercase;letter-spacing:.16em;font-size:10px;color:var(--gm-ink-3)}
.sidebar-group-label::after{content:"";position:absolute;left:14px;bottom:0;height:2px;
  width:calc(var(--gm-w,0)*1px);max-width:64%;border-radius:1px;
  background:linear-gradient(90deg,rgba(127,176,255,.55),rgba(127,176,255,.04))}
.feat-item{transition:background-color .12s var(--ds-ease),border-color .12s var(--ds-ease),color .12s var(--ds-ease)!important;position:relative}
.feat-item:hover{background:var(--gm-panel)}
.feat-item.active::before{content:"";position:absolute;left:0;top:15%;bottom:15%;width:2px;border-radius:1px;
  background:var(--ds-accent);box-shadow:0 0 8px rgba(127,176,255,.5)}
.feat-item.active{background:var(--ds-accent-dim)}
/* ---- KPI cards: big tabular numerals, quiet chrome (Control-Tower strip) ---- */
.niy-kpi,.geo-kpi,.qa-card{background:var(--gm-card)!important;border:1px solid var(--gm-hair)!important;box-shadow:none!important;border-radius:var(--ds-r-s)}
.niy-kpi:hover,.qa-card:hover{border-color:var(--gm-hair-2)!important}
.niy-kpi-k,.geo-kpi-k,.qa-k{text-transform:uppercase;letter-spacing:.13em;font-size:10px;color:var(--gm-ink-3)}
.niy-kpi-v,.geo-kpi-v,.qa-t{font-variant-numeric:tabular-nums;letter-spacing:-.015em}
/* ---- chart cards: hairline surfaces, small-caps titles ---- */
.niy-chart{background:var(--gm-card)!important;border:1px solid var(--gm-hair)!important;box-shadow:none!important}
.niy-chart-hd{border-bottom:1px solid var(--gm-hair)}
.niy-chart-t{text-transform:uppercase;letter-spacing:.13em;font-size:10.5px;color:var(--gm-ink-3)}
/* ---- data bars: count chip + hairline track (histogram rows) ---- */
.bar-row{align-items:center}
.bar-fill{border-radius:1px}
/* ---- tables: dense, zebra-faint, numerals aligned ---- */
#detail table{border-collapse:collapse}
#detail thead th{text-transform:uppercase;letter-spacing:.12em;font-size:10px;color:var(--gm-ink-3);border-bottom:1px solid var(--gm-hair-2)}
#detail tbody td{font-variant-numeric:tabular-nums;border-bottom:1px solid var(--gm-hair)}
#detail tbody tr:hover{background:var(--gm-panel)}
/* ---- accordion cards ---- */
.niy-acc-head{transition:background-color .12s var(--ds-ease)!important}
.niy-acc-head:hover{background:var(--gm-panel)}
.niy-acc-count{font-variant-numeric:tabular-nums}
.open>.niy-acc-head{box-shadow:inset 2px 0 0 var(--ds-accent)}
/* ---- buttons + inputs: hairline chrome, wash hover, pressed inset ---- */
.toolbar-btn,.scope-action-btn{transition:background-color .12s,border-color .12s,color .12s!important}
.toolbar-btn:hover,.scope-action-btn:hover{background:var(--gm-panel)}
.toolbar-btn:active,.scope-action-btn:active{box-shadow:inset 0 1px 3px rgba(0,0,0,.4)}
#detail select,#detail input[type=text],#detail input[type=search]{border:1px solid var(--gm-hair-2)!important;transition:border-color .12s,box-shadow .12s}
#detail select:focus,#detail input[type=text]:focus,#detail input[type=search]:focus{border-color:var(--ds-accent-line)!important;box-shadow:0 0 0 2px var(--ds-accent-dim)}
/* ---- alerts: severity tint, maroon-card style, never a wall of red ---- */
.sb-alert{background:rgba(229,72,77,.07)!important;border:1px solid rgba(229,72,77,.30)!important;box-shadow:inset 2px 0 0 var(--gm-red)!important;border-radius:var(--ds-r-s)}
/* ---- ticker: contained paint, tabular timestamps ---- */
.ticker-item{contain:content}
.ticker-item .ts{font-variant-numeric:tabular-nums;color:var(--gm-ink-3)}
/* ---- tabs: live underline, no colour noise ---- */
.tab{transition:background-color .12s,color .12s!important}
.tab.active .tab-label{text-shadow:0 0 12px rgba(127,176,255,.35)}
/* ---- motion discipline + perf ---- */
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.001s!important;transition-duration:.001s!important}}
/* ---- V2: the moves you can see from across the room ---- */
/* active tier tab: Gotham underline */
.tab.active{box-shadow:inset 0 -2px 0 var(--ds-accent)}
/* chart/section titles: accent tick, like Gotham section markers */
.niy-chart-t::before{content:"";display:inline-block;width:3px;height:9px;margin-right:7px;background:var(--ds-accent);border-radius:1px;vertical-align:-1px}
/* histogram bars: the Gotham red->amber ramp (reference: MAP event histogram).
   Only the untoned default bars — .g/.r/.a tone classes keep their semantics. */
.niy-dist-bar:not(.g):not(.r):not(.a){background:linear-gradient(90deg,#e5484d,#e0913f 72%,#e5c53f);box-shadow:0 0 6px rgba(229,72,77,.22)}
.niy-dist-row:hover .niy-dist-bar{filter:brightness(1.28)}
.niy-dist-val{font-variant-numeric:tabular-nums;color:var(--gm-ink-3)}
.niy-dist-row:hover .niy-dist-val{color:inherit}
.niy-dist-track{background:rgba(148,166,196,.07);border-radius:1px}
/* KPI values: Control-Tower scale */
.niy-kpi-v{font-size:clamp(21px,1.8vw,30px)!important;font-weight:600}
.geo-kpi-v{font-weight:600}
/* live-feed TIME column was clipped mid-value — data must never truncate */
.niy-col-feed td:last-child,.niy-col-feed th:last-child{white-space:nowrap;min-width:12ch}
/* zebra so dense tables read in rows, not soup */
#detail tbody tr:nth-child(even){background:var(--ds-zebra)}
/* ============ BLUEPRINT — Palantir's exact palette (Blueprint 5 hexes) ============ */
:root{
  /* surfaces (dark-gray scale) */
  --bp-dg1:#1C2127; --bp-dg2:#252A31; --bp-dg3:#2F343C; --bp-dg4:#383E47; --bp-dg5:#404854;
  /* chrome (gray scale) */
  --bp-g1:#5F6B7C; --bp-g2:#738091; --bp-g3:#8F99A8; --bp-g4:#ABB3BF; --bp-g5:#C5CBD3;
  /* text on dark (light-gray scale) */
  --bp-lg1:#D3D8DE; --bp-lg2:#DCE0E5; --bp-lg3:#E5E8EB; --bp-lg4:#EDEFF2; --bp-lg5:#F6F7F9;
  /* intents */
  --bp-blue1:#184A90; --bp-blue2:#215DB0; --bp-blue3:#2D72D2; --bp-blue4:#4C90F0; --bp-blue5:#8ABBFF;
  --bp-green1:#165A36; --bp-green2:#1C6E42; --bp-green3:#238551; --bp-green4:#32A467; --bp-green5:#72CA9B;
  --bp-orange1:#77450D; --bp-orange2:#935610; --bp-orange3:#C87619; --bp-orange4:#EC9A3C; --bp-orange5:#FBB360;
  --bp-red1:#8E292C; --bp-red2:#AC2F33; --bp-red3:#CD4246; --bp-red4:#E76A6E; --bp-red5:#FA999C;
  /* extended data hues */
  --bp-vermilion:#D33D17; --bp-rose:#DB2C6F; --bp-violet:#9D3F9D; --bp-indigo:#7961DB;
  --bp-cerulean:#147EB3; --bp-turquoise:#00A396; --bp-forest:#29A634; --bp-lime:#8EB125;
  --bp-gold:#D1980B; --bp-sepia:#946638;
  /* dark-theme elevation (Blueprint) */
  --bp-el1:0 0 0 1px rgba(17,20,24,.40), 0 1px 1px rgba(17,20,24,.50);
  --bp-el2:0 0 0 1px rgba(17,20,24,.40), 0 1px 1px rgba(17,20,24,.50), 0 2px 6px rgba(17,20,24,.40);
  --bp-el3:0 0 0 1px rgba(17,20,24,.40), 0 2px 4px rgba(17,20,24,.50), 0 8px 24px rgba(17,20,24,.50);
  /* atomic layers over the Niyantran base (theme preserved) */
  --L1:rgba(37,42,49,.50);  /* pane   (dg2 wash) */
  --L2:rgba(47,52,60,.55);  /* card   (dg3 wash) */
  --L3:rgba(56,62,71,.65);  /* raised (dg4 wash) */
  --L4:#252A31;             /* overlay, solid    */
  --ink-hi:var(--bp-lg5); --ink:var(--bp-lg2); --ink-lo:var(--bp-g3); --ink-faint:var(--bp-g1);
}
/* --- atoms: cards (L2, elevation-1, raise on hover) --- */
.niy-kpi,.geo-kpi,.qa-card,.niy-chart{background:var(--L2)!important;box-shadow:var(--bp-el1)!important;border:1px solid rgba(143,153,168,.14)!important}
.niy-kpi:hover,.qa-card:hover,.niy-chart:hover{background:var(--L3)!important;border-color:rgba(143,153,168,.22)!important}
/* --- atoms: text hierarchy --- */
.niy-kpi-v,.geo-kpi-v{color:var(--ink-hi)}
.niy-kpi-k,.geo-kpi-k,.qa-k,.niy-chart-t,#detail thead th,.sidebar-group-label{color:var(--ink-lo)}
.niy-dist-val,.ticker-item .ts{color:var(--ink-lo)}
/* --- atoms: intent colours (KPI tone classes map to exact Blueprint) --- */
.sig-red,.niy-kpi-v.sig-red{color:var(--bp-red4)!important}
.sig-amber,.niy-kpi-v.sig-amber{color:var(--bp-orange4)!important}
.sig-green,.niy-kpi-v.sig-green{color:var(--bp-green4)!important}
/* --- atoms: distribution bars — Blueprint intent ramp + exact tones --- */
.niy-dist-bar:not(.g):not(.r):not(.a){background:linear-gradient(90deg,var(--bp-red3),var(--bp-orange4) 72%,var(--bp-gold))}
.niy-dist-bar.r{background:var(--bp-red3)!important}
.niy-dist-bar.a{background:var(--bp-orange4)!important}
.niy-dist-bar.g{background:var(--bp-green4)!important}
/* --- atoms: selection + accents unified on Blueprint blue --- */
.feat-item.active{background:rgba(45,114,210,.14)}
.feat-item.active::before{background:var(--bp-blue4);box-shadow:0 0 8px rgba(76,144,240,.5)}
.tab.active{box-shadow:inset 0 -2px 0 var(--bp-blue4)}
.niy-chart-t::before{background:var(--bp-blue4)}
.sidebar-group-label::after{background:linear-gradient(90deg,rgba(76,144,240,.55),rgba(76,144,240,.04))}
/* --- atoms: inputs (Blueprint focus ring) --- */
#detail select:focus,#detail input[type=text]:focus,#detail input[type=search]:focus{border-color:var(--bp-blue4)!important;box-shadow:0 0 0 2px rgba(76,144,240,.28)!important}
/* --- atoms: menus, tooltips = overlay layer (L4, elevation-3) --- */
.niy-more-menu,#niyTip{background:var(--L4)!important;border:1px solid rgba(143,153,168,.20)!important;box-shadow:var(--bp-el3)!important}
/* --- atoms: alert intent (Blueprint red, quiet) --- */
.sb-alert{background:rgba(205,66,70,.08)!important;border-color:rgba(205,66,70,.35)!important;box-shadow:inset 2px 0 0 var(--bp-red3)!important}


