html:root{ --ds-accent:#7A9254; --ds-accent-dim:rgba(122,146,84,.15); --ds-accent-line:rgba(122,146,84,.5); }
:root{
  /* surfaces — exact PDF hexes */
  --black:#0B0F0D;            /* App Background · Midnight Black   */
  --panel:#121714;            /* Sidebar · Gunmetal                */
  --panel-2:#161B18;          /* Top Bar · Tactical Charcoal       */
  --panel-3:#232B27;          /* Primary Cards · Dark Slate        */
  --line:#414C45;             /* Borders · Military Steel          */
  --line-bright:#51584F;      /* Roads · Concrete Grey             */
  /* text */
  --white:#F2F5F1; --fg:#E6EAE5; --fg-dim:#A7AEA7; --fg-faint:#747C76;
  /* type: Inter for UI, JetBrains Mono stays for data */
  --font-display:'Inter','Segoe UI',system-ui,sans-serif;
  /* accents */
  --ds-accent:#7A9254; --ds-accent-dim:rgba(122,146,84,.15); --ds-accent-line:rgba(122,146,84,.5);
  --gm-hair:rgba(65,76,69,.6); --gm-hair-2:#414C45; --gm-panel:rgba(52,62,56,.55); --gm-card:#232B27; --gm-ink-3:#747C76;
  --gm-red:#982F2F; --gm-amber:#B18A42; --gm-yellow:#A4C76D; --gm-green:#5E8A52; --gm-cyan:#4B7D73; --gm-blue:#7A9254;
  /* layer system remapped to the PDF card scale */
  --L1:#161B18; --L2:#232B27; --L3:#343E38; --L4:#2B332F;
  --ink-hi:#E6EAE5; --ink:#E6EAE5; --ink-lo:#A7AEA7; --ink-faint:#747C76;
}
/* ---- surfaces & cards (Dark Slate on Gunmetal, Military Steel hairlines) ---- */
.niy-kpi,.geo-kpi,.qa-card,.niy-chart{background:#232B27!important;border:1px solid #414C45!important;box-shadow:0 1px 1px rgba(11,15,13,.5)!important}
.niy-kpi:hover,.qa-card:hover,.niy-chart:hover{background:#343E38!important;border-color:#51584F!important}
.niy-more-menu,#niyTip{background:#2B332F!important;border:1px solid #414C45!important}
/* ---- accents: Battle Green active / Olive selection ---- */
.feat-item.active{background:rgba(122,146,84,.14)}
.feat-item.active::before{background:#7A9254;box-shadow:0 0 8px rgba(122,146,84,.55)}
.tab.active{box-shadow:inset 0 -2px 0 #647C3C}
.tab.active .tab-label{text-shadow:0 0 12px rgba(150,184,109,.35)}
.niy-chart-t::before{background:#7A9254}
.sidebar-group-label::after{background:linear-gradient(90deg,rgba(122,146,84,.6),rgba(122,146,84,.05))}
#detail select:focus,#detail input[type=text]:focus,#detail input[type=search]:focus{border-color:#7A9254!important;box-shadow:0 0 0 2px rgba(122,146,84,.25)!important}
::selection{background:rgba(164,199,109,.3)}
:focus-visible{outline:1px solid rgba(122,146,84,.6)!important}
/* ---- intents (exact PDF) ---- */
.sig-red,.niy-kpi-v.sig-red{color:#C1524B!important}          /* emergency, lifted for contrast */
.sig-amber,.niy-kpi-v.sig-amber{color:#B18A42!important}       /* Brass Gold  */
.sig-green,.niy-kpi-v.sig-green{color:#72C36B!important}       /* Signal Green */
.niy-dist-bar:not(.g):not(.r):not(.a){background:linear-gradient(90deg,#647C3C,#96B86D 70%,#A4C76D);box-shadow:0 0 6px rgba(122,146,84,.3)}
.niy-dist-bar.r{background:#982F2F!important}
.niy-dist-bar.a{background:#B18A42!important}
.niy-dist-bar.g{background:#5E8A52!important}
.sb-alert{background:rgba(123,46,46,.12)!important;border:1px solid rgba(152,47,47,.5)!important;box-shadow:inset 2px 0 0 #982F2F!important}
.tab-live,.feat-item .live{color:#72C36B!important}
/* ---- typography per the PDF table ---- */
.wordmark,.login-title,h1,h2,h3,.niy-acc-name,.qa-d{font-family:var(--font-display)!important}
.tab,.tab-label,.toolbar-btn,.scope-action-btn,.feat-item,.sidebar-group-label,.niy-kpi-k,.geo-kpi-k,.qa-k,.niy-chart-t,.beta-badge{font-family:var(--font-display)!important}
.toolbar-btn,.scope-action-btn{font-weight:500;color:#9DB075}
.toolbar-btn:hover,.scope-action-btn:hover{color:#A4C76D}
.niy-kpi-v,.geo-kpi-v,.qa-t,#detail td,.ticker-item,.niy-dist-val{font-family:var(--font-mono)!important}
/* ---- header: logo only, wordmark removed, search claims the space ---- */
.brand img+.wordmark,.brand:has(img) .wordmark{display:block!important;font-size:15px;letter-spacing:.24em;color:var(--fg)}
.brand img{width:auto!important;height:38px!important;animation:none!important;filter:drop-shadow(0 0 10px rgba(243,120,94,.35))!important}
/* ---- maps: Deep Slate Blue water (PDF Map Water) ---- */
.niy-seaborne-on canvas,#niyGeoDossier canvas{background:#162128!important;border-radius:inherit}
/* ---- declutter: the status dots doubled up with LIVE badges and colour rails,
   and clipped at container edges; the section count chips were visual noise ---- */
.feat-item .dot{display:none!important}
#detail .dot{display:none!important}
.sidebar-group-label .niy-acc-count{display:none!important}
/* ---- big monitors: fluid, never distorted ---- */
html,body{overflow-x:hidden}
@media (min-width:1720px){ .main{max-width:none} #detail{overflow-x:hidden} }



:root{
  --grad-brand:linear-gradient(120deg,#FF7A80,#F3785E 45%,#E8874F 75%,#F5A95C);
  --grad-aurora:linear-gradient(90deg,#D95A54,#F3785E 42%,#EE8E52 72%,#F5B36A);
  --grad-live:linear-gradient(90deg,#F3785E,#FF7A80);
  --grad-vert:linear-gradient(180deg,#FF7A80,#ED6050 55%,#CF7437);
}
/* ---- charts: aurora bars with glow, gradient hero numerals, lit card top-edge ---- */
.niy-dist-bar:not(.g):not(.r):not(.a){background:var(--grad-aurora)!important;box-shadow:0 0 8px rgba(240,118,90,.35)}
.niy-dist-row:hover .niy-dist-bar:not(.g):not(.r):not(.a){box-shadow:0 0 12px rgba(240,118,90,.55)}
.niy-kpi-v:not(.sig-red):not(.sig-amber):not(.sig-green),.geo-kpi-v:not(.sig-red):not(.sig-amber):not(.sig-green){
  background:var(--grad-brand);-webkit-background-clip:text;background-clip:text;color:transparent!important}
.niy-chart{position:relative;overflow:hidden}
.niy-chart::before{content:"";position:absolute;top:0;left:0;right:0;height:2px;background:var(--grad-aurora);opacity:.85}
.niy-chart-t::before{background:var(--grad-vert)}
/* ---- live ticker: gradient baseline + breathing LIVE dot (LIVE stays palette green) ---- */
.ticker-wrap{position:relative}
.ticker-wrap::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--grad-aurora);opacity:.6;pointer-events:none}
.tab-live,.feat-item .live{color:#72C36B!important;text-shadow:0 0 8px rgba(114,195,107,.55);font-weight:700}
/* ---- navigation: gradient underline + gradient notch + section bars ---- */
.tab.active{box-shadow:none;background-image:linear-gradient(90deg,#F3785E,#FF7A80);background-repeat:no-repeat;background-size:100% 2px;background-position:bottom}
.feat-item.active::before{background:var(--grad-vert);box-shadow:0 0 10px rgba(240,118,90,.5)}
.sidebar-group-label::after{background:var(--grad-aurora);opacity:.75}
/* ---- accents that sell it: search focus, mode toggles, scrollbar, brand glow ---- */
.cmdbar:focus-within{box-shadow:0 0 0 1px rgba(243,120,94,.45),0 0 18px rgba(255,122,128,.18)}
.sb-mode.active{background:linear-gradient(120deg,rgba(255,122,128,.2),rgba(224,147,79,.2))!important;border-color:rgba(240,118,90,.55)!important}
*::-webkit-scrollbar-thumb{background:linear-gradient(180deg,#8A4A42,#9C6238);border:2px solid transparent;background-clip:content-box}
*::-webkit-scrollbar-thumb:hover{background:linear-gradient(180deg,#F3785E,#E0934F);border:2px solid transparent;background-clip:content-box}
.brand img{width:auto!important;height:38px!important;filter:drop-shadow(0 0 12px rgba(243,120,94,.4))!important}
/* ---- alert stays serious: no gradients on maroon ---- */



/* content never hard-swaps: new views and analytics ease in */
@keyframes niyIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
#detail>.niy-split,#detail>.toolbar{animation:niyIn .22s var(--ds-ease) both}
.niy-pane-analytics .niy-kpis-wrap,.niy-pane-analytics .niy-chart{animation:niyIn .26s var(--ds-ease) both}
.niy-pane-analytics{scroll-behavior:smooth}
.suggest-item .suggest-title{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media (prefers-reduced-motion:reduce){#detail>*,.niy-pane-analytics .niy-kpis-wrap,.niy-pane-analytics .niy-chart{animation:none!important}}



/* ============ TOOLBAR — one quiet line: ghost controls, one soft field, ONE accent ============ */
#detail .toolbar{align-items:center;gap:4px}
#detail .toolbar .filter-group{background:var(--gm-panel);border:1px solid var(--gm-hair);border-radius:8px;padding:2px 8px;transition:border-color .15s}
#detail .toolbar .filter-group:focus-within{border-color:#7A9254}
#detail .toolbar .filter-group .filter-input{border:0!important;background:transparent!important;box-shadow:none!important;outline:none!important}
#detail .toolbar .column-filters{gap:2px}
#detail .toolbar .column-filters select{background:transparent!important;border:1px solid transparent!important;border-radius:6px;color:var(--fg-dim)!important;padding:4px 8px;cursor:pointer;transition:background-color .12s,color .12s}
#detail .toolbar .column-filters select:hover{background:var(--gm-panel)!important;color:var(--fg)!important}
#detail .toolbar .toolbar-btn{background:transparent!important;border:1px solid transparent!important;border-radius:6px}
#detail .toolbar .toolbar-btn:hover{background:var(--gm-panel)!important;border-color:var(--gm-hair)!important}
#detail .toolbar .toolbar-btn.niy-primary{background:#647C3C!important;border-color:#7A9254!important;color:#0B0F0D!important;font-weight:600}
#detail .toolbar .toolbar-btn.niy-primary:hover{background:#7A9254!important}
/* ============ SIDEBAR — auto-collapsed monogram rail, expands on HOVER as an overlay ============ */
body.sb-hoverail .main{grid-template-columns:64px 1fr!important;transition:none!important}
body.sb-hoverail #sidebar{width:64px!important;min-width:64px!important;position:relative;z-index:75;overflow:visible;padding:0!important;border-right:0!important;background:transparent!important}
body.sb-hoverail .niy-sb-panel{position:absolute;left:0;top:0;bottom:0;width:64px;overflow:hidden;display:flex;flex-direction:column;background:var(--panel);border-right:1px solid var(--gm-hair);transition:width .2s var(--ds-ease) .18s,box-shadow .2s var(--ds-ease) .18s}
body.sb-hoverail #sidebar:hover .niy-sb-panel,body.sb-hoverail #sidebar:focus-within .niy-sb-panel{width:300px;transition-delay:0s;box-shadow:16px 0 44px rgba(0,0,0,.5)}
body.sb-hoverail .niy-sb-panel>#sidebarList{flex:1;overflow-y:auto;overflow-x:hidden;width:300px}
body.sb-hoverail .niy-sb-panel>.sidebar-filter{width:300px}
body.sb-hoverail #sidebar .label,body.sb-hoverail #sidebar .fi-meta,body.sb-hoverail #sidebar .niy-acc-name,body.sb-hoverail #sidebar .niy-acc-meta,body.sb-hoverail #sidebar .filter-input,body.sb-hoverail #sidebar .niy-sb-toggle{transition:opacity .14s ease}
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .label,
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .fi-meta,
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .niy-acc-name,
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .niy-acc-meta,
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .filter-input,
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .niy-sb-toggle{opacity:0;pointer-events:none}
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .feat-item::after{content:attr(data-mono);position:absolute;left:0;width:64px;text-align:center;font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--fg-dim)}
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .feat-item.active::after{color:#A4C76D}
@media (prefers-reduced-motion:reduce){body.sb-hoverail #sidebar{transition:none}}



/* SHAPE LOCK: controls 6px / containers 8px / overlays 10px / status badges pill.
   Documented rule per the shape-consistency lock; no other radii allowed. */
.niy-chart,.niy-kpi,.geo-kpi,.qa-card,.sb-alert,.cmdbar,.niy-pane{border-radius:8px!important}
.niy-acc{border-radius:8px!important;overflow:hidden}
.niy-more-menu,#niyTip,#searchSuggest{border-radius:10px!important;overflow:hidden}
/* ACCENT LOCK: the last blue survivor. Info pills move to Military Teal (PDF intent). */
.niy-pill-b{background:rgba(75,125,115,.16)!important;border-color:rgba(75,125,115,.45)!important;color:#8FBFB4!important}
/* overlay parity: the search suggest panel joins the L4 overlay layer */
#searchSuggest{background:#2B332F!important;border:1px solid #414C45!important;box-shadow:0 0 0 1px rgba(17,20,24,.4),0 2px 4px rgba(17,20,24,.5),0 8px 24px rgba(17,20,24,.5)!important}
#searchSuggest .suggest-sec{color:#747C76;letter-spacing:.14em;font-size:10px}
#searchSuggest .suggest-item:hover,#searchSuggest .suggest-item.active{background:#343E38}
#searchSuggest .suggest-hit{font-variant-numeric:tabular-nums;color:#A4C76D}
/* rail rest-state: the filter row is a single centered glyph, never a clipped input */
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .niy-sb-panel>.sidebar-filter{display:none!important}
body.sb-hoverail #sidebar:not(:hover):not(:focus-within) .niy-sb-panel>.sidebar-filter>*{display:none!important}
/* one hairline under the feature header, not two stacked lines */
#detail .toolbar{border-bottom:0!important}
/* severity rails need breathing room from the text, terminal-wide */
#detail table.sample tbody td:first-child,.niy-col-feed table tbody td:first-child{padding-left:12px!important}



#nDesk{flex-direction:column!important}
/* the terminal shell kept its full viewport height under Home/Studio, leaving ~600px of dead black above them */
body.niy-alt-view .terminal{height:auto!important;min-height:0!important;transition:none!important}
#niyHome{width:100%;max-width:1720px;margin:0 auto;padding:16px 28px 40px;font-family:var(--font-display);box-sizing:border-box}
#nhGrid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:22px;align-items:start}
#niyHome .nh-sec{margin-top:26px}
#niyHome .nh-h{font-size:19px;font-weight:700;color:var(--fg);margin:0 0 12px;display:flex;align-items:baseline;gap:10px}
#niyHome .nh-h small{font-size:9.5px;font-weight:600;color:var(--fg-faint);letter-spacing:.16em;text-transform:uppercase}
/* market strip */
#nhStrip{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px;min-height:34px}
#nhStrip .nh-q{display:flex;gap:8px;align-items:baseline;background:var(--panel-3);border:1px solid var(--line);border-radius:8px;padding:7px 12px;font-family:var(--font-mono)}
#nhStrip .nh-q b{font-size:12px;color:var(--fg)}#nhStrip .nh-q span{font-size:12px;color:var(--fg-dim)}
.up{color:#72C36B!important}.dn{color:#C1524B!important}
/* hero */
#nhHero{position:relative;border:1px solid var(--line);border-radius:10px;background:var(--panel-3);overflow:hidden}
.nh-slide{display:none;grid-template-columns:1.05fr 1fr;min-height:340px}
.nh-slide.on{display:grid}
.nh-slide .txt{padding:34px 38px;display:flex;flex-direction:column;justify-content:center;gap:15px}
.nh-slide img{width:100%;height:100%;object-fit:cover;min-height:340px}
.nh-slide h2{margin:0;font-size:clamp(24px,2.2vw,36px);line-height:1.12;color:var(--fg);cursor:pointer;font-weight:700}
.nh-slide h2:hover{color:#A4C76D}
.nh-slide p{margin:0;font-size:14.5px;line-height:1.55;color:var(--fg-dim);max-width:56ch}
.nh-cta{display:inline-flex;align-items:center;gap:8px;align-self:flex-start;background:#647C3C;border:1px solid #7A9254;color:#0B0F0D;font-weight:700;font-size:12.5px;border-radius:6px;padding:9px 18px;cursor:pointer;font-family:var(--font-display)}
.nh-cta:hover{background:#7A9254}
.nh-dots{position:absolute;left:38px;bottom:20px;display:flex;gap:7px}
.nh-dots i{width:24px;height:3px;border-radius:2px;background:var(--line-bright);cursor:pointer}
.nh-dots i.on{background:#A4C76D}
.nh-tag{display:inline-flex;gap:8px;align-items:center;font-size:10px;font-weight:700;letter-spacing:.18em;color:#B18A42}
.nh-tag.inv{color:#C1524B}.nh-tag.rep{color:#4B7D73}
.nh-tag .sim{background:rgba(122,146,84,.16);border:1px solid rgba(122,146,84,.45);color:#A4C76D;border-radius:999px;padding:2px 9px;letter-spacing:.1em}
/* zine cards */
#nhZine{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.nh-card{background:var(--panel-3);border:1px solid var(--line);border-radius:10px;overflow:hidden;cursor:pointer;transition:border-color .15s,transform .15s}
.nh-card:hover{border-color:#51584F;transform:translateY(-2px)}
.nh-card img{width:100%;height:160px;object-fit:cover;display:block}
.nh-card .b{padding:13px 15px 15px}
.nh-card h3{margin:8px 0 6px;font-size:14.5px;line-height:1.3;color:var(--fg)}
.nh-card p{margin:0;font-size:11.5px;line-height:1.45;color:var(--fg-faint);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.nh-card .meta{margin-top:10px;font-size:10px;color:var(--fg-faint);font-family:var(--font-mono)}
/* wires w/ thumbs */
#nhWires{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.nh-wire{background:var(--panel-3);border:1px solid var(--line);border-radius:10px;padding:16px 18px}
.nh-wire h4{margin:0 0 2px;font-size:12px;letter-spacing:.14em;color:var(--fg);font-weight:700}
.nh-wire .src{font-size:10px;color:var(--fg-faint);font-family:var(--font-mono);margin-bottom:8px}
.nh-wire ul{list-style:none;margin:0;padding:0}
.nh-wire li{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid var(--line);align-items:flex-start}
.nh-wire li:last-child{border-bottom:0}
.nh-wire .th{width:74px;height:52px;flex:0 0 auto;border-radius:6px;object-fit:cover;background:var(--panel-2);border:1px solid var(--line)}
.nh-wire a{color:var(--fg);text-decoration:none;font-size:12.5px;line-height:1.4;display:block}
.nh-wire a:hover{color:#A4C76D}
.nh-wire .ago{font-size:10px;color:var(--fg-faint);font-family:var(--font-mono);margin-top:3px;display:block}
.nh-wire .err{font-size:11.5px;color:var(--fg-faint);line-height:1.5}
.nh-wire .err a{display:inline;color:#7A9254}
/* right rail */
#nhRail{display:flex;flex-direction:column;gap:18px;position:sticky;top:12px}
.nh-box{background:var(--panel-3);border:1px solid var(--line);border-radius:10px;padding:15px 17px}
.nh-box .bh{font-size:11px;letter-spacing:.16em;font-weight:700;color:#C1524B;margin-bottom:10px}
.nh-box .bh.g{color:#A4C76D}
#nhLatest li{list-style:none;display:flex;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}
#nhLatest li:last-child{border-bottom:0}
#nhLatest ul{margin:0;padding:0}
#nhLatest .t{font-size:10px;color:var(--fg-faint);font-family:var(--font-mono);flex:0 0 46px;padding-top:2px}
#nhLatest a{color:var(--fg);font-size:12px;line-height:1.4;text-decoration:none}
#nhLatest a:hover{color:#A4C76D}
#nhLatest .s{display:block;font-size:9.5px;letter-spacing:.08em;color:var(--fg-faint);margin-top:2px}
#nhMoves table{width:100%;border-collapse:collapse;font-family:var(--font-mono)}
#nhMoves td{padding:7px 0;border-bottom:1px solid var(--line);font-size:12px;color:var(--fg-dim)}
#nhMoves tr:last-child td{border-bottom:0}
#nhMoves td:last-child{text-align:right;font-weight:700}
#nhFocus{display:flex;gap:8px;flex-wrap:wrap}
#nhFocus button{background:transparent;border:1px solid var(--line);border-radius:999px;color:var(--fg-dim);font-size:11.5px;padding:6px 13px;cursor:pointer;font-family:var(--font-display)}
#nhFocus button:hover{border-color:#7A9254;color:#A4C76D}
/* ---- FULL-PAGE reader ---- */
#nzPage{display:none;width:100%;max-width:1720px;margin:0 auto;padding:14px 28px 60px;box-sizing:border-box;font-family:var(--font-display)}
#nzPage.on{display:block}
#niyHome.off{display:none}
#nzPage .top{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}
#nzPage .back{background:transparent;border:1px solid var(--line);border-radius:6px;color:var(--fg-dim);padding:8px 16px;cursor:pointer;font-size:12.5px;font-family:var(--font-display)}
#nzPage .back:hover{border-color:#7A9254;color:#A4C76D}
#nzPage article{max-width:820px;margin:0 auto}
#nzPage h1{font-size:clamp(28px,3.4vw,44px);line-height:1.1;color:var(--fg);margin:14px 0 14px;font-weight:800}
#nzPage .dek{font-size:17px;color:var(--fg-dim);line-height:1.55;margin-bottom:10px}
#nzPage .meta{font-size:11px;color:var(--fg-faint);font-family:var(--font-mono);margin-bottom:26px;padding-bottom:14px;border-bottom:1px solid var(--line)}
#nzPage img.lead{width:100%;border-radius:10px;border:1px solid var(--line);margin-bottom:28px}
#nzPage .body p{font-size:15.5px;line-height:1.8;color:#CDD4CC;margin:0 0 18px}
#nzPage .more{max-width:820px;margin:44px auto 0;border-top:1px solid var(--line);padding-top:18px}
#nzPage .more .nh-h{font-size:15px}
#nzPage .more #nhMore{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
/* simulators (shared with reader) */
.nz-sim{border:1px solid rgba(122,146,84,.5);background:#141A14;border-radius:10px;padding:22px 24px;margin:26px 0}
.nz-sim .st{font-size:11px;letter-spacing:.18em;color:#A4C76D;font-weight:700;margin-bottom:4px}
.nz-sim .note{font-size:10.5px;color:var(--fg-faint);margin-bottom:14px;line-height:1.5}
.nz-sim .kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px}
.nz-sim .kpi{background:var(--panel-3);border:1px solid var(--line);border-radius:6px;padding:10px 12px}
.nz-sim .kpi b{display:block;font-size:20px;color:var(--fg);font-family:var(--font-mono)}
.nz-sim .kpi span{font-size:9.5px;letter-spacing:.1em;color:var(--fg-faint)}
.nz-sim .row{display:flex;align-items:center;gap:10px;margin:5px 0}
.nz-sim .row .lb{width:170px;font-size:11.5px;color:var(--fg-dim);flex:0 0 auto}
.nz-sim .row .tr{flex:1;height:14px;background:rgba(148,166,196,.07);border-radius:2px}
.nz-sim .row .fl{height:100%;border-radius:2px;background:linear-gradient(90deg,#647C3C,#96B86D 70%,#A4C76D);transition:width .35s var(--ds-ease)}
.nz-sim .row .vl{width:74px;text-align:right;font-family:var(--font-mono);font-size:11.5px;color:#A4C76D;flex:0 0 auto}
.nz-sim .tgl{display:flex;gap:6px;margin:4px 0 12px}
.nz-sim .tgl button{background:transparent;border:1px solid var(--line);border-radius:6px;color:var(--fg-dim);font-size:11px;padding:5px 12px;cursor:pointer}
.nz-sim .tgl button.on{background:#647C3C;border-color:#7A9254;color:#0B0F0D;font-weight:700}
.nz-sim input[type=range]{width:100%;accent-color:#7A9254}
.nz-sim .sl label{font-size:11px;color:var(--fg-dim);display:flex;justify-content:space-between;margin-top:10px}
.nz-sim .sl label b{color:#A4C76D;font-family:var(--font-mono)}
.nz-sim .gauge{margin-top:14px;padding:12px;background:var(--panel-3);border:1px solid var(--line);border-radius:6px}
.nz-sim .gauge .bar{height:16px;background:rgba(148,166,196,.07);border-radius:3px;overflow:hidden}
.nz-sim .gauge .fill{height:100%;transition:width .3s,background .3s}
.nz-sim .gauge .cap{display:flex;justify-content:space-between;font-size:10px;color:var(--fg-faint);margin-top:6px;gap:10px}
@media(max-width:1280px){#nhGrid{grid-template-columns:1fr}#nhRail{position:static;flex-direction:row;flex-wrap:wrap}#nhRail .nh-col{flex:1 1 300px}#nhRail .nh-box{flex:0 0 auto}}
@media(max-width:1100px){#nhZine{grid-template-columns:repeat(2,1fr)}}
@media(max-width:760px){#nhZine,#nhWires,#nzPage .more #nhMore{grid-template-columns:1fr}.nh-slide{grid-template-columns:1fr}.nh-slide img{min-height:200px}}
/* theme flips must be instant on these large surfaces (a broad transition:all was animating/freezing them) */
#nhHero,.nh-wire,.nh-box,#nhAds,.nh-q,.nz-sim,#nzPage,.nh-slide .txt{transition:none!important}
/* ---- ad slider (Home only) ---- */
#nhAds{position:relative;margin-bottom:18px;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--panel-3);height:auto;aspect-ratio:1720/404}
#nhAds .ad-slide{display:none;position:absolute;inset:0;align-items:center;justify-content:center}
#nhAds .ad-slide.on{display:flex}
