.pig-tl-bars{position:relative;height:48px;display:flex;align-items:flex-end;gap:1px;cursor:crosshair}
.pig-tl-bar{flex:1;background:linear-gradient(180deg,#647C3C,#3a4a24);border-radius:1px 1px 0 0;min-height:2px;opacity:.5;transition:opacity .12s,background .12s}
.pig-tl-bar:hover{opacity:.85}
.pig-tl-bar.in{opacity:1;background:linear-gradient(180deg,#F3785E,#a8412a)}
.pig-tl-sel{position:absolute;top:0;bottom:0;background:rgba(243,120,94,.1);border-left:1.5px solid #F3785E;border-right:1.5px solid #F3785E;pointer-events:none}
.pig-tl-axis{display:flex;justify-content:space-between;font-family:var(--font-mono);font-size:9px;color:var(--fg-faint);padding-top:3px}


.brand img{filter:none!important;box-shadow:none!important;height:38px!important;width:auto!important;animation:none!important}


/* ==================================================================
   NIYANTRAN V2 — DESIGN SYSTEM (pass 1: editorial light foundation)
   Mockups = visual source of truth. Restrained · dense · institutional.
   Colour reserved for status / live / selection only.
   ================================================================== */
html:root, html:root[data-theme="light"], html:root[data-theme="dark"]{
  /* surfaces */
  --bg:#FFFFFF; --panel:#EEF1F3; --panel-2:#F6F7F9; --panel-3:#FFFFFF;
  --line:#E5E8EB; --line-bright:#D5DADF; --hairline:#ECEEF0;
  /* ink — hierarchy through weight+shade, not boxes */
  --fg:#15181B; --fg-dim:#525960; --fg-faint:#9AA1A8; --white:#0A0C0E;
  /* accent (logo orange) — interactive / live / selection ONLY */
  --accent:#EE5A2C; --accent-2:#FF6A3D; --ds-accent:#EE5A2C;
  --sel:rgba(238,90,44,.08); --sel-line:rgba(238,90,44,.5);
  /* status */
  --signal-red:#D93B2B; --signal-amber:#E79A24; --signal-green:#2FA254;
  --niy-live:#D93B2B;
  --font-display:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  --font-mono:'JetBrains Mono',ui-monospace,Menlo,Consolas,monospace;
}
body, .terminal{ background:#FFFFFF !important; color:#15181B; }
body{ -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility; }

/* ---- neutralise the dark surface layers ---- */
.topbar,.tabs,.scope-bar,#sidebar,.niy-sb-panel,header,.main,.detail,#detail,
.niy-box,.nh-box,.nh-card,.pig-timeline,.pig-canvas,.pig-right,.pig-left{
  background:transparent !important;
}
.terminal,.main{ background:#FFFFFF !important; }

/* ---- TOP BAR: compressed, editorial ---- */
.topbar{ border-bottom:1px solid var(--line) !important; padding:9px 20px !important; min-height:0 !important; }
.brand .wordmark{ color:var(--fg) !important; letter-spacing:.16em; font-weight:600; }
.cmdbar{ background:#FFFFFF !important; border:1px solid var(--line) !important; border-radius:10px !important; box-shadow:none !important; }
.cmdbar:focus-within{ border-color:var(--accent) !important; box-shadow:0 0 0 3px var(--sel) !important; }
.cmdbar input,.cmdbar input::placeholder{ color:var(--fg-dim) !important; }
.topbar-btn,.scope-action-btn,.toolbar-btn{ color:var(--fg-dim) !important; background:transparent !important; border-color:var(--line) !important; }
.topbar-btn:hover,.toolbar-btn:hover{ background:var(--panel-2) !important; color:var(--fg) !important; }

/* ---- SCOPE ticker + market strip: muted, mono, hairline sep ---- */
.scope-bar{ border-bottom:1px solid var(--hairline) !important; }
.scope-bar,.scope-bar *{ color:var(--fg-dim) !important; }
.scope-bar .scope-badge,.scope-bar [class*="badge"]{ background:var(--panel) !important; color:var(--fg-dim) !important; }

/* ---- TABS: text-first, quiet, active = ink + accent underline ---- */
.tabs{ border-bottom:1px solid var(--line) !important; }
.tab{ color:var(--fg-faint) !important; font-weight:500 !important; background:transparent !important; border:0 !important; }
.tab:hover{ color:var(--fg-dim) !important; background:transparent !important; }
.tab.active{ color:var(--fg) !important; font-weight:600 !important; }
.tab.active::after{ background:var(--accent) !important; height:2px !important; }
.tab .tab-ico svg,.tab svg{ stroke:currentColor !important; }
.beta-badge{ color:var(--fg-faint) !important; border-color:var(--line) !important; }

/* ---- SIDEBAR rail: icons quiet, selected = accent tick ---- */
#sidebar,.niy-sb-panel{ border-right:1px solid var(--line) !important; }
.feat-item{ color:var(--fg-dim) !important; }
.feat-item:hover{ background:var(--panel-2) !important; color:var(--fg) !important; }
.feat-item.active{ color:var(--fg) !important; background:var(--sel) !important; }
.feat-item.active::before{ background:var(--accent) !important; box-shadow:none !important; }
.sidebar-group-label{ color:var(--fg-faint) !important; }
.sidebar-group-label::after{ background:var(--hairline) !important; }

/* ---- TYPOGRAPHY: confident headings, disappearing metadata ---- */
.detail-title,h1{ font-weight:650 !important; letter-spacing:-.02em !important; color:var(--fg) !important; }
h2,h3,.nh-h,.niy-chart-t{ color:var(--fg) !important; }
.m,.meta,.ago,.uf-meta,.s,.detail-title-block .tags .tag,.section-label,.pill-row-label{ color:var(--fg-faint) !important; }
.body-text,.nh-card h3,td{ color:var(--fg-dim) !important; }

/* ---- FEEDS / TABLES: dense financial-terminal scanning ---- */
table.sample,.niy-col-feed table{ font-size:12.5px !important; }
table.sample thead th,.niy-col-feed thead th{ color:var(--fg-faint) !important; font-family:var(--font-mono) !important; font-size:10px !important; letter-spacing:.08em !important; text-transform:uppercase !important; font-weight:500 !important; background:#fff !important; border-bottom:1px solid var(--line) !important; }
table.sample tbody tr{ border-bottom:1px solid var(--hairline) !important; }
table.sample tbody tr:hover{ background:var(--panel-2) !important; }
table.sample td{ color:var(--fg) !important; padding:8px 12px !important; border:0 !important; }
table.sample td:first-child{ padding-left:14px !important; }
/* time / numeric columns → mono, muted, right-aligned feel */
table.sample td.time,table.sample td:last-child{ font-family:var(--font-mono) !important; color:var(--fg-faint) !important; }

/* ---- BORDERS: dramatically reduced. panels defined by alignment ---- */
.niy-box,.nh-box,.nh-card,.niy-kpi,.geo-kpi,.qa-card,.stat,.pig-metric,.pig-sec-card{
  background:var(--panel-3) !important; border:1px solid var(--line) !important; box-shadow:none !important;
}
.callout,.bill-panel,.niy-acc{ background:var(--panel-2) !important; border:0 !important; border-left:2px solid var(--line) !important; }

/* ---- BUTTONS: premium, quiet ---- */
.btn,button.primary,.qa-card{ transition:background .15s,border-color .15s,color .15s; }
.niy-pill-b,.tag.unique{ background:var(--sel) !important; border-color:var(--sel-line) !important; color:var(--accent) !important; }

/* ---- STATUS + LIVE: the only saturated colour ---- */
.up,.sig-green,.dot.ok{ color:var(--signal-green) !important; }
.dn,.sig-red{ color:var(--signal-red) !important; }
.sig-amber{ color:var(--signal-amber) !important; }
.live,.tab-live,.sb-dot,[class*="live-dot"]{ color:var(--niy-live) !important; text-shadow:none !important; }

/* ---- kill all glow / heavy shadow / gradient chrome from v1 ---- */
*{ text-shadow:none !important; }
.niy-chart::before,.ticker-wrap::after,.nh-h::before{ background:var(--accent) !important; opacity:1 !important; }
.brand img{ filter:none !important; }

/* ---- POLICY GRAPH (Gotham) → light institutional ---- */
#detail.pig-host,.pig-wrap{ background:#FFFFFF !important; }
.pig-timeline{ background:var(--panel-2) !important; border-top:1px solid var(--line) !important; }
.pig-node text{ fill:var(--fg-dim) !important; stroke:#fff !important; }
.pig-toolbar button{ background:#fff !important; border-color:var(--line) !important; color:var(--fg-dim) !important; }

/* ---- MOTION: invisible, 120-180ms ease-out ---- */
.tab,.feat-item,.nh-card,.btn,.topbar-btn,table.sample tr{ transition-duration:.14s !important; transition-timing-function:cubic-bezier(.22,.61,.36,1) !important; }

/* ---- ULTRAWIDE: expose info, don't inflate UI ---- */
@media(min-width:1900px){ .main{ grid-template-columns:300px 1fr !important; } }

/* ===== V2 PASS 2 — feeds & tables (dense professional terminal) ===== */
#detail table.sample{ border-collapse:separate !important; border-spacing:0 !important; width:100% !important; }
/* sticky, quiet, mono column headers */
#detail table.sample thead th{ position:sticky !important; top:0 !important; z-index:3 !important; background:#FFFFFF !important; color:var(--fg-faint) !important; font-family:var(--font-mono) !important; font-size:9.5px !important; letter-spacing:.1em !important; text-transform:uppercase !important; font-weight:500 !important; text-align:left !important; padding:9px 12px 8px !important; border-bottom:1px solid var(--line) !important; white-space:nowrap !important; }
/* rows: hairline sep, tight, calm hover */
#detail table.sample tbody tr{ border-bottom:1px solid var(--hairline) !important; }
#detail table.sample tbody tr:hover{ background:var(--panel-2) !important; }
#detail table.sample td{ padding:8px 12px !important; border:0 !important; vertical-align:middle !important; font-size:12px !important; color:var(--fg-faint) !important; }
/* the headline / primary entity column dominates */
#detail table.sample td:first-child{ color:var(--fg) !important; font-weight:550 !important; font-size:12.5px !important; letter-spacing:-.005em !important; padding-left:16px !important; position:relative !important; }
#detail table.sample tbody tr:hover td:first-child{ color:var(--accent) !important; }
/* a quiet status rail on the leading edge of each row (uses the row's own signal dot if present) */
#detail table.sample tbody tr td:first-child::before{ content:""; position:absolute; left:6px; top:50%; transform:translateY(-50%); width:4px; height:4px; border-radius:50%; background:var(--line-bright); }
#detail table.sample tbody tr.sig-red td:first-child::before,#detail table.sample tbody tr:has(.sig-red) td:first-child::before{ background:var(--signal-red); }
#detail table.sample tbody tr.sig-amber td:first-child::before,#detail table.sample tbody tr:has(.sig-amber) td:first-child::before{ background:var(--signal-amber); }
#detail table.sample tbody tr.sig-green td:first-child::before,#detail table.sample tbody tr:has(.sig-green) td:first-child::before{ background:var(--signal-green); }
/* numeric / date-ish columns read as data */
#detail table.sample td:last-child{ font-family:var(--font-mono) !important; font-size:11px !important; color:var(--fg-faint) !important; white-space:nowrap !important; }
/* the feed toolbar above the table: quiet, hairline */
#detail .niy-col-feed .toolbar,#detail .toolbar{ border-bottom:0 !important; }
#detail .nx-head,#detail .feed-head{ color:var(--fg) !important; }
/* right split pane (AI / analytics) — clean canvas, no heavy border */
.niy-split .niy-col-work,.niy-split .niy-col-ai{ background:#FFFFFF !important; border-left:1px solid var(--line) !important; }

/* ===== V2 PASS 3 — Home as editorial "mission brief" (de-boxed, image-forward) ===== */
/* section labels: quiet caps + a single full-width hairline (no ticks/extenders) */
#niyHome .nh-h{ font-size:10.5px !important; letter-spacing:.15em !important; color:var(--fg-faint) !important; font-weight:600 !important; text-transform:uppercase !important; padding:0 0 10px !important; border-bottom:1px solid var(--line) !important; margin:0 0 16px !important; display:block !important; }
#niyHome .nh-h::before,#niyHome .nh-h::after{ display:none !important; content:none !important; }
#niyHome .nh-h small{ color:var(--fg-faint) !important; font-weight:400 !important; letter-spacing:.02em !important; text-transform:none !important; margin-left:8px; }
/* N-ZINE cards: image-forward, no box, ink headline, muted dek */
#niyHome .nh-card{ border:0 !important; border-radius:8px !important; background:transparent !important; box-shadow:none !important; overflow:hidden !important; }
#niyHome .nh-card img{ border-radius:6px !important; }
#niyHome .nh-card:hover{ transform:translateY(-2px) !important; box-shadow:none !important; border:0 !important; }
#niyHome .nh-card h3{ color:var(--fg) !important; font-weight:600 !important; letter-spacing:-.01em !important; font-size:15px !important; line-height:1.3 !important; }
#niyHome .nh-card:hover h3{ color:var(--accent) !important; }
#niyHome .nh-card:hover img{ transform:scale(1.03) !important; }
#niyHome .nh-tag,#niyHome .nh-card .m,#niyHome .nh-card .meta{ color:var(--fg-faint) !important; }
#niyHome .nh-tag.inv{ color:var(--accent) !important; }
/* hero: editorial headline */
.nh-slide h2{ color:var(--fg) !important; font-weight:700 !important; letter-spacing:-.02em !important; }
.nh-slide h2:hover{ color:var(--accent) !important; }
#nhHero{ border:1px solid var(--line) !important; border-radius:10px !important; }
/* ads: framed quietly */
#nhAds{ border:1px solid var(--line) !important; }
/* rail: de-boxed columns, defined by header rule + whitespace */
#niyHome .nh-box{ border:0 !important; background:transparent !important; padding:0 !important; }
#niyHome .nh-box .bh{ font-size:10.5px !important; letter-spacing:.14em !important; color:var(--fg-faint) !important; font-weight:600 !important; border-bottom:1px solid var(--line) !important; padding:0 0 9px !important; margin:0 0 12px !important; }
#niyHome .nh-box .bh.g,#niyHome .nh-box .bh small{ color:var(--fg-faint) !important; }
/* LATEST: dense editorial list */
#nhLatest ul{ margin:0 !important; }
#nhLatest li{ border-bottom:1px solid var(--hairline) !important; padding:9px 0 !important; border-radius:0 !important; margin:0 !important; }
#nhLatest li:hover{ background:transparent !important; }
#nhLatest li a{ color:var(--fg) !important; font-weight:500 !important; }
#nhLatest li:hover a{ color:var(--accent) !important; }
#nhLatest .s,#nhLatest .t,#nhLatest .ago{ color:var(--fg-faint) !important; font-family:var(--font-mono) !important; font-size:10px !important; letter-spacing:.03em !important; }
/* KEY MOVES + PULSE: mono, aligned, quiet */
#nhMoves td{ font-family:var(--font-mono) !important; font-size:11.5px !important; border-bottom:1px solid var(--hairline) !important; color:var(--fg) !important; }
#nhMoves .px{ color:var(--fg) !important; }
#nhPulse a{ color:var(--fg) !important; }#nhPulse a:hover{ color:var(--accent) !important; }
#nhPulse .pt{ color:var(--fg-faint) !important; font-family:var(--font-mono) !important; }
/* IN FOCUS chips + DESK shortcuts: editorial */
#nhFocus button{ border-color:var(--line) !important; color:var(--fg-dim) !important; background:transparent !important; }
#nhFocus button:hover{ border-color:var(--accent) !important; color:var(--accent) !important; }
.nh-desk{ background:var(--panel-2) !important; border:1px solid var(--line) !important; }
.nh-desk:hover{ border-color:var(--accent) !important; transform:translateY(-1px) !important; }
.nh-desk b{ color:var(--accent) !important; }
.nh-desk span{ color:var(--fg-dim) !important; }
/* agent provenance badge stays quiet */
.nh-agent{ color:var(--fg-faint) !important; }
/* N-ZINE full-page reader: editorial article */
#nzPage h1{ color:var(--fg) !important; font-weight:700 !important; letter-spacing:-.025em !important; }
#nzPage .body,#nzPage p{ color:var(--fg-dim) !important; }

/* ===== V2 PASS 4 — sidebar: clean editorial collapse-to-rail ===== */
.niy-sb-panel{ background:#FFFFFF !important; border-right:1px solid var(--line) !important; }
#sidebar:hover .niy-sb-panel,#sidebar:focus-within .niy-sb-panel{ box-shadow:14px 0 40px rgba(20,24,28,.10) !important; }
/* collapsed monogram codes = the rail's "icons": mono, quiet, active=accent */
#sidebar:not(:hover):not(:focus-within) .feat-item::after{ color:var(--fg-faint) !important; font-family:var(--font-mono) !important; font-weight:600 !important; font-size:10.5px !important; letter-spacing:.05em !important; }
#sidebar:not(:hover):not(:focus-within) .feat-item.active::after{ color:var(--accent) !important; }
/* rows: quiet default, ink+accent-tick when active */
#sidebar .feat-item .label{ color:var(--fg-dim) !important; font-weight:500 !important; letter-spacing:-.005em !important; }
#sidebar .feat-item:hover{ background:var(--panel-2) !important; }
#sidebar .feat-item:hover .label{ color:var(--fg) !important; }
#sidebar .feat-item.active{ background:var(--sel) !important; }
#sidebar .feat-item.active .label{ color:var(--fg) !important; font-weight:600 !important; }
#sidebar .feat-item.active::before{ background:var(--accent) !important; box-shadow:none !important; }
#sidebar .fi-meta.fi-live{ color:var(--niy-live) !important; font-family:var(--font-mono) !important; font-size:8.5px !important; letter-spacing:.08em !important; }
/* status dots (expanded) muted unless meaningful */
#sidebar .feat-item .dot{ opacity:.9 !important; }
#sidebar .feat-item .dot.dot-red{ background:var(--signal-red) !important; }
#sidebar .feat-item .dot.dot-amber{ background:var(--signal-amber) !important; }
#sidebar .feat-item .dot.dot-green{ background:var(--signal-green) !important; }
/* group labels: quiet mono caps + hairline */
#sidebar .sidebar-group-label{ color:var(--fg-faint) !important; font-family:var(--font-mono) !important; font-size:9px !important; letter-spacing:.13em !important; text-transform:uppercase !important; font-weight:500 !important; }
#sidebar .sidebar-group-label::after{ background:var(--hairline) !important; opacity:1 !important; }
/* the filter/search inside the expanded rail: editorial */
#sidebar .sidebar-filter input,#sidebar .filter-input{ background:var(--panel-2) !important; border:1px solid var(--line) !important; color:var(--fg) !important; border-radius:8px !important; }
/* rail toggle / account block quiet */
#sidebar .niy-sb-toggle,#sidebar .niy-acc-name{ color:var(--fg-dim) !important; }
#sidebar .niy-acc-meta{ color:var(--fg-faint) !important; }

/* ===== V2 PASS 5 — European cool shades + declutter ===== */
html:root, html:root[data-theme="light"], html:root[data-theme="dark"]{
  --bg:#FCFCFD; --panel:#EFF1F4; --panel-2:#F6F7F9; --panel-3:#FFFFFF;
  --line:#E3E7EC; --line-bright:#D3D9E0; --hairline:#ECEFF2;
  --fg:#16191D; --fg-dim:#4E555D; --fg-faint:#949BA3; --white:#0A0C0E;
  --accent:#E9572A; --accent-2:#FF6A3D; --ds-accent:#E9572A;
  --sel:rgba(233,87,42,.07); --sel-line:rgba(233,87,42,.5);
  --signal-red:#D23B2E; --signal-amber:#DD9A2C; --signal-green:#2C9E58;
}
body,.terminal,.main{ background:#FCFCFD !important; }
/* remove workspace-org clutter from the scope bar; space reflows */
#newFolderBtn,#geoEmbedBtn,#categoryBtn{ display:none !important; }
/* cool, refined chrome accents */
.cmdbar:focus-within{ box-shadow:0 0 0 3px var(--sel) !important; border-color:var(--accent) !important; }

/* ===== V2 PASS 6 — mockup match: uppercase tabs, LIVE TV, COMPANY out of topbar ===== */
.tab .tab-label{ text-transform:uppercase !important; letter-spacing:.055em !important; font-size:12px !important; }
#niyCoBtn{ display:none !important; }   /* COMPANY removed from top panel -> relocated to Finance/Home (next) */

/* ===== V2 PASS 7 — light every overlay + Stripe-grade craftsmanship ===== */
/* every floating surface: white, hairline, soft layered shadow, consistent radius */
.ticker-filter-pop,.niy-tools-pop,.niy-more-menu,.niy-smart-card,.scope-popover,.niy-menu,
.context-menu,#searchSuggest,.niy-sugg,.niy-acc-menu,.niy-tools-pop,[id$="Popover"],[class*="-popover"]{
  background:#FFFFFF !important; color:var(--fg) !important;
  border:1px solid var(--line) !important; border-radius:12px !important;
  box-shadow:0 1px 2px rgba(16,24,40,.05), 0 12px 34px rgba(16,24,40,.13) !important;
  backdrop-filter:none !important;
}
.ticker-filter-pop *,.niy-tools-pop *,.niy-more-menu *,.scope-popover *{ color:var(--fg-dim) !important; }
.ticker-filter-pop label,.ticker-filter-pop .h,.niy-tools-pop b,.scope-popover label,.niy-menu b{ color:var(--fg-faint) !important; font-family:var(--font-mono) !important; font-size:9.5px !important; letter-spacing:.11em !important; text-transform:uppercase !important; }
/* segmented toggles (Normal/Slow/Hide) → Stripe pill segments */
.ticker-filter-pop button,.niy-tools-pop button,.niy-more-menu button,.scope-popover button{
  background:var(--panel-2) !important; border:1px solid var(--line) !important; color:var(--fg-dim) !important; border-radius:8px !important; font-weight:500 !important;
}
.ticker-filter-pop button.active,.ticker-filter-pop button[aria-pressed="true"],.niy-more-menu button.active{
  background:var(--sel) !important; border-color:var(--sel-line) !important; color:var(--accent) !important;
}
.ticker-filter-pop button:hover,.niy-tools-pop button:hover,.niy-more-menu button:hover{ border-color:var(--line-bright) !important; color:var(--fg) !important; }
.ticker-filter-pop input[type="checkbox"],.niy-tools-pop input[type="checkbox"]{ accent-color:var(--accent) !important; }
/* modal scrims → light, blurred (Stripe) */
.modal-overlay,.niy-co-modal,#niyCoModal,.cs-cm-ov,[class*="-ov"]{ background:rgba(18,22,26,.32) !important; backdrop-filter:blur(3px) !important; }
.niy-co-card,.cs-cm,.niy-modal-card{ background:#FFFFFF !important; border:1px solid var(--line) !important; border-radius:14px !important; box-shadow:0 8px 40px rgba(16,24,40,.18) !important; color:var(--fg) !important; }
/* ===== soft elevation over hard borders (Stripe) ===== */
.niy-box,.nh-box,.nh-card,.niy-kpi,.geo-kpi,.qa-card,.stat,.pig-metric,.pig-sec-card,#nhHero,#nhAds,.niy-acc{
  border:1px solid var(--hairline) !important; box-shadow:0 1px 2px rgba(16,24,40,.04) !important; border-radius:12px !important;
}
.nh-card,#niyHome .nh-box{ border:0 !important; box-shadow:none !important; }
.nh-card:hover,.pig-sec-card:hover,.dataset-card:hover{ box-shadow:0 2px 4px rgba(16,24,40,.05),0 16px 36px rgba(16,24,40,.10) !important; }
/* KEY INDICATOR tiles → Stripe stat tiles */
.niy-kpi-k,.geo-kpi-k,.qa-k{ color:var(--fg-faint) !important; font-family:var(--font-mono) !important; font-size:9.5px !important; letter-spacing:.1em !important; text-transform:uppercase !important; font-weight:500 !important; }
.niy-kpi-v,.geo-kpi-v{ font-weight:650 !important; letter-spacing:-.02em !important; }
/* buttons: Stripe refinement */
button,.btn{ transition:background .15s cubic-bezier(.22,.61,.36,1),box-shadow .15s,border-color .15s,color .15s !important; }
.toolbar-btn,.scope-action-btn,.topbar-btn{ border-radius:8px !important; }
/* segmented lang / scope toggles refined */
