/* ==================================================================
   V2 PASS 22 — CRAFT REFINEMENT (no layout change, visual only)
   Enterprise token system: neutral 95%, accent reserved, hairline
   borders as separation, unified radius, disciplined type, calm motion.
   ================================================================== */
html:root,html:root[data-theme="light"],html:root[data-theme="dark"]{
  /* ---- neutral ramp (the 95%) ---- */
  --n0:#FFFFFF; --n25:#FCFCFD; --n50:#F7F8FA; --n100:#F1F3F5; --n150:#E9ECEF;
  --n200:#E1E4E8; --n300:#CDD2D8; --n400:#A9B0B8; --n500:#7C848D; --n600:#5B636C;
  --n700:#3E454D; --n800:#272D34; --n900:#1A1F26;
  /* ---- semantic ---- */
  --bg:var(--n25); --panel:var(--n50); --panel-2:var(--n50); --panel-3:var(--n0);
  --line:rgba(18,24,32,.08); --hairline:rgba(18,24,32,.055); --line-bright:rgba(18,24,32,.13);
  --fg:var(--n900); --fg-dim:var(--n600); --fg-faint:var(--n500); --white:var(--n900);
  /* ---- accent: active nav · active tab · primary CTA · selection only ---- */
  --accent:#E0552A; --accent-press:#C7481F;
  --sel:rgba(224,85,42,.07); --sel-line:rgba(224,85,42,.35); --ds-accent:var(--accent);
  --ring:0 0 0 3px rgba(224,85,42,.14);
  /* ---- status: quiet, never decorative ---- */
  --ok:#127A47; --warn:#9A6314; --bad:#B4291D; --info:#1F5FA8;
  --signal-green:var(--ok); --signal-amber:var(--warn); --signal-red:var(--bad);
  /* ---- one radius system ---- */
  --r-xs:5px; --r-sm:7px; --r-md:9px; --r-lg:12px; --r-xl:15px; --r-pill:999px;
  /* ---- one elevation scale (soft, never heavy) ---- */
  --e1:0 1px 1px rgba(18,24,32,.04);
  --e2:0 1px 2px rgba(18,24,32,.05),0 1px 1px rgba(18,24,32,.03);
  --e3:0 4px 12px rgba(18,24,32,.07),0 1px 2px rgba(18,24,32,.05);
  --e4:0 12px 32px rgba(18,24,32,.11),0 2px 6px rgba(18,24,32,.05);
  /* ---- motion ---- */
  --ease:cubic-bezier(.2,.6,.35,1); --t1:.15s; --t2:.19s;
}

/* ---------- TYPOGRAPHY: disciplined hierarchy ---------- */
body{ color:var(--fg); font-size:13.5px; line-height:1.5; letter-spacing:-.003em; }
h1,.detail-title{ font-size:20px !important; font-weight:640 !important; line-height:1.25 !important; letter-spacing:-.019em !important; color:var(--n900) !important; }
h2{ font-size:17px !important; font-weight:620 !important; letter-spacing:-.015em !important; }
h3,.nh-card h3{ font-size:14.5px !important; font-weight:600 !important; letter-spacing:-.009em !important; line-height:1.35 !important; }
/* section eyebrows / column heads — the quietest layer */
th,.nh-h,.bh,.section-label,.pig-p-kicker,.niy-kpi-k,.geo-kpi-k,.pill-row-label,.niy-fly-h,.sidebar-group-label{
  font-size:10.5px !important; font-weight:600 !important; letter-spacing:.075em !important;
  text-transform:uppercase !important; color:var(--n500) !important; }
/* body + data */
td,.label,p,li{ font-size:13.5px !important; color:var(--n800) !important; }
.ago,.t,.s,.fi-meta,.uf-meta,.m,.meta{ font-size:11.5px !important; color:var(--n500) !important; letter-spacing:0 !important; }
/* numerals never wobble */
td,th,.niy-kpi-v,.pig-metric .v,#nhMoves td,#nhStrip .nh-q *{ font-variant-numeric:tabular-nums; }

/* ---------- BORDERS: the primary separator, almost invisible ---------- */
.niy-box,.nh-box,.nh-card,.niy-kpi,.geo-kpi,.qa-card,.stat,.pig-metric,.pig-sec-card,
.dataset-card,.niy-acc,.callout,.bill-panel,#nhHero,#nhAds,.niy-chart{
  border:1px solid var(--line) !important; border-radius:var(--r-lg) !important;
  background:var(--n0) !important; box-shadow:none !important; }
/* elevation ONLY for things that float above the page */
.niy-fly,.niy-acc-body,.ticker-filter-pop,.niy-tools-pop,.niy-more-menu,#searchSuggest,
.niy-co-card,.niy-modal-card,.niy-tier-rail:hover{
  border:1px solid var(--line) !important; border-radius:var(--r-lg) !important;
  box-shadow:var(--e4) !important; background:var(--n0) !important; }

/* ---------- BUTTONS: quiet, confident ---------- */
button,.btn,.toolbar-btn,.topbar-btn,.scope-action-btn,.nh-desk,#nhFocus button{
  font-size:12.5px !important; font-weight:530 !important; letter-spacing:-.002em !important;
  border-radius:var(--r-md) !important; transition:background var(--t1) var(--ease),
  color var(--t1) var(--ease),border-color var(--t1) var(--ease),box-shadow var(--t1) var(--ease) !important; }
.toolbar-btn,.topbar-btn,.scope-action-btn{
  color:var(--n600) !important; background:transparent !important; border:1px solid transparent !important;
  padding:7px 11px !important; }
.toolbar-btn:hover,.topbar-btn:hover,.scope-action-btn:hover{
  background:var(--n100) !important; color:var(--n800) !important; }
.toolbar-btn:active,.topbar-btn:active{ background:var(--n150) !important; }
/* primary CTA — the only filled accent */
.nh-cta,#niyHome .nh-cta,button.primary,.ask-ai-btn,#askAiBtn,[class*="ask-ai"]{
  background:var(--accent) !important; color:#fff !important; border:1px solid transparent !important;
  border-radius:var(--r-md) !important; font-weight:560 !important; padding:8px 14px !important;
  box-shadow:var(--e1) !important; }
.nh-cta:hover,button.primary:hover,[class*="ask-ai"]:hover{ background:var(--accent-press) !important; box-shadow:var(--e2) !important; }
.nh-cta:active,button.primary:active{ transform:translateY(.5px); }
/* secondary chips */
.nh-desk,#nhFocus button{ background:var(--n0) !important; border:1px solid var(--line) !important; color:var(--n600) !important; }
.nh-desk:hover,#nhFocus button:hover{ border-color:var(--line-bright) !important; background:var(--n50) !important; color:var(--n800) !important; transform:none !important; }

/* ---------- INPUTS: effortless ---------- */
input,select,textarea,#rowFilter,.filter-input,.column-filter-select{
  font-size:13px !important; color:var(--n900) !important;
  background:var(--n0) !important; border:1px solid var(--line) !important;
  border-radius:var(--r-md) !important; height:34px !important; padding:0 12px !important;
