  stroke:var(--accent) !important; stroke-width:1.7 !important; }

/* ---------- NAVIGATION: quiet, disappears into the interface ---------- */
.niy-tier,.feat-item,.sidebar-group-label{ transition:background var(--t1) var(--ease),color var(--t1) var(--ease) !important; }
.niy-tier{ border-radius:var(--r-md) !important; }
