  padding:64px 40px; text-align:center; }
.niy-scope-empty svg{ width:34px; height:34px; fill:none; stroke:var(--n300); stroke-width:1.4; }
.niy-scope-empty h4{ font-size:14.5px !important; font-weight:600 !important; color:var(--n700) !important; margin:2px 0 0; }
.niy-scope-empty p{ font-size:12.5px !important; color:var(--n500) !important; max-width:430px; line-height:1.6; }
.niy-scope-empty .cta{ display:flex; gap:8px; margin-top:6px; }
.niy-scope-empty button{ height:32px; padding:0 14px; border-radius:var(--r-md); border:1px solid var(--line);
  background:var(--n0); font-size:12px; font-weight:540; color:var(--n700); cursor:pointer; }
.niy-scope-empty button.pri{ background:var(--accent); border-color:transparent; color:#fff; }
#niyScopeBar.loading .sc-stats{ opacity:.4; }
#detail .niy-fade{ animation:niyScFade .22s var(--ease); }
@keyframes niyScFade{ from{ opacity:0; transform:translateY(4px); } to{ opacity:1; transform:none; } }

/* ===== V2 PASS 49 — row card, restored to first-class (analysis, keywords, fields) ===== */
html body .niy-rd-panel-row td{ text-decoration:none !important; }
html body .niy-rd-panel{ background:var(--n25) !important; border:1px solid var(--line) !important;
  border-radius:var(--r-lg) !important; margin:4px 6px 12px !important; padding:16px 20px 18px !important;
  box-shadow:var(--e2) !important; animation:niyCardIn .22s var(--ease); }
@keyframes niyCardIn{ from{ opacity:0; transform:translateY(-5px); } to{ opacity:1; transform:none; } }
html body .niy-rd-panel-head{ display:flex; align-items:flex-start; gap:12px; }
html body .niy-rd-panel-title{ font-size:17px !important; font-weight:640 !important;
  letter-spacing:-.014em !important; color:var(--n900) !important; }
html body .niy-rd-close{ margin-left:auto !important; width:30px !important; height:30px !important;
  border:1px solid var(--line) !important; background:var(--n0) !important; border-radius:var(--r-md) !important;
  color:var(--n600) !important; font-size:15px !important; cursor:pointer !important;
  display:grid !important; place-items:center !important; flex:0 0 30px;
  transition:background var(--t1) var(--ease), color var(--t1) var(--ease) !important; }
html body .niy-rd-close:hover{ background:var(--n100) !important; color:var(--n900) !important; }



/* ===== V2PASS62B — the pass-59 tap-to-pin class opens the flyout (its CSS died with pass 60) ===== */
html body #sidebar .sidebar-group.niy-pinned > .niy-acc-body{ opacity:1 !important; visibility:visible !important;
  transform:translateX(0); pointer-events:auto !important; }
/* V2PASS62C — rows inside a pinned flyout: beat the at-rest display:none twin */
html body #sidebar .sidebar-group.niy-pinned .feat-item{ display:flex !important; }
html body #sidebar .sidebar-group.niy-pinned .feat-item .label{ display:inline !important; opacity:1 !important; }
html body #sidebar .sidebar-group.niy-pinned .niy-ficon{ display:inline-grid !important; }

/* ===== V2 PASS 63 — Security desk live sections (token-styled, icon-free) ===== */
.niy-live-sec{ margin:22px 4px 8px; }
.nls-head{ display:flex; align-items:baseline; justify-content:space-between; gap:10px; margin-bottom:6px; }
.nls-title{ font-size:10px; font-weight:600; letter-spacing:.09em; text-transform:uppercase; color:var(--n500,#7C848D); }
.nls-status{ font-size:9px; letter-spacing:.06em; color:var(--n400,#A9B0B8); text-transform:uppercase; white-space:nowrap; }
.nls-body table{ width:100%; border-collapse:collapse; }
.nls-body th{ text-align:left; font-size:9.5px; letter-spacing:.07em; text-transform:uppercase;
  color:var(--n500,#7C848D); font-weight:600; padding:5px 8px; border-bottom:1px solid var(--line,#E1E4E8); }
.nls-body td{ font-size:12px; color:var(--n700,#3E454D); padding:6px 8px;
  border-bottom:1px solid var(--line,#E1E4E8); vertical-align:top; line-height:1.4; }
.nls-body tr:hover td{ background:var(--n50,#F7F8F9); }
.nls-body a{ color:inherit; text-decoration:none; }
.nls-body a:hover{ text-decoration:underline; }
.nls-chips{ display:flex; flex-wrap:wrap; gap:6px; margin:2px 0 8px; }
.nls-chip{ border:1px solid var(--line,#E1E4E8); background:transparent; border-radius:999px;
  padding:3px 10px; font-size:10.5px; color:var(--n600,#5B636C); cursor:pointer; transition:border-color .12s,color .12s; }
.nls-chip.on{ border-color:var(--accent,#E0552A); color:var(--accent,#E0552A); }
.nls-note{ font-size:11px; color:var(--n500,#7C848D); padding:8px 2px; }
.nls-num{ font-variant-numeric:tabular-nums; }

/* ===== V2 PASS 66 — remove AI / LIVE / BETA chips beside function names ===== */
.beta-badge{ display:none !important; }
.fi-meta{ display:none !important; }

/* ===== V2 PASS 70 — analytics chart blocks (token-themed SVG) ===== */
.niy-viz-block{ padding:6px 2px 14px; }
.nvz-title{ font-size:10px; font-weight:600; letter-spacing:.09em; text-transform:uppercase; color:var(--n500,#7C848D); margin:8px 0 6px; }
.nvz-sub{ font-size:9px; letter-spacing:.05em; color:var(--n400,#A9B0B8); text-transform:uppercase; margin:-4px 0 8px; }
.niy-viz-block svg{ width:100%; height:auto; display:block; }
.niy-viz-block svg text{ fill:var(--n500,#7C848D); font-size:9.5px; font-family:var(--font-mono,monospace); }
.nvz-axis{ stroke:var(--line,#E1E4E8); stroke-width:1; }
.nvz-line{ stroke:var(--accent,#E0552A); stroke-width:1.8; fill:none; }
.nvz-area{ fill:var(--accent,#E0552A); opacity:.08; }
.nvz-bar{ fill:var(--accent,#E0552A); opacity:.85; }
.nvz-bar2{ fill:var(--n400,#A9B0B8); opacity:.55; }

/* ===== V2 PASS 73 — Goa report components (state/local) ===== */
.ngv-stats{ display:flex; flex-wrap:wrap; gap:10px; margin:4px 0 10px; }
.ngv-stat{ flex:1 1 150px; min-width:140px; border:1px solid var(--line,#E1E4E8); border-radius:10px; padding:10px 12px; }
.ngv-stat .v{ font-size:19px; font-weight:700; color:var(--n900,#1A1F26); font-variant-numeric:tabular-nums; line-height:1.15; }
.ngv-stat .k{ font-size:9.5px; font-weight:600; letter-spacing:.08em; text-transform:uppercase; color:var(--n500,#7C848D); margin-top:3px; }
.ngv-stat .s{ font-size:10.5px; color:var(--n500,#7C848D); margin-top:2px; }
.ngv-strip{ display:flex; height:26px; border-radius:6px; overflow:hidden; margin:6px 0 6px; }
.ngv-strip span{ display:block; height:100%; }
.ngv-leg{ display:flex; flex-wrap:wrap; gap:10px 16px; margin:2px 0 10px; }
.ngv-leg .lg{ display:inline-flex; align-items:center; gap:6px; font-size:10.5px; color:var(--n600,#5B636C); }
.ngv-leg .sw{ width:9px; height:9px; border-radius:2px; flex:none; }
.ngv-grid{ display:grid; grid-template-columns:minmax(120px,1.3fr) repeat(4,minmax(44px,1fr)) 56px; gap:3px 6px; align-items:center; margin:6px 0 8px; }
.ngv-grid .hd{ font-size:9px; font-weight:600; letter-spacing:.07em; text-transform:uppercase; color:var(--n500,#7C848D); }
.ngv-grid .nm{ font-size:11.5px; color:var(--n700,#3E454D); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.ngv-grid .cell{ height:17px; border-radius:3px; color:#fff; font-size:8.5px; font-weight:700; letter-spacing:.03em;
  display:flex; align-items:center; justify-content:center; }
.ngv-grid .mg{ font-size:10.5px; color:var(--n500,#7C848D); text-align:right; font-variant-numeric:tabular-nums; }
.ngv-cbars{ margin:4px 0 8px; }
.ngv-cbar{ display:flex; align-items:center; gap:8px; margin:3px 0; }
.ngv-cbar .l{ flex:0 0 148px; font-size:11px; color:var(--n700,#3E454D); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.ngv-cbar .t{ flex:1 1 auto; height:13px; border-radius:3px; background:var(--n100,#F1F3F5); position:relative; overflow:hidden; }
.ngv-cbar .f{ position:absolute; left:0; top:0; bottom:0; border-radius:3px; }
.ngv-cbar .v{ flex:0 0 64px; font-size:10.5px; color:var(--n600,#5B636C); font-variant-numeric:tabular-nums; text-align:right; }

/* ===== V2 PASS 75 — Goa choropleths ===== */
.ngv-maps{ display:flex; flex-wrap:wrap; gap:18px 26px; margin:8px 0 12px; }
.ngv-map{ flex:0 1 172px; min-width:150px; }
.ngv-mapsvg{ width:100%; height:auto; display:block; }
.ngv-mapsvg .ngv-ac{ stroke:var(--n0,#fff); stroke-width:.7; transition:opacity .12s; cursor:default; }
.ngv-mapsvg .ngv-ac:hover{ opacity:.78; stroke:var(--n900,#1A1F26); stroke-width:1; }
.ngv-mapcap{ font-size:10px; letter-spacing:.06em; text-transform:uppercase; color:var(--n500,#7C848D); margin-top:5px; text-align:center; }

/* ===== V2PASS76 — editorial polish for the Goa components ===== */
.ngv-stats{ gap:0 34px; margin:6px 0 14px; }
.ngv-stat{ flex:0 1 auto; min-width:132px; border:0; border-radius:0; padding:8px 0 2px;
  border-top:2px solid var(--n900,#1A1F26); }
.ngv-stat .v{ font-size:23px; letter-spacing:-.01em; }
.ngv-stat .k{ margin-top:4px; }
.nls-body td.nls-num{ text-align:right; }
.nls-body th:not(:first-child):not([data-l]){ }
.ngv-cbar .t{ height:10px; }
.ngv-cbar .l{ flex-basis:170px; }
.ngv-strip{ height:22px; border-radius:4px; }
.ngv-grid .cell{ height:19px; border-radius:2px; }
.ngv-dossier{ margin:2px 0 14px; }
.ngv-dossier .dn{ font-size:20px; font-weight:700; color:var(--n900,#1A1F26); letter-spacing:-.01em; }
.ngv-dossier .dm{ font-size:11px; letter-spacing:.07em; text-transform:uppercase; color:var(--n500,#7C848D); margin-top:2px; }
.ngv-dossier .dw{ font-size:13px; color:var(--n700,#3E454D); margin-top:7px; }
.ngv-dossier .pty{ display:inline-block; padding:1px 7px; border-radius:3px; font-size:10px; font-weight:700; color:#fff; margin-right:6px; }
.ngv-dossier .bandchip{ display:inline-block; padding:1px 8px; border-radius:999px; font-size:9.5px; font-weight:700;
  letter-spacing:.07em; text-transform:uppercase; color:#fff; margin-left:8px; vertical-align:2px; }

/* ===== V2 PASS 79 — usable tables + analytics maps ===== */
html body #detail .niy-col-feed .niy-feedwrap{ min-height:460px; }
html body #detail .niy-col-feed .niy-feedwrap > table.sample{ width:100%; }
.niy-live-sec{ margin-top:26px; padding-top:4px; border-top:1px solid var(--line,#E1E4E8); }
.niy-live-sec:first-of-type{ border-top:0; }
.ngv-mapwrap{ margin:2px 0 10px; }
.niy-viz-block .ngv-maps{ gap:14px 18px; }
.niy-viz-block .ngv-map{ flex:0 1 132px; min-width:118px; }
/* live rows are grabbable wherever they appear */
html body #detail .niy-col-feed tbody tr[data-niy-drag]{ cursor:grab; }


