/*V2PASS96 the split-brain mark*/
.brand img{ object-fit:contain; }
.niy-rail-logo img{ height:28px; width:28px; object-fit:contain; }
.niy-login-mark{ display:block; width:54px; height:54px; object-fit:contain; margin:0 auto 12px; }
/* the mark is drawn in ink on transparency \u2014 invert it when the shell goes dark */
:root[data-theme="dark"] .brand img,
:root[data-theme="dark"] .niy-rail-logo img,
:root[data-theme="dark"] .niy-st-top .st-logo img,
:root[data-theme="dark"] .niy-login-mark{ filter:invert(1); }


/*V2PASS98 analysis sections inside the analytics pane*/
.niy-pane-analytics [data-niy-moved]{ margin:0 0 18px; }
.niy-pane-analytics [data-niy-moved] table{ width:100%; }
.niy-pane-analytics [data-niy-moved] td,
.niy-pane-analytics [data-niy-moved] th{ padding:7px 9px; font-size:11.5px; }
.niy-pane-analytics [data-niy-moved] .ngv-grid{ grid-template-columns:minmax(74px,1.2fr) repeat(4,minmax(30px,1fr)) 42px; gap:2px 4px; }
.niy-pane-analytics [data-niy-moved] .ngv-grid .nm{ font-size:10.5px; }
.niy-pane-analytics [data-niy-moved] .nls-note{ font-size:11px; }
/* the analyst box is gone from the feed \u2014 make sure it cannot flash in */
#detail .niy-col-feed .niy-analyst{ display:none !important; }


body{font-family:system-ui,sans-serif;margin:0;background:#f4f4f2;color:#1a1a1a}header{background:#fff;padding:14px 18px;display:flex;align-items:center;gap:12px;border-bottom:2px solid ' + S.themeColor + '}header img{width:44px;height:44px;border-radius:9px}h1{font-size:19px;margin:0}main{max-width:900px;margin:0 auto;padding:16px}article{background:#fff;border:1px solid #e5e5e0;border-radius:12px;padding:16px 18px;margin-bottom:14px}article img{max-width:100%;border-radius:9px}.m{font-size:11px;color:#999}.live{margin:0 0 14px;border-radius:12px;overflow:hidden}iframe{width:100%;aspect-ratio:16/9;border:0}footer{text-align:center;color:#999;font-size:11px;padding:22px}

/* Density pass: Bloomberg-grade data rows — trim loose cell padding so more rows show per screen (reversible; rich cells keep their own height). */#detail table tbody td{padding-top:6px!important;padding-bottom:6px!important}#detail table thead th{padding-top:6px!important;padding-bottom:6px!important}


/* Open Fronts · compact selected-event intelligence view */
body.niy-ofx-open #detail{min-height:calc(100dvh - 64px)!important}
body.niy-ofx-open #detail .niy-split{height:calc(100dvh - 72px)!important;min-height:680px!important;max-height:none!important;align-items:stretch!important;overflow:hidden!important}
body.niy-ofx-open #detail .niy-col-feed{display:flex!important;flex-basis:61%!important;height:100%!important;min-height:0!important;min-width:0!important}
body.niy-ofx-open #detail .niy-col-work{height:100%!important;min-height:0!important;display:flex!important;flex-basis:39%!important;min-width:400px;overflow:hidden!important}
body.niy-ofx-open #detail .niy-col-feed>.niy-col-body{display:flex!important;flex:1 1 0!important;height:0!important;min-height:0!important;overflow:auto!important}
body.niy-ofx-open #detail .niy-split.only-work .niy-col-feed,
body.niy-ofx-open #detail .niy-split.only-feed .niy-col-feed{display:flex!important;flex-basis:61%!important;min-width:0!important}
body.niy-ofx-open #detail .niy-split.only-work .niy-col-work,
body.niy-ofx-open #detail .niy-split.only-feed .niy-col-work{display:flex!important;flex-basis:39%!important;min-width:400px!important}
body.niy-ofx-open #detail .niy-split.only-work .niy-divider,
body.niy-ofx-open #detail .niy-split.only-feed .niy-divider{display:block!important}
body.niy-ofx-open #detail .niy-col-toggle[data-max]{display:none!important}
body.niy-ofx-open #detail .niy-work-head{padding:10px 16px 3px!important}
body.niy-ofx-open #detail .niy-work-modes{gap:20px!important}
body.niy-ofx-open #detail .niy-work-modes .niy-mode{font-size:9.5px!important;letter-spacing:.11em!important}
body.niy-ofx-open #detail .niy-work-body{display:flex!important;flex:1 1 0!important;height:0!important;min-height:0!important;overflow:hidden!important}
body.niy-ofx-open #detail .niy-pane-analytics{height:100%!important;padding:0 14px 22px;scrollbar-width:thin;overflow:auto!important;overflow-x:hidden!important}
body.niy-ofx-open #detail .niy-pane-analytics[hidden],body.niy-ofx-open #detail .niy-pane-ai[hidden]{display:none!important}
body.niy-ofx-open #detail .niy-pane-ai:not([hidden]){position:relative;display:flex!important;flex:1 1 auto!important;height:100%!important;min-height:0!important;flex-direction:column!important;padding:10px 3px 0!important;overflow:hidden!important;background:#fff!important}
body.niy-ofx-open #detail .niy-pane-ai .niy-ai-context{display:none!important}
body.niy-ofx-open #detail .niy-pane-ai .niy-ai-log{display:flex!important;flex:1 1 auto!important;min-height:0!important;overflow:auto!important;padding:24px 8px 16px!important}
body.niy-ofx-open #detail .niy-pane-ai .niy-ai-empty{width:100%;max-width:420px;margin:auto;text-align:center}
body.niy-ofx-open #detail .niy-pane-ai .niy-ai-empty-d{display:none!important}
body.niy-ofx-open #detail .niy-pane-ai .niy-ai-input-row{position:static!important;display:flex!important;flex:0 0 auto!important;width:100%!important;margin:0!important;padding:14px 0 18px!important;background:#fff!important;border-top:1px solid var(--line-bright,#c7cdd4)!important}
body.niy-ofx-open #detail tr.niy-rd-open>td{box-shadow:inset 3px 0 0 var(--accent,#e64b2a)!important}
body.niy-ofx-open #detail .niy-rd-panel{padding:14px 18px 20px}
body.niy-ofx-open #detail .niy-rd-panel-title{font-size:15px;letter-spacing:-.015em}
body.niy-ofx-open #detail .rd-ai{border-radius:2px!important;border-color:rgba(49,105,189,.25)!important;background:rgba(49,105,189,.055)!important}
body.niy-ofx-open #detail .row-detail-field{grid-template-columns:190px minmax(0,1fr);padding:7px 0}
body.niy-ofx-open #detail .rdf-key{font:600 9.5px var(--font-mono,ui-monospace,monospace);letter-spacing:.08em;color:var(--fg-faint,#77818c)}
body.niy-ofx-open #detail .rdf-val{font-size:12px;line-height:1.45;font-variant-numeric:tabular-nums}

.ofx-ai-banner{margin:7px 14px 0;border:1px solid var(--line,#dfe3e8);border-left:3px solid var(--accent,#e64b2a);background:var(--panel,#fff);padding:9px 10px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:5px 10px;align-items:center}
.ofx-ai-eyebrow{font:700 8.5px var(--font-mono,ui-monospace,monospace);letter-spacing:.13em;color:var(--accent,#e64b2a);text-transform:uppercase}
.ofx-ai-title{font-size:12px;font-weight:720;color:var(--fg,#111820);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ofx-ai-meta{font:500 9px var(--font-mono,ui-monospace,monospace);letter-spacing:.045em;color:var(--fg-faint,#68727e);grid-column:1/2}
.ofx-ai-side{grid-column:2;grid-row:1/4;display:flex;flex-direction:column;align-items:flex-end;gap:5px}
.ofx-ai-state{font:700 8px var(--font-mono,ui-monospace,monospace);letter-spacing:.1em;color:#24834f;text-transform:uppercase}
.ofx-ai-reattach{border:0;background:transparent;padding:0;color:var(--fg-faint,#68727e);font:600 8.5px var(--font-mono,ui-monospace,monospace);text-transform:uppercase;letter-spacing:.08em;cursor:pointer}
.ofx-ai-reattach:hover{color:var(--accent,#e64b2a)}

.ofx{--of-ink:var(--fg,#141a21);--of-dim:var(--fg-dim,#66717d);--of-faint:var(--fg-faint,#8c959f);--of-line:var(--line,#dfe3e8);--of-line2:var(--line-bright,#c7cdd4);--of-panel:var(--panel,#fff);--of-wash:var(--panel-2,#f6f7f8);--of-accent:var(--accent,#e64b2a);--of-red:#b7352f;--of-amber:#a66f19;--of-green:#317a4e;color:var(--of-ink);font-variant-numeric:tabular-nums;width:100%;min-width:0}
.ofx *{box-sizing:border-box;min-width:0}
.ofx-top{position:sticky;top:0;z-index:5;background:var(--of-panel);border-bottom:1px solid var(--of-line);padding:10px 0 0;margin-bottom:15px}
.ofx-command{display:flex;align-items:center;gap:8px;min-width:0}
.ofx-riskdot{width:6px;height:6px;background:var(--of-red);flex:0 0 auto}
.ofx-title{font-size:14px;font-weight:780;letter-spacing:-.015em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ofx-status{margin-left:auto;border:1px solid var(--of-line2);padding:2px 6px;font:700 8px var(--font-mono,ui-monospace,monospace);letter-spacing:.09em;text-transform:uppercase;color:var(--of-dim)}
.ofx-sub{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:5px;font:550 8px var(--font-mono,ui-monospace,monospace);letter-spacing:.065em;color:var(--of-faint);text-transform:uppercase}
.ofx-model{margin-left:auto;color:var(--of-amber);cursor:help}
.ofx-nav{display:flex;align-items:center;gap:16px;overflow-x:auto;margin-top:10px;scrollbar-width:none}
.ofx-nav::-webkit-scrollbar{display:none}
.ofx-nav button,.ofx-period button{white-space:nowrap;border:0;background:transparent;color:var(--of-faint);font:650 8px var(--font-mono,ui-monospace,monospace);letter-spacing:.09em;text-transform:uppercase;cursor:pointer}
.ofx-nav button{padding:7px 0 6px;border-bottom:2px solid transparent}
.ofx-nav button:hover,.ofx-nav button.on{color:var(--of-ink);border-bottom-color:var(--of-accent)}
.ofx-period{display:flex;gap:2px;margin-left:auto}
.ofx-period button{padding:3px 5px}
.ofx-period button:hover,.ofx-period button.on{color:var(--of-ink);background:var(--of-wash)}
.ofx-section{margin:0 0 17px;scroll-margin-top:100px}
.ofx-sec-h{display:flex;align-items:center;gap:8px;border-bottom:1px solid var(--of-line2);padding-bottom:5px;margin-bottom:8px}
.ofx-sec-no{font:700 8px var(--font-mono,ui-monospace,monospace);color:var(--of-accent)}
.ofx-sec-title{font:760 9px var(--font-mono,ui-monospace,monospace);letter-spacing:.115em;text-transform:uppercase}
.ofx-sec-meta{margin-left:auto;font:550 7.5px var(--font-mono,ui-monospace,monospace);letter-spacing:.06em;color:var(--of-faint);text-transform:uppercase}
.ofx-card{border:1px solid var(--of-line);background:var(--of-panel);padding:11px 12px;min-width:0}
.ofx-card-title{display:flex;align-items:center;gap:6px;font:700 8.5px var(--font-mono,ui-monospace,monospace);letter-spacing:.085em;text-transform:uppercase;color:var(--of-dim);margin-bottom:9px}
.ofx-card-title i{display:block;width:2px;height:10px;background:var(--of-accent)}
.ofx-grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.ofx-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--of-line);margin-bottom:8px}
.ofx-kpi{padding:9px 10px;border-right:1px solid var(--of-line);min-height:62px}
.ofx-kpi:last-child{border-right:0}
.ofx-kpi-l{font:650 7.5px var(--font-mono,ui-monospace,monospace);letter-spacing:.1em;text-transform:uppercase;color:var(--of-faint);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ofx-kpi-v{font:770 16px/1.15 var(--font-display,Arial,sans-serif);letter-spacing:-.025em;color:var(--of-ink);margin:5px 0 2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ofx-kpi-s{font:550 7.5px var(--font-mono,ui-monospace,monospace);line-height:1.3;color:var(--of-faint);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ofx-kpi-s.up{color:var(--of-red)}.ofx-kpi-s.good{color:var(--of-green)}
.ofx-deltas{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid var(--of-line);margin-top:8px}
.ofx-delta{padding:8px 8px 0;border-right:1px solid var(--of-line)}.ofx-delta:first-child{padding-left:0}.ofx-delta:last-child{border-right:0}
.ofx-delta span{display:block;font:650 7.5px var(--font-mono,ui-monospace,monospace);letter-spacing:.07em;text-transform:uppercase;color:var(--of-faint)}
.ofx-delta b{display:block;margin-top:3px;font:760 12px var(--font-display,Arial,sans-serif);color:var(--of-ink)}
.ofx-delta b.risk{color:var(--of-red)}
.ofx-spark{width:100%;height:82px;display:block;overflow:visible}
.ofx-spark .grid{stroke:var(--of-line);stroke-width:1}.ofx-spark .line{fill:none;stroke:var(--of-accent);stroke-width:1.8;vector-effect:non-scaling-stroke}.ofx-spark .area{fill:var(--of-accent);opacity:.07}.ofx-spark .dot{fill:var(--of-panel);stroke:var(--of-accent);stroke-width:1.5}
.ofx-axis{display:flex;justify-content:space-between;margin-top:3px;font:500 7.5px var(--font-mono,ui-monospace,monospace);color:var(--of-faint)}
.ofx-bullet{display:grid;grid-template-columns:minmax(92px,1fr) minmax(72px,1.25fr) 28px;gap:7px;align-items:center;margin:7px 0}
.ofx-bullet-l{font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ofx-bullet-track{height:5px;background:var(--of-wash);position:relative;overflow:hidden}
.ofx-bullet-fill{display:block;height:100%;background:var(--of-accent)}
.ofx-bullet-fill.red{background:var(--of-red)}.ofx-bullet-fill.amber{background:var(--of-amber)}.ofx-bullet-fill.green{background:var(--of-green)}
.ofx-bullet-v{text-align:right;font:650 8.5px var(--font-mono,ui-monospace,monospace);color:var(--of-dim)}
.ofx-statrow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-bottom:1px solid var(--of-line);padding-bottom:10px;margin-bottom:10px}
.ofx-stat{padding:0 9px;border-right:1px solid var(--of-line)}.ofx-stat:first-child{padding-left:0}.ofx-stat:last-child{border-right:0}
