.nww-feedbar p{margin:5px 0 0;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#66727f}
.nww-feed-meta{font-size:11px;letter-spacing:.08em;text-transform:uppercase;white-space:nowrap;color:#596571}
.nww-feed-meta b{font-size:16px;color:#1d2732;margin-right:3px}
.nww-global-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-bottom:1px solid #d7dde2;background:#fff}
.nww-global-strip div{padding:9px 12px;border-right:1px solid #e0e5e9;min-width:0}
.nww-global-strip div:last-child{border-right:0}
.nww-global-strip label{display:block;font-size:8px;letter-spacing:.13em;text-transform:uppercase;color:#687480}
.nww-global-strip strong{display:block;margin-top:3px;font-size:16px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nww-global-strip span{display:block;margin-top:2px;font-size:9px;color:#71808d;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nww-filters{display:grid;grid-template-columns:minmax(220px,1.5fr) repeat(3,minmax(135px,.65fr));gap:8px;padding:10px;border-bottom:1px solid #d7dde2;background:#fff}
.nww-search,.nww-select{width:100%;height:38px;border:1px solid #aeb8c0;border-radius:18px;background:#fff;padding:0 14px;font:inherit;font-size:12px;color:#1d2732;outline:none}
.nww-select{border-radius:7px;padding-right:26px}
.nww-search:focus,.nww-select:focus{border-color:#e84d2a;box-shadow:0 0 0 1px #e84d2a}
.nww-feednote{display:flex;justify-content:space-between;align-items:center;min-height:31px;padding:0 14px;border-bottom:1px solid #d7dde2;background:#f7f9fa;font-size:8px;letter-spacing:.13em;text-transform:uppercase;color:#65717d}
.nww-tablewrap{flex:1;min-height:0;overflow:auto;background:#fff}
.nww-table{width:100%;border-collapse:collapse;table-layout:fixed}
.nww-table thead{position:sticky;top:0;z-index:4;background:#edf2f5}
.nww-table th{height:36px;padding:0 12px;text-align:left;border-bottom:1px solid #d7dde2;font-size:9px;font-weight:500;letter-spacing:.12em;text-transform:uppercase;color:#596673}
.nww-table td{height:55px;padding:7px 12px;border-bottom:1px solid #e0e5e8;vertical-align:middle;font-size:11px;overflow:hidden}
.nww-table tbody tr{cursor:pointer;background:#fff;outline:none}
.nww-table tbody tr:nth-child(even){background:#fafbfc}
.nww-table tbody tr:hover,.nww-table tbody tr:focus{background:#f0f5f7}
.nww-table tbody tr.nww-row-selected{background:#e8f0f4;box-shadow:inset 3px 0 #e84d2a}
.nww-facility{display:flex;align-items:flex-start;min-width:0}
.nww-dot{width:7px;height:7px;border-radius:50%;background:#457c6d;margin:6px 9px 0 0;flex:0 0 auto}
.nww-facility div,.nww-cell,.nww-record{min-width:0}
.nww-facility strong,.nww-cell strong,.nww-record strong{display:block;font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nww-facility small,.nww-cell small,.nww-record small{display:block;margin-top:4px;font-size:8px;letter-spacing:.09em;text-transform:uppercase;color:#687581;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nww-cell span,.nww-record span{display:block;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#53616d}
.nww-status{display:inline-block;max-width:100%;padding:4px 7px;border:1px solid #bdc8cf;border-radius:3px;background:#f7f9fa;font-size:8px;letter-spacing:.09em;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nww-status[data-tone="operating"]{border-color:#9dcbb9;color:#176146;background:#eff8f4}
.nww-status[data-tone="building"]{border-color:#e9bd7f;color:#a64b00;background:#fff8ef}
.nww-status[data-tone="strategic"]{border-color:#e7a39a;color:#a8362c;background:#fff3f1}
.nww-a{padding-bottom:22px}
.nww-head{position:relative;display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:12px;align-items:start;padding:17px 0 14px;border-bottom:1px solid #9fabB4}
.nww-mark{width:8px;height:8px;margin-top:7px;background:#d33f32}
.nww-head h2{margin:0;font-size:19px;line-height:1.25;font-weight:600}
.nww-head p{margin:6px 0 0;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#5c6975}
.nww-head .nww-status{margin-top:1px}
.nww-nav{display:flex;gap:24px;min-height:46px;align-items:end;border-bottom:1px solid #cfd6dc;overflow:auto}
.nww-nav button{height:45px;border:0;border-bottom:2px solid transparent;background:transparent;padding:0;font:inherit;font-size:12px;color:#5a6672;white-space:nowrap;cursor:pointer}
.nww-nav button.active{border-color:#e84d2a;color:#18232e}
.nww-mapwrap{padding:12px;background:#eef4f6;border:1px solid #d3dde2;border-top:0}
.nww-map{position:relative;height:322px;overflow:hidden;background:#d8e6ec;cursor:grab;touch-action:none;outline:none}
.nww-map.is-dragging{cursor:grabbing}
.nww-map-tiles,.nww-map-markers{position:absolute;inset:0;overflow:hidden}
.nww-map-tiles img{position:absolute;width:256px;height:256px;max-width:none;user-select:none}
.nww-map-offline{position:absolute;inset:0;display:none;place-items:center;background:#e7eef1;color:#64727d;font-size:11px;letter-spacing:.08em;text-transform:uppercase}
.nww-map-marker{position:absolute;width:13px;height:13px;transform:translate(-50%,-50%);padding:0;border:2px solid #fff;border-radius:50%;background:#536b7c;box-shadow:0 0 0 1px rgba(23,39,52,.6);cursor:pointer;z-index:2}
.nww-map-marker.is-selected{width:20px;height:20px;background:#e84d2a;box-shadow:0 0 0 2px #fff,0 0 0 3px #a93b2a;z-index:4}
.nww-map-marker span{display:none;position:absolute;left:15px;top:-13px;width:185px;padding:6px 7px;border:1px solid #8997a2;background:rgba(255,255,255,.97);font-size:9px;line-height:1.35;text-align:left;color:#17232d;pointer-events:none}
.nww-map-marker:hover span,.nww-map-marker:focus span,.nww-map-marker.is-selected span{display:block}
.nww-map-marker.nww-label-left span{left:auto;right:15px}
.nww-map-label{position:absolute;top:12px;left:12px;z-index:5;max-width:72%;padding:6px 8px;border:1px solid #aab7bf;background:rgba(255,255,255,.95);font-size:9px;line-height:1.35}
.nww-map-controls{position:absolute;top:12px;right:12px;z-index:6;display:flex;gap:4px}
.nww-map-controls button{height:32px;min-width:32px;padding:0 8px;border:1px solid #9aa8b2;border-radius:4px;background:#fff;font:inherit;font-size:16px;cursor:pointer}
.nww-map-controls .nww-home{font-size:9px;text-transform:uppercase}
.nww-map-key{position:absolute;left:12px;bottom:12px;z-index:5;padding:5px 8px;background:rgba(255,255,255,.94);font-size:8px;letter-spacing:.06em;text-transform:uppercase}
.nww-map-key i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#e84d2a;margin-right:5px}
.nww-map-attrib{position:absolute;right:5px;bottom:4px;z-index:5;background:rgba(255,255,255,.85);font-size:7px;color:#293744;text-decoration:none}
.nww-section{margin-top:13px}
.nww-sechead{display:flex;justify-content:space-between;align-items:center;min-height:30px;border-bottom:1px solid #cfd6dc;font-size:9px;letter-spacing:.12em;text-transform:uppercase}
.nww-sechead b{font-weight:600}.nww-sechead span{font-size:8px;color:#65727d}
.nww-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid #d4dbe0;border-top:0}
.nww-kpi{min-height:77px;padding:11px 12px;border-right:1px solid #d4dbe0;min-width:0}.nww-kpi:last-child{border-right:0}
.nww-kpi label,.nww-fact label{display:block;font-size:8px;letter-spacing:.12em;text-transform:uppercase;color:#66737f}
.nww-kpi strong{display:block;margin-top:7px;font-size:17px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nww-kpi span{display:block;margin-top:4px;font-size:8px;color:#687582;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nww-source-card,.nww-brief{padding:13px 14px;border:1px solid #d5dde2;background:#f7f9fa}
.nww-source-top{display:flex;justify-content:space-between;gap:12px;margin-bottom:9px;font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:#c83c2d}
.nww-source-card p,.nww-brief p{margin:0;font-size:13px;line-height:1.48}.nww-source-card a{color:#0758aa;text-decoration:none;white-space:nowrap}
.nww-brief{border-left:2px solid #0d67ad;background:#f2f6f8}.nww-brief label{display:block;margin-bottom:7px;font-size:8px;letter-spacing:.12em;text-transform:uppercase;color:#0758aa}
.nww-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border:1px solid #d5dde2;border-top:0}
.nww-fact{min-height:68px;padding:11px 12px;border-right:1px solid #d5dde2;border-bottom:1px solid #d5dde2;min-width:0}.nww-fact:nth-child(2n){border-right:0}.nww-fact:nth-last-child(-n+2){border-bottom:0}
.nww-fact strong{display:block;margin-top:7px;font-size:12px;font-weight:500;line-height:1.4;overflow-wrap:anywhere}
.nww-bars{padding:10px 12px;border:1px solid #d5dde2;border-top:0}.nww-bar{display:grid;grid-template-columns:120px 1fr 28px;gap:9px;align-items:center;margin:8px 0;font-size:9px}.nww-bar label{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.nww-track{height:6px;background:#e5eaed}.nww-track i{display:block;height:100%;background:#657c8b}.nww-bar:first-child .nww-track i{background:#e84d2a}.nww-bar b{text-align:right;font-weight:600}
.nww-list{border:1px solid #d5dde2;border-top:0}.nww-list-row{display:grid;grid-template-columns:145px 1fr;gap:14px;padding:11px 12px;border-bottom:1px solid #dde3e7}.nww-list-row:last-child{border-bottom:0}.nww-list-row label{font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:#65727d}.nww-list-row span{font-size:12px;line-height:1.4}
.nww-reserve{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid #d5dde2;border-top:0}.nww-reserve div{padding:12px;border-right:1px solid #d5dde2}.nww-reserve div:last-child{border-right:0}.nww-reserve label{display:block;font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:#65727d}.nww-reserve strong{display:block;margin-top:6px;font-size:17px}.nww-reserve span{display:block;margin-top:3px;font-size:8px;color:#687582}
.nww-method{margin-top:14px;border-top:1px solid #d2dae0;border-bottom:1px solid #d2dae0;padding:9px 0}.nww-method summary{cursor:pointer;font-size:9px;letter-spacing:.11em;text-transform:uppercase}.nww-method p{font-size:10px;line-height:1.5;color:#596671}
.nww-actions{display:flex;align-items:center;gap:12px;margin-top:13px}.nww-ai{border:0;border-radius:4px;background:#202f3a;color:#fff;padding:10px 15px;font:inherit;font-size:11px;cursor:pointer}.nww-method-note{font-size:8px;color:#687581}
.nww-drop-ready{outline:2px dashed #e84d2a;outline-offset:-5px}.nww-drag-source{opacity:.55}
@media(max-width:1250px){.nww-filters{grid-template-columns:1fr 1fr}.nww-global-strip{grid-template-columns:repeat(2,1fr)}.nww-kpis{grid-template-columns:repeat(2,1fr)}.nww-kpi:nth-child(2){border-right:0}.nww-kpi:nth-child(-n+2){border-bottom:1px solid #d4dbe0}}
